text_nat:
WHITESPACE = " \t\n\r"
PUNCTUATION = ".,;:!?'\"-()[]"
SKIPPED = WHITESPACE + PUNCTUATION
VOWELS = "aeiouAEIOU"


def reverse_string(s):
    """Return the characters of s in reverse order."""
    if not isinstance(s, str):
        raise TypeError("reverse_string expects a string")
    chars = []
    for index in range(len(s) - 1, -1, -1):
        chars.append(s[index])
    return "".join(chars)


def tokenize(s):
    """Split s into words on any run of whitespace."""
    words = []
    current = []
    for ch in s:
        if ch not in WHITESPACE:
            current.append(ch)
        elif current:
            words.append("".join(current))
            current = []
    if current:
        words.append("".join(current))
    return words


def normalize(s):
    """Lowercase s and drop spacing and punctuation for comparisons."""
    kept = []
    for ch in s:
        if ch not in SKIPPED:
            kept.append(ch.lower())
    return "".join(kept)


def unique(samples):
    """Keep the first occurrence of each sample, preserving order."""
    seen = []
    for sample in samples:
        if sample not in seen:
            seen.append(sample)
    return seen


def consonant_skeleton(s):
    """The reversed string with vowels removed, a rough fingerprint."""
    letters = []
    for ch in reverse_string(normalize(s)):
        if ch not in VOWELS:
            letters.append(ch)
    return "".join(letters)


def group_by_skeleton(samples):
    """Map each consonant skeleton to the samples that produce it."""
    groups = {}
    for sample in samples:
        key = consonant_skeleton(sample)
        if key not in groups:
            groups[key] = []
        groups[key].append(sample)
    return groups


def is_palindrome(s):
    cleaned = normalize(s)
    return cleaned == reverse_string(cleaned)


def reverse_words(s):
    """Reverse the order of the words while keeping each word intact."""
    words = tokenize(s)
    return " ".join(words[index] for index in range(len(words) - 1, -1, -1))


def report(samples):
    lines = []
    wanted = unique(samples)
    for sample in wanted:
        line = repr(sample) + " -> " + repr(reverse_string(sample))
        if is_palindrome(sample):
            line = line + " [palindrome]"
        elif len(tokenize(sample)) > 1:
            line = line + " [words reversed: " + reverse_words(sample) + "]"
        lines.append(line)
    for key, members in sorted(group_by_skeleton(wanted).items()):
        if len(members) > 1:
            lines.append("shared skeleton " + repr(key) + ": " + ", ".join(members))
    return "\n".join(lines)


def main():
    samples = [
        "hello",
        "Python",
        "A man, a plan, a canal: Panama",
        "never odd or even",
        "reverse each word here",
        "hello",
    ]
    print(report(samples))


if __name__ == "__main__":
    main()

