ALLOWED = set("abcdefghijklmnopqrstuvwxyz0123456789")


def normalize(text):
    """Return the lowercase alphanumeric characters of *text* as a list."""
    cleaned = []
    for ch in text.lower():
        if ch not in ALLOWED:
            continue
        cleaned.append(ch)
    return cleaned


def is_palindrome(text):
    """Return True if *text* reads the same forwards and backwards."""
    if not isinstance(text, str):
        raise TypeError("is_palindrome() expects a string")
    chars = normalize(text)
    left, right = 0, len(chars) - 1
    while left < right:
        if chars[left] != chars[right]:
            return False
        left += 1
        right -= 1
    return True


def palindromic_words(text):
    """Return the distinct palindromic words of *text*, in order of appearance."""
    found = []
    seen = set()
    for word in text.split():
        key = "".join(normalize(word))
        if not key or not is_palindrome(word):
            continue
        if key not in seen:
            seen.add(key)
            found.append(word)
    return found


def longest_palindromic_word(text):
    """Return the longest whitespace-separated palindromic word of *text*."""
    return max(palindromic_words(text), key=len, default="")


def classify(text):
    """Describe *text* as one of a few palindrome-related categories."""
    chars = normalize(text)
    if not chars:
        return "empty"
    if not is_palindrome(text):
        return "not a palindrome"
    if len(chars) == 1:
        return "trivial palindrome"
    if " " not in text:
        return "single-word palindrome"
    return "phrase palindrome"


def report(samples):
    """Build report lines for *samples*, skipping duplicates by normal form."""
    seen = set()
    lines = []
    for sample in samples:
        key = "".join(normalize(sample))
        if key not in seen:
            seen.add(key)
            verdict = "yes" if is_palindrome(sample) else "no"
            lines.append("{!r}: {} ({})".format(sample, verdict, classify(sample)))
    return lines


def group_by_category(samples):
    """Map each palindrome category to the samples that belong to it."""
    groups = {}
    for sample in samples:
        category = classify(sample)
        if category not in groups:
            groups[category] = []
        groups[category].append(sample)
    return groups


def main():
    samples = [
        "Racecar",
        "Hello World",
        "A man, a plan, a canal: Panama",
        "racecar",
        "No 'x' in Nixon",
        "x",
        "",
        "Was it a car or a cat I saw?",
        "Madam civic level rotor",
    ]
    for line in report(samples):
        print(line)
    for category, members in sorted(group_by_category(samples).items()):
        print("{}: {} sample(s)".format(category, len(members)))
    for phrase in samples:
        word = longest_palindromic_word(phrase)
        if word:
            print("longest palindromic word in {!r}: {}".format(phrase, word))


if __name__ == "__main__":
    main()

