text_nat:
NUMERIC_TYPES = (int, float)
SEPARATORS = ",;|"
ALLOWED_CHARS = set("0123456789+-.eE")
LEADING_CHARS = set("0123456789+-.")


def sum_list(numbers):
    """Return the sum of a list of numbers (0 for an empty list)."""
    total = 0
    for value in numbers:
        if type(value) not in NUMERIC_TYPES:
            raise TypeError("not a number: {0!r}".format(value))
        total += value
    return total


def parse_numbers(text):
    """Turn a line such as '1, 2; 3' into [1, 2, 3], keeping ints as ints."""
    for separator in SEPARATORS:
        text = text.replace(separator, " ")
    numbers = []
    for token in text.split():
        for character in token:
            if character not in ALLOWED_CHARS:
                raise ValueError("bad character {0!r} in {1!r}".format(character, token))
        if token[0] not in LEADING_CHARS:
            raise ValueError("number cannot start with {0!r}".format(token[0]))
        lowered = token.lower()
        if "." in lowered or "e" in lowered:
            numbers.append(float(token))
        else:
            numbers.append(int(token))
    return numbers


def read_entries(block):
    """Read 'label: 1, 2, 3' lines into (label, numbers) pairs."""
    entries = []
    for line in block.splitlines():
        if not line.strip():
            continue
        if ":" not in line:
            raise ValueError("missing label in {0!r}".format(line))
        label, _, values = line.partition(":")
        entries.append((label.strip(), parse_numbers(values)))
    return entries


def mean_list(numbers):
    """Arithmetic mean, or None when there is nothing to average."""
    if not numbers:
        return None
    return sum_list(numbers) / len(numbers)


def collect(entries):
    """Summarize (label, numbers) pairs, merging repeated labels."""
    rows = []
    positions = {}
    for label, numbers in entries:
        if label not in positions:
            positions[label] = len(rows)
            rows.append({"label": label, "count": len(numbers),
                         "total": sum_list(numbers), "mean": mean_list(numbers)})
            continue
        row = rows[positions[label]]
        row["count"] += len(numbers)
        row["total"] += sum_list(numbers)
        row["mean"] = row["total"] / row["count"] if row["count"] else None
    return rows


def format_report(rows):
    """Render rows produced by collect() as aligned text lines."""
    width = max([len(row["label"]) for row in rows] + [5])
    lines = []
    for row in rows:
        average = "n/a" if row["mean"] is None else "{0:.2f}".format(row["mean"])
        lines.append("{0:<{1}} n={2:<3} sum={3:<8} mean={4}".format(
            row["label"], width, row["count"], row["total"], average))
    return "\n".join(lines)


def main():
    block = "basic: 1, 2, 3, 4\nempty:\nfloats: 0.5; 1.5 | 2e1\nbasic: 10 20\n"
    print(format_report(collect(read_entries(block))))


if __name__ == "__main__":
    main()

