ALLOWED_NAME_CHARS = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ -'"
GRADE_CUTOFFS = ((90.0, "A"), (80.0, "B"), (70.0, "C"), (60.0, "D"))
PASSING_GRADES = ("A", "B", "C", "D")


def calculate_average(numbers):
    if not numbers:
        return 0
    return sum(numbers) / len(numbers)


def parse_line(line):
    if ":" not in line:
        raise ValueError("entry needs a ':' separator: %r" % line)
    raw_name, _, raw_scores = line.partition(":")
    name = raw_name.strip()
    if not name:
        raise ValueError("entry has an empty name: %r" % line)
    for char in name:
        if char not in ALLOWED_NAME_CHARS:
            raise ValueError("illegal character %r in name %r" % (char, name))
    scores = []
    for token in raw_scores.split(","):
        token = token.strip()
        if not token:
            continue
        try:
            scores.append(float(token))
        except ValueError:
            raise ValueError("score %r for %s is not a number" % (token, name))
    return name, scores


def build_records(lines):
    records = {}
    for line in lines:
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        name, scores = parse_line(line)
        if name not in records:
            records[name] = []
        records[name].extend(scores)
    return records


def letter_grade(average):
    for cutoff, letter in GRADE_CUTOFFS:
        if average >= cutoff:
            return letter
    return "F"


def summarize(records):
    summary = {}
    for name, scores in records.items():
        average = calculate_average(scores)
        summary[name] = (average, letter_grade(average))
    return summary


def failing_students(summary):
    return sorted(name for name, (_, letter) in summary.items()
                  if letter not in PASSING_GRADES)


def student_summary(summary, name):
    if name not in summary:
        return "%s: no records found" % name
    average, letter = summary[name]
    return "%s: average %.1f (%s)" % (name, average, letter)


def format_report(summary):
    lines = ["%-10s %8s %6s" % ("STUDENT", "AVERAGE", "GRADE")]
    for name in sorted(summary):
        average, letter = summary[name]
        lines.append("%-10s %8.1f %6s" % (name, average, letter))
    return "\n".join(lines)


def main():
    raw_lines = [
        "# name: scores",
        "Alice: 10, 20, 30",
        "Bob: 95, 88",
        "Alice: 90",
        "Cara:",
        "Dan: 55, 61, 40",
    ]
    summary = summarize(build_records(raw_lines))
    print(format_report(summary))
    print("Failing:", ", ".join(failing_students(summary)) or "none")
    for name in ("Cara", "Zoe"):
        print(student_summary(summary, name))


if __name__ == "__main__":
    main()

