def remove_duplicates(items):
    """Return a new list with duplicates removed, keeping first occurrences."""
    seen = set()
    unhashable = []
    result = []
    for item in items:
        try:
            if item not in seen:
                seen.add(item)
                result.append(item)
        except TypeError:
            if item not in unhashable:
                unhashable.append(item)
                result.append(item)
    return result


def remove_duplicates_by(items, key):
    """Remove duplicates by comparing key(item) instead of the item itself."""
    seen_keys = []
    result = []
    for item in items:
        k = key(item)
        if k not in seen_keys:
            seen_keys.append(k)
            result.append(item)
    return result


def duplicate_counts(items):
    """Map each repeated value to how many extra times it appeared."""
    counts = {}
    for item in items:
        if item not in counts:
            counts[item] = 0
        else:
            counts[item] += 1
    return {value: extra for value, extra in counts.items() if extra}


def describe(items):
    """Build a short human readable report about the deduplication."""
    unique = remove_duplicates(items)
    lines = ["input:  %r" % (items,), "unique: %r" % (unique,)]
    try:
        extras = duplicate_counts(items)
    except TypeError:
        extras = {}
        lines.append("(values are unhashable, counts skipped)")
    for value in unique:
        if value not in extras:
            continue
        lines.append("  %r repeated %d extra time(s)" % (value, extras[value]))
    return "\n".join(lines)


def main():
    samples = [
        [1, 2, 2, 3, 1, 4],
        ['a', 'b', 'a'],
        [],
        [3, 3, 3, 3],
        [1, '1', 1.0, True, None, None],
        [[1, 2], [1, 2], [3], {'x': 1}, {'x': 1}],
    ]
    for sample in samples:
        print(describe(sample))
        print("-" * 40)

    words = ["Apple", "apple", "BANANA", "banana", "Cherry"]
    folded = remove_duplicates_by(words, key=str.lower)
    print("case-insensitive unique words: %r" % (folded,))
    for word in words:
        if word not in folded:
            print("  dropped as a case variant: %s" % word)


if __name__ == "__main__":
    main()

