    '+': lambda a, b: a + b,
    '-': lambda a, b: a - b,
    '*': lambda a, b: a * b,
    '/': lambda a, b: 'Error' if b == 0 else a / b,
}
ALIASES = {'x': '*', 'X': '*', ':': '/'}
NUMBER_CHARS = '0123456789.eE'


def simple_calculator(num1, operator, num2):
    """Apply a basic arithmetic operator to two numbers."""
    if operator not in OPERATIONS:
        return 'Error'
    if not isinstance(num1, (int, float)) or not isinstance(num2, (int, float)):
        return 'Error'
    return OPERATIONS[operator](num1, num2)


def normalize_operator(symbol):
    """Map typed variants such as 'x' or ':' onto the canonical operators."""
    if symbol not in ALIASES:
        return symbol
    return ALIASES[symbol]


def is_symbol(char):
    """Report whether a character separates the two operands."""
    return not char.isspace() and char not in NUMBER_CHARS


def parse_number(text):
    """Turn a numeric string into an int when possible, else a float."""
    text = text.strip()
    if '.' not in text:
        lowered = text.lower()
        if 'e' not in lowered:
            try:
                return int(text)
            except ValueError:
                return None
    try:
        return float(text)
    except ValueError:
        return None


def tokenize(line):
    """Split an expression into pieces, even without spaces around the operator."""
    tokens = []
    current = ''
    for char in line:
        if not is_symbol(char):
            current += char
            continue
        if current.strip() == '' and char in '+-':
            if not tokens or tokens[-1] in OPERATIONS:
                current = char
                continue
        tokens.append(current.strip())
        tokens.append(normalize_operator(char))
        current = ''
    tokens.append(current.strip())
    return [token for token in tokens if token != '']


def parse_expression(line):
    """Split 'a op b' into its three parts, returning None if malformed."""
    tokens = tokenize(line)
    if len(tokens) != 3:
        return None
    left, operator, right = tokens
    if operator not in OPERATIONS:
        return None
    num1 = parse_number(left)
    num2 = parse_number(right)
    if num1 is None or num2 is None:
        return None
    return num1, operator, num2


def format_result(value):
    """Render a calculator result for display."""
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value)


def evaluate_line(line):
    """Evaluate a single textual expression, reporting parse problems."""
    expression = parse_expression(line)
    if expression is None:
        return 'Error'
    return format_result(simple_calculator(*expression))


def main():
    expressions = ['10 + 5', '10 / 0', '7x6', '2.5 - 1', '9 / 4',
                   '4 * -2', '3 ^ 2', 'abc + 1']
    for line in expressions:
        print('{:>10} = {}'.format(line, evaluate_line(line)))


if __name__ == '__main__':
    main()

