ABSOLUTE_ZERO_C = -273.15
LABELS = ("freezing", "cold", "mild", "warm", "hot")


def describe(celsius):
    """Return a short label for a Celsius temperature."""
    if celsius <= 0:
        return LABELS[0]
    if celsius < 15:
        return LABELS[1]
    if celsius < 25:
        return LABELS[2]
    if celsius < 35:
        return LABELS[3]
    return LABELS[4]


def parse_celsius(text):
    """Read a Celsius value from a string like '25', '-3.5C' or '12 c'."""
    cleaned = text.strip().replace(" ", "")
    if not cleaned:
        raise ValueError("empty temperature")
    suffix = cleaned[-1]
    if suffix.isalpha():
        if suffix not in "cC":
            raise ValueError("unsupported scale %r in %r" % (suffix, text))
        cleaned = cleaned[:-1]
    for char in cleaned:
        if char not in "0123456789+-.":
            raise ValueError("invalid character %r in %r" % (char, text))
    if "." not in cleaned:
        return int(cleaned)
    return float(cleaned)


def celsius_to_fahrenheit(celsius):
    """Convert a Celsius temperature to Fahrenheit."""
    if isinstance(celsius, bool) or not isinstance(celsius, (int, float)):
        raise TypeError("celsius must be a real number")
    if celsius < ABSOLUTE_ZERO_C:
        raise ValueError("temperature below absolute zero")
    return celsius * 9 / 5 + 32


def build_report(values, labels=None):
    """Convert every value, keeping only the labels that were requested."""
    if labels is not None:
        for wanted in labels:
            if wanted not in LABELS:
                raise ValueError("unknown label %r" % (wanted,))
    lines = []
    for text in values:
        row = format_row(text)
        if labels is not None:
            found = row.rsplit("(", 1)[-1].rstrip(")")
            if found not in labels:
                continue
        if row not in lines:
            lines.append(row)
    return "\n".join(lines)


def format_row(text):
    """Format one input value as a report line, or an error line."""
    try:
        celsius = parse_celsius(text)
        fahrenheit = celsius_to_fahrenheit(celsius)
    except (TypeError, ValueError) as exc:
        return "%-10s -> error: %s" % (text.strip(), exc)
    return "%8.2f C = %8.2f F  (%s)" % (celsius, fahrenheit, describe(celsius))


def main():
    samples = ["0", "25", "-40", "100 C", "36.6c", "", "12f", "-500"]
    print("All readings")
    print(build_report(samples))
    print()
    print("Only mild or warm readings")
    print(build_report(samples, labels={"mild", "warm"}))


if __name__ == "__main__":
    main()

