def list_intersection(list1, list2):
    """Return the elements of list1 that also occur in list2, without duplicates.

    Membership is tested with ``in``, so the lists may hold unhashable values
    such as other lists or dictionaries.
    """
    result = []
    for item in list1:
        if not item in list2:
            continue
        if not item in result:
            result.append(item)
    return result


def list_difference(list1, list2):
    """Return the elements of list1 that are absent from list2, without duplicates."""
    result = []
    for item in list1:
        if not item in list2:
            if not item in result:
                result.append(item)
    return result


def list_union(list1, list2):
    """Return every value of both lists, in first-seen order and without duplicates."""
    result = []
    for item in list(list1) + list(list2):
