LOWER = "abcdefghijklmnopqrstuvwxyz"
UPPER = LOWER.upper()
DIGITS = "0123456789"
COMMON_WORDS = {"the", "and", "attack", "dawn", "hello", "world", "secret", "at"}


def _shift_letter(ch, shift):
    if ch not in LOWER:
        if ch not in UPPER:
            return ch
        return UPPER[(UPPER.index(ch) + shift) % 26]
    return LOWER[(LOWER.index(ch) + shift) % 26]


def caesar_cipher_encrypt(text, shift):
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if not isinstance(shift, int) or isinstance(shift, bool):
        raise TypeError("shift must be an integer")
    return "".join(_shift_letter(ch, shift) for ch in text)


def caesar_cipher_decrypt(text, shift):
    return caesar_cipher_encrypt(text, -shift)


def parse_shift(raw):
    cleaned = raw.strip()
    if not cleaned:
        raise ValueError("shift is empty")
    sign = 1
    if cleaned[0] in "+-":
        sign = -1 if cleaned[0] == "-" else 1
        cleaned = cleaned[1:]
    for ch in cleaned:
        if ch not in DIGITS:
            raise ValueError("invalid shift: %r" % raw)
    return sign * int(cleaned)


def passthrough_chars(text):
