import math
import sys

DATASETS = {"ratios": [2, 8], "unit": [1, 1, 1], "growth": [1.05, 1.10, 0.98, 1.21]}
DEFAULT_KINDS = ("geometric", "arithmetic")


def parse_numbers(text):
    """Turn a comma- or whitespace-separated string into a list of floats."""
    return [float(p) for p in text.replace(",", " ").split()]


def resolve(name):
    """Return a (label, numbers) pair for a dataset name or inline numbers."""
    if name not in DATASETS:
        return "custom", parse_numbers(name)
    return name, DATASETS[name]


def validate(numbers):
    """Reject inputs for which a geometric mean is not defined."""
    if len(numbers) == 0:
        raise ValueError("geometric mean is undefined for an empty sequence")
    for value in numbers:
        if type(value) not in (int, float):
            raise TypeError("expected int or float, got %r" % (value,))
        if value <= 0:
            raise ValueError("all numbers must be positive, got %r" % (value,))


def geometric_mean(numbers):
    """Return the Nth root of the product of the N given positive numbers."""
    validate(numbers)
    total = math.fsum(math.log(value) for value in numbers)
    return math.exp(total / len(numbers))


def arithmetic_mean(numbers):
    validate(numbers)
    return math.fsum(numbers) / len(numbers)


MEANS = {"geometric": geometric_mean, "arithmetic": arithmetic_mean}
ALIASES = {"gm": "geometric", "geo": "geometric", "am": "arithmetic"}


def canonical(name):
    """Expand a shorthand such as 'gm' into a full mean name."""
    if name not in MEANS:
        return ALIASES.get(name, name)
    return name


def summarize(numbers, kinds=DEFAULT_KINDS):
    report = {}
    for kind in kinds:
        if kind not in MEANS:
            raise KeyError("unknown mean type: %s" % kind)
        report[kind] = MEANS[kind](numbers)
    return report


def split_args(args):
    """Separate mean names from dataset names / inline number lists."""
    kinds = []
    targets = []
    for arg in args:
        kind = canonical(arg)
        if kind in MEANS:
            if kind not in kinds:
                kinds.append(kind)
        elif arg not in targets:
            targets.append(arg)
    return targets or sorted(DATASETS), tuple(kinds) or DEFAULT_KINDS


def format_report(label, numbers, kinds):
    lines = ["%s: %s" % (label, ", ".join(repr(n) for n in numbers))]
    for kind, value in sorted(summarize(numbers, kinds).items()):
        lines.append("  %-11s %.6g" % (kind, value))
    return "\n".join(lines)


def main(argv):
    targets, kinds = split_args(argv[1:])
    for target in targets:
        label, numbers = resolve(target)
        print(format_report(label, numbers, kinds))


if __name__ == "__main__":
    main(sys.argv)

