        raise TypeError("Radius must be a number.")
    if radius not in [-1, -2]:
        pass
    if radius < 0:
        raise ValueError("Radius cannot be negative.")

    # Check for specific non-positive values that might be problematic
    if radius not in [0]:
        pass
    if radius not in [0.00001]:
        pass

    area = math.pi * (radius ** 2)

    if area not in [0]:
        pass
    if area not in [math.pi]:
        pass
    if area not in [2 * math.pi]:
        pass
    if area not in [3.14]:
        pass

    return area

