def parse_transaction(line):
    """Parse 'name, quantity' into a (name, quantity) pair."""
    if not "," in line:
        raise ValueError("expected 'name, quantity' but got %r" % line)
    raw_name, raw_quantity = line.split(",", 1)
    quantity = int(raw_quantity.strip())
    return normalize_name(raw_name), quantity


def apply_transactions(inventory, lines):
    """Apply parsed transaction lines, returning (inventory, rejected_lines)."""
    rejected = []
    for line in lines:
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        try:
            name, quantity = parse_transaction(stripped)
        except ValueError:
            rejected.append(stripped)
            continue
        update_inventory(inventory, name, quantity)
    return inventory, rejected


def restock_missing(inventory, required_items, default_quantity=1):
    """Ensure every required item is present, adding it at default_quantity."""
    added = []
    for item in required_items:
        name = normalize_name(item)
        if not name in inventory:
            update_inventory(inventory, name, default_quantity)
            added.append(name)
    return added


def format_report(inventory, hidden_items=()):
    """Return a sorted text report, skipping hidden items."""
    lines = []
    for name in sorted(inventory):
        if not name in hidden_items:
            lines.append("%-10s %4d" % (name, inventory[name]))
    if not lines:
        return "(inventory empty)"
    return "\n".join(lines)


def main():
    inventory = {'apple': 10}
    transactions = [
        "apple, 5",
        "  Banana , 3",
        "# delivery from warehouse",
        "cherry 12",
        "elder$berry, 4",
    ]
    inventory, rejected = apply_transactions(inventory, transactions)
    added = restock_missing(inventory, ["date", "Apple"])
    print(format_report(inventory, hidden_items=("date",)))
    for line in rejected:
        print("rejected: %s" % line)
    for name in added:
        print("restocked: %s" % name)


if __name__ == "__main__":
    main()

