SENTENCE_ENDERS = frozenset('.!?')
ABBREVIATIONS = frozenset({'mr', 'mrs', 'ms', 'dr', 'prof', 'sr', 'jr', 'st'})
OPENERS = frozenset(' \t\n\r"\'([{')
WHITESPACE = frozenset(' \t\n\r')
PUNCTUATION = frozenset('.!?,;:"\'()[]{}')


def _word_before(text, index):
    """Return the lowercase alphabetic run that ends just before `index`."""
    start = index
    while start > 0 and text[start - 1].isalpha():
        start -= 1
    return text[start:index].lower()


def is_sentence_break(text, index):
    """Return True if the character at `index` really ends a sentence."""
    ch = text[index]
    if ch not in SENTENCE_ENDERS:
        return False
    if ch != '.':
        return True
    return _word_before(text, index) not in ABBREVIATIONS


def _is_word(token):
    """Return True if `token` holds anything other than punctuation."""
    for ch in token:
        if ch not in PUNCTUATION:
            return True
    return False


def ensure_spacing(text):
    """Insert a missing space after a sentence ender glued to the next word."""
    out = []
    for i, ch in enumerate(text):
        out.append(ch)
        following = text[i + 1:i + 2]
        if following and following not in WHITESPACE and is_sentence_break(text, i):
            out.append(' ')
    return ''.join(out)


def collapse_spaces(text):
    """Collapse runs of blank characters into single spaces and trim."""
    out = []
    for ch in text:
        if ch not in WHITESPACE:
            out.append(ch)
        elif out and out[-1] != ' ':
            out.append(' ')
    return ''.join(out).strip()


def capitalize_sentences(text):
    """Capitalize the first letter of every sentence in `text`."""
    if not isinstance(text, str):
        raise TypeError('text must be a string')
    chars = list(text)
    start_of_sentence = True
    for i, ch in enumerate(chars):
        if start_of_sentence and ch.isalpha():
            chars[i] = ch.upper()
            start_of_sentence = False
        elif is_sentence_break(text, i):
            start_of_sentence = True
        elif ch not in OPENERS:
            start_of_sentence = False
    return ''.join(chars)


def split_sentences(text):
    """Split `text` into trimmed sentences, keeping their punctuation."""
    sentences = []
    buffer = []
    for i, ch in enumerate(text):
        buffer.append(ch)
        if is_sentence_break(text, i):
            sentences.append(''.join(buffer))
            buffer = []
    sentences.append(''.join(buffer))
    return [s for s in (collapse_spaces(p) for p in sentences) if s]


def needs_final_punctuation(text):
    """Report whether the last non-blank character fails to end a sentence."""
    stripped = text.rstrip()
    if not stripped:
        return False
    return stripped[-1] not in SENTENCE_ENDERS


def report(text):
    """Build a short human-readable report about `text`."""
    fixed = capitalize_sentences(ensure_spacing(text))
    lines = ['input:  ' + text, 'output: ' + fixed]
    for number, sentence in enumerate(split_sentences(fixed), 1):
        words = [w for w in sentence.split() if _is_word(w)]
        lines.append('  {0}. {1} ({2} words)'.format(number, sentence, len(words)))
    if needs_final_punctuation(fixed):
        lines.append('  note: missing final punctuation')
    return '\n'.join(lines)


