    samples = [
        'hello world. how are you?',
        'python rocks!',
        'dr. smith arrived late.he apologized',
        '  "what now?" she asked. nobody knew!',
    ]
    for sample in samples:
        print(report(sample))
        print('-' * 40)


if __name__ == '__main__':
    main()

