import re

HASHTAG_RE = re.compile(r"#(\w+)")
STOP_TAGS = {"ad", "sponsored", "spam"}


def extract_hashtags(text):
    """Return every hashtag found in text, without the leading '#'."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    return HASHTAG_RE.findall(text)


def unique_hashtags(text):
    """Hashtags in order of first appearance, compared case-insensitively."""
    seen = set()
    result = []
    for tag in extract_hashtags(text):
        key = tag.lower()
        if key not in seen:
            seen.add(key)
            result.append(tag)
    return result


def filter_hashtags(text, blocked=STOP_TAGS):
    """Drop promotional tags and anything that is purely numeric."""
    kept = []
    for tag in unique_hashtags(text):
        if tag.lower() not in blocked and not tag.isdigit():
            kept.append(tag)
    return kept


def tag_index(texts):
    """Map each lowercase hashtag to the numbers of the texts mentioning it."""
    index = {}
    for number, text in enumerate(texts, start=1):
        for tag in unique_hashtags(text):
            key = tag.lower()
            if key not in index:
                index[key] = []
            index[key].append(number)
    return index


def hashtag_counts(texts):
    """Map each lowercase hashtag to how many of the given texts mention it."""
    return {tag: len(numbers) for tag, numbers in tag_index(texts).items()}


def trending(texts, minimum=2):
    """Tags mentioned in at least `minimum` texts, most frequent first."""
    counts = hashtag_counts(texts)
    hot = [(tag, n) for tag, n in counts.items() if n >= minimum and tag not in STOP_TAGS]
    hot.sort(key=lambda pair: (-pair[1], pair[0]))
    return hot


def report(texts):
    """Build a human readable summary, marking each tag's first appearance."""
    lines = []
    seen = set()
    for index, text in enumerate(texts, start=1):
        shown = []
        for tag in filter_hashtags(text):
            key = tag.lower()
            if key not in seen:
                seen.add(key)
                shown.append(tag + " (new)")
            else:
                shown.append(tag)
        lines.append("%d: %s" % (index, ", ".join(shown) if shown else "(no hashtags)"))
    hot = trending(texts)
    if hot:
        lines.append("trending: " + ", ".join("%s(%d)" % pair for pair in hot))
    else:
        lines.append("trending: none")
    return "\n".join(lines)


def main():
    posts = [
        "This is a #test with #python.",
        "No hashtags here.",
        "Learning #Python and #django, #sponsored though",
        "Numbers like #2024 are skipped, but #python stays",
    ]
    print(report(posts))
    counts = hashtag_counts(posts)
    missing = [tag for tag in ("python", "rust") if tag not in counts]
    print("never mentioned: " + (", ".join(missing) if missing else "nothing"))


if __name__ == "__main__":
    main()

