"""Squares of the integers from 1 to n, plus helpers built on top of them."""

DIGITS = "0123456789"
_CACHE = {}


def parse_count(text):
    """Turn user input such as ' 7 ' into the integer 7."""
    cleaned = text.strip()
    if not cleaned:
        raise ValueError("no number given")
    for char in cleaned:
        if char not in DIGITS:
            raise ValueError("not a non-negative integer")
    return int(cleaned)


def list_of_squares(n):
    """Return [1, 4, 9, ...] up to n*n; an empty list when n <= 0."""
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("n must be an int")
    if n < 1:
        return []
    if n not in _CACHE:
        _CACHE[n] = [i * i for i in range(1, n + 1)]
    return list(_CACHE[n])


def missing_squares(values, n):
    """Squares up to n that do not appear in values."""
    seen = set(values)
    result = []
    for square in list_of_squares(n):
        if square not in seen:
            result.append(square)
    return result


def stray_values(values, n):
    """Entries of values that are not squares of 1..n."""
    squares = set(list_of_squares(n))
    result = []
    for value in values:
        if value not in squares:
            result.append(value)
    return result


def squares_table(limits):
    """Map each distinct limit to its list of squares."""
    table = {}
    for limit in limits:
        if limit not in table:
            table[limit] = list_of_squares(limit)
    return table


def format_row(limit, squares):
    """Render one line of the report."""
    body = ", ".join(str(square) for square in squares) if squares else "-"
    return "n={:<3d} -> [{}]".format(limit, body)


def report(limits):
    """Build a human-readable report for several limits."""
    table = squares_table(limits)
    return "\n".join(format_row(limit, table[limit]) for limit in sorted(table))


def main():
    raw_inputs = ["3", "0", " 5 ", "3", "four"]
    limits = []
    for raw in raw_inputs:
        try:
            limits.append(parse_count(raw))
        except ValueError as exc:
            print("skipping {!r}: {}".format(raw, exc))
    print(report(limits))

    partial = [1, 9, 25, 30]
    print("missing from {}: {}".format(partial, missing_squares(partial, 5)))
    print("not squares: {}".format(stray_values(partial, 5)))


if __name__ == "__main__":
    main()

