QUOTE_CHARS = ('"', "'")
MISSING_MARKERS = ('', 'NA', 'N/A', 'null', '-')
BOOL_TRUE = ('true', 'yes')
BOOL_FALSE = ('false', 'no')
NUMERIC_CHARS = '0123456789+-.'


def parse_csv_line(line):
    """Split a CSV line into its comma-separated values."""
    if not isinstance(line, str):
        raise TypeError('line must be a string')
    return [strip_value(field) for field in line.split(',')]


def strip_value(field):
    """Trim surrounding whitespace and one layer of matching quotes."""
    value = field.strip()
    if value[:1] not in QUOTE_CHARS:
        return value
    if len(value) >= 2 and value[-1] == value[0]:
        return value[1:-1]
    return value


def is_missing(value):
    """Report whether a field stands for an absent value."""
    return value.strip() in MISSING_MARKERS


def convert(value):
    """Guess a Python type for a single CSV value."""
    if is_missing(value):
        return None
    lowered = value.lower()
    if lowered in BOOL_TRUE:
        return True
    if lowered in BOOL_FALSE:
        return False
    if any(ch not in NUMERIC_CHARS for ch in value):
        return value
    try:
        if '.' not in value:
            return int(value)
        return float(value)
    except ValueError:
        return value


def validate_header(names):
    """Return the column names after rejecting empty or repeated ones."""
    seen = []
    for name in names:
        if name == '':
            raise ValueError('empty column name in header')
        if name not in seen:
            seen.append(name)
        else:
            raise ValueError('duplicate column name: %s' % name)
    return seen


def select(rows, columns):
    """Project each row onto the requested columns, erroring on unknown names."""
    result = []
    for row in rows:
        for column in columns:
            if column not in row:
                raise KeyError('unknown column: %s' % column)
        result.append([row[column] for column in columns])
    return result


def parse_table(text):
    """Parse a multi-line CSV text into a header list and list of row dicts."""
    lines = [line for line in text.splitlines() if line.strip()]
    if not lines:
        return [], []
    header = validate_header(parse_csv_line(lines[0]))
    rows = []
    for raw in lines[1:]:
        values = parse_csv_line(raw)
        if len(values) != len(header):
            raise ValueError('row has %d fields, expected %d' % (len(values), len(header)))
        rows.append({key: convert(val) for key, val in zip(header, values)})
    return header, rows


def format_report(header, rows):
    """Render the parsed table as aligned text, marking absent values."""
    widths = [len(name) for name in header]
    body = []
    for values in select(rows, header):
        cells = ['<none>' if value is None else str(value) for value in values]
        widths = [max(w, len(c)) for w, c in zip(widths, cells)]
        body.append(cells)
    out = ['  '.join(n.ljust(w) for n, w in zip(header, widths))]
    out.append('  '.join('-' * w for w in widths))
    for cells in body:
        out.append('  '.join(c.ljust(w) for c, w in zip(cells, widths)))
    return '\n'.join(out)


def main():
    print(parse_csv_line('apple,banana,cherry'))
    print(parse_csv_line('1,2,3'))
    text = 'name,qty,price,active\n"apple", 12, 1.50, yes\nbanana,3,0.25,no\ncherry,NA,2.00,true\n'
    header, rows = parse_table(text)
    print(format_report(header, rows))
    print('total qty:', sum(row['qty'] for row in rows if row['qty'] is not None))


if __name__ == '__main__':
    main()

