import random
import string
import sys

ALPHABET = string.ascii_lowercase + string.ascii_uppercase + string.digits
AMBIGUOUS = "lIO01"
CLASSES = ("lowercase", "uppercase", "digit")


def generate_password(length):
    """Return a random password of `length` letters and digits."""
    if not isinstance(length, int) or isinstance(length, bool):
        raise TypeError("length must be an integer")
    if length < 1:
        raise ValueError("length must be at least 1")
    return "".join(random.choice(ALPHABET) for _ in range(length))


def pool_excluding(excluded):
    """Return the alphabet characters that are not listed in `excluded`."""
    return [c for c in ALPHABET if c not in excluded]


def generate_readable_password(length):
    """Like generate_password, but skips characters that are easy to confuse."""
    pool = pool_excluding(AMBIGUOUS)
    return "".join(random.choice(pool) for _ in range(length))


def classify(char):
    """Name the character class of `char`, or None if it is not in the alphabet."""
    if char not in ALPHABET:
        return None
    if char in string.ascii_lowercase:
        return "lowercase"
    if char in string.ascii_uppercase:
        return "uppercase"
    return "digit"


def missing_classes(password):
    """Return the character classes that do not occur in `password`."""
    present = set()
    for char in password:
        kind = classify(char)
        if kind is not None:
            present.add(kind)
    return [kind for kind in CLASSES if kind not in present]


def parse_lengths(args):
    """Turn command-line arguments into a list of distinct positive lengths."""
    lengths = []
    seen = set()
    for arg in args:
        for char in arg:
            if char not in string.digits:
                raise ValueError("not a length: %r" % arg)
        length = int(arg)
        if length not in seen:
            seen.add(length)
            lengths.append(length)
    return lengths


def generate_strong_password(length):
    """Generate a password that contains every character class."""
    if length < len(CLASSES):
        raise ValueError("a strong password needs at least 3 characters")
    while True:
        candidate = generate_password(length)
        if not missing_classes(candidate):
            return candidate


def describe(password):
    """Build a one-line report about a generated password."""
    gaps = missing_classes(password)
    parts = ["%s (%d chars)" % (password, len(password))]
    parts.append("missing: " + ", ".join(gaps) if gaps else "all classes present")
    confusing = sorted({c for c in password if c in AMBIGUOUS})
    if confusing:
        parts.append("confusing: " + "".join(confusing))
    return " | ".join(parts)


def main():
    lengths = parse_lengths(sys.argv[1:]) or [8, 12, 16]
    for length in lengths:
        print(describe(generate_password(length)))
    print(describe(generate_readable_password(10)))
    biggest = max(lengths)
    if biggest >= len(CLASSES):
        print(describe(generate_strong_password(biggest)))


if __name__ == "__main__":
    main()

