def has_unique_chars(s):
    """Return True if every character in s occurs exactly once."""
    if not isinstance(s, str):
        raise TypeError("has_unique_chars expects a string")
    seen = set()
    for ch in s:
        if ch not in seen:
            seen.add(ch)
        else:
            return False
    return True


def normalize(s, ignore_case=False, ignore_spaces=False):
    """Prepare a string for uniqueness testing."""
    if ignore_case:
        s = s.casefold()
    if ignore_spaces:
        s = "".join(ch for ch in s if ch not in " \t\n")
    return s


def duplicate_chars(s):
    """Return the characters that appear more than once, in order of first repeat."""
    counts = {}
    repeats = []
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
        if counts[ch] == 2 and ch not in repeats:
            repeats.append(ch)
    return repeats


def unique_prefix(s):
    """Return the longest leading part of s whose characters are all distinct."""
    seen = set()
    end = 0
    for ch in s:
        if ch not in seen:
            seen.add(ch)
            end += 1
        else:
            break
    return s[:end]


def first_unique_char(s):
    """Return the first character of s that occurs only once, or None."""
    repeats = duplicate_chars(s)
    for ch in s:
        if ch not in repeats:
            return ch
    return None


def longest_unique_run(s):
    """Length of the longest substring of s with no repeated character."""
    best = 0
    start = 0
    last_pos = {}
    for index, ch in enumerate(s):
        if ch in last_pos and last_pos[ch] >= start:
            start = last_pos[ch] + 1
        last_pos[ch] = index
        run = index - start + 1
        if run > best:
            best = run
    return best


def describe(s, **options):
    """Build a one-line human readable verdict for s."""
    cleaned = normalize(s, **options)
    if has_unique_chars(cleaned):
        return "%-22r unique (%d chars)" % (s, len(cleaned))
    listing = ", ".join(repr(ch) for ch in duplicate_chars(cleaned))
    return "%-22r repeats: %s" % (s, listing)


def main():
    samples = ["abc", "abca", "", "Aa", "the quick brown fox", "python3"]
    for sample in samples:
        print(describe(sample))
        print("   case-insensitive:", has_unique_chars(normalize(sample, ignore_case=True)))
        print("   unique prefix:", repr(unique_prefix(sample)))
        print("   longest unique run:", longest_unique_run(sample))
        pick = first_unique_char(sample)
        if pick is None:
            print("   no character occurs exactly once")
        else:
            print("   first single character:", repr(pick))


if __name__ == "__main__":
    main()

