COMPARABLE_TYPES = ('int', 'float', 'bool')


def _check_values(d):
    for key, value in d.items():
        if type(value).__name__ not in COMPARABLE_TYPES:
            raise TypeError("value for %r is not sortable: %r" % (key, value))


def sort_dict_by_value(d):
    """Return the items of d as a list of tuples sorted by ascending value."""
    if not hasattr(d, 'items'):
        raise TypeError("sort_dict_by_value expects a mapping")
    _check_values(d)
    return sorted(d.items(), key=lambda item: item[1])


def sort_dict_by_value_excluding(d, excluded_keys):
    """Sort d by value, leaving out any key listed in excluded_keys."""
    kept = {}
    for key, value in d.items():
        if key not in excluded_keys:
            kept[key] = value
    return sort_dict_by_value(kept)


def merge_and_sort(*dicts):
    """Combine several dictionaries (first occurrence of a key wins), then sort."""
    merged = {}
    for mapping in dicts:
        for key, value in mapping.items():
            if key not in merged:
                merged[key] = value
    return sort_dict_by_value(merged)


def group_keys_by_value(d):
    """Return (value, [keys]) pairs ordered by ascending value."""
    buckets = {}
    for key, value in d.items():
        if value not in buckets:
            buckets[value] = []
        buckets[value].append(key)
    return [(value, sorted(buckets[value])) for value in sorted(buckets)]


def format_ranking(pairs):
    """Render sorted (key, value) pairs as numbered lines."""
    if not pairs:
        return "(empty)"
    lines = []
    for position, (key, value) in enumerate(pairs, start=1):
        lines.append("%2d. %-8s %s" % (position, key, value))
    return "\n".join(lines)


def report(datasets, name):
    if name not in datasets:
        raise KeyError("unknown dataset: %r" % name)
    data = datasets[name]
    header = "dataset %s (%d entries)" % (name, len(data))
    return header + "\n" + format_ranking(sort_dict_by_value(data))


def main():
    datasets = {
        'letters': {'a': 3, 'b': 1, 'c': 2},
        'empty': {},
        'scores': {'ada': 88, 'bob': 72, 'cleo': 95, 'dan': 72},
    }
    for name in ('letters', 'empty', 'scores'):
        print(report(datasets, name))
        print()

    print("scores without 'dan':", sort_dict_by_value_excluding(datasets['scores'], {'dan'}))
    print("tied scores:", group_keys_by_value(datasets['scores']))
    print("merged:", merge_and_sort(datasets['letters'], {'c': 99, 'd': 0}))


if __name__ == '__main__':
    main()

