import sys

NUMERIC_TYPES = (int, float)
ALIGNMENTS = {"left": str.ljust, "right": str.rjust, "center": str.center}
ALLOWED_CHARS = set("0123456789+-.")
ALLOWED_FLAGS = ("align",)


def parse_options(args):
    """Split '--align=center' style flags from positional matrix texts."""
    align = "right"
    texts = []
    for arg in args:
        if not arg.startswith("--"):
            texts.append(arg)
            continue
        if "=" not in arg:
            raise ValueError("flag needs a value: " + arg)
        name, value = arg[2:].split("=", 1)
        if name not in ALLOWED_FLAGS:
            raise ValueError("unknown flag: " + name)
        align = value
    return texts, align


def parse_matrix(text):
    """Parse a matrix written as '1 2; 3 4' into a list of lists of numbers."""
    rows = []
    for chunk in text.replace("\n", ";").split(";"):
        cells = chunk.split()
        if not cells:
            continue
        row = []
        for cell in cells:
            for ch in cell:
                if ch not in ALLOWED_CHARS:
                    raise ValueError("illegal character " + repr(ch))
            if "." not in cell:
                row.append(int(cell))
            else:
                row.append(float(cell))
        rows.append(row)
    if not rows:
        raise ValueError("no rows found in " + repr(text))
    return rows


def validate_matrix(matrix, name):
    """Check that matrix is a rectangular list of rows of plain numbers."""
    if not isinstance(matrix, list) or not matrix:
        raise ValueError(name + " must be a non-empty list of rows")
    width = len(matrix[0]) if isinstance(matrix[0], list) else None
    for index, row in enumerate(matrix):
        if not isinstance(row, list):
            raise ValueError("%s row %d is not a list" % (name, index))
        if len(row) != width:
            raise ValueError("%s row %d has a ragged length" % (name, index))
        for value in row:
            if type(value) not in NUMERIC_TYPES:
                raise ValueError("%s row %d holds a non-number" % (name, index))
    return len(matrix), width


def matrix_add(matrix1, matrix2):
    """Return the element-wise sum of two equally shaped matrices."""
    shape1 = validate_matrix(matrix1, "matrix1")
    shape2 = validate_matrix(matrix2, "matrix2")
    if shape1 != shape2:
        raise ValueError("shape mismatch: %s vs %s" % (shape1, shape2))
    return [[a + b for a, b in zip(r1, r2)] for r1, r2 in zip(matrix1, matrix2)]


def format_number(value):
    """Render one entry without a trailing '.0' on whole floats."""
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value)


def format_matrix(matrix, align="right"):
    """Render a matrix as text rows whose columns line up."""
    if align not in ALIGNMENTS:
        raise ValueError("unknown alignment " + repr(align))
    pad = ALIGNMENTS[align]
    cells = [[format_number(value) for value in row] for row in matrix]
    width = max(len(text) for row in cells for text in row)
    return "\n".join(" ".join(pad(text, width) for text in row) for row in cells)


def report(left_text, right_text, align="right"):
    """Parse two textual matrices, add them and render the sum."""
    total = matrix_add(parse_matrix(left_text), parse_matrix(right_text))
    return format_matrix(total, align)


def main(argv):
    texts, align = parse_options(argv[1:])
    if len(texts) != 2:
        texts = ["1 2; 3 4", "5 6; 7 8"]
    print(report(texts[0], texts[1], align))


if __name__ == "__main__":
    main(sys.argv)

