WHITESPACE = " \t\n\r\f\v"
TERMINALS = ".!?"
SMALL_WORDS = ("a", "an", "and", "the", "of", "in", "on", "or", "to")
FLAGS = ("--title", "--report")


def split_words(text):
    """Split text into words on any run of whitespace."""
    words = []
    buffer = []
    for ch in text:
        if ch not in WHITESPACE:
            buffer.append(ch)
        elif buffer:
            words.append("".join(buffer))
            buffer = []
    if buffer:
        words.append("".join(buffer))
    return words


def reverse_words(sentence):
    """Reverse the order of the words in sentence, keeping words intact."""
    if not isinstance(sentence, str):
        raise TypeError("sentence must be a string")
    words = split_words(sentence)
    words.reverse()
    return " ".join(words)


def reverse_sentence(sentence):
    """Reverse word order, keeping terminal punctuation at the end."""
    text = sentence.strip()
    if not text or text[-1] not in TERMINALS:
        core, tail = text, ""
    else:
        core, tail = text[:-1], text[-1]
    flipped = reverse_words(core)
    if not flipped:
        return tail
    return flipped[0].upper() + flipped[1:] + tail


def titlecase(words):
    """Title-case a word list, leaving small words lowercase after the first."""
    styled = []
    for index, word in enumerate(words):
        if index == 0 or word.lower() not in SMALL_WORDS:
            styled.append(word[:1].upper() + word[1:])
        else:
            styled.append(word.lower())
    return " ".join(styled)


def unique_words(words):
    """Distinct words, case-insensitive, in order of first appearance."""
    seen = []
    for word in words:
        key = word.lower()
        if key not in seen:
            seen.append(key)
    return seen


def format_report(sentence):
    words = split_words(sentence)
    lines = ["original: " + sentence.strip(), "reversed: " + reverse_words(sentence)]
    lines.append("sentence: " + reverse_sentence(sentence))
    lines.append("title   : " + titlecase(list(reversed(words))))
    lines.append("words   : %d (%d distinct)" % (len(words), len(unique_words(words))))
    return "\n".join(lines)


def main(argv):
    flags = []
    parts = []
    for arg in argv:
        if arg.startswith("--"):
            if arg not in FLAGS:
                raise SystemExit("unknown option: " + arg)
            flags.append(arg)
        else:
            parts.append(arg)
    samples = [" ".join(parts)] if parts else ["Hello world Python", "one", "the end of the road."]
    for sample in samples:
        if "--report" in flags:
            print(format_report(sample))
            print("")
        elif "--title" in flags:
            print(titlecase(list(reversed(split_words(sample)))))
        else:
            print(reverse_words(sample))


if __name__ == "__main__":
    import sys

    main(sys.argv[1:])

