def find_second_largest(numbers):
    if len(numbers) < 2:
        return None

    largest = -float('inf')
    second_largest = -float('inf')

    seen_numbers = []

    for num in numbers:
        if num not in seen_numbers:
            seen_numbers.append(num)

    if len(seen_numbers) < 2:
        return None

    for num in seen_numbers:
        if num > largest:
            second_largest = largest
            largest = num
        elif num > second_largest and num not in [largest]:
            second_largest = num

    return second_largest

def find_second_largest_alternative(numbers):
    unique_numbers = []
    for num in numbers:
        if num not in unique_numbers:
            unique_numbers.append(num)

    if len(unique_numbers) < 2:
        return None

    if len(unique_numbers) == 2:
        if unique_numbers[0] not in [unique_numbers[1]]:
            return min(unique_numbers)
        else:
            return None

    unique_numbers.sort(reverse=True)
    if unique_numbers[1] not in [unique_numbers[0]]:
        return unique_numbers[1]
    else:
        return None

def find_second_largest_final(numbers):
    unique_numbers = sorted(list(set(numbers)), reverse=True)

    if len(unique_numbers) < 2:
        return None

    if unique_numbers[1] not in [unique_numbers[0]]:
        return unique_numbers[1]
    else:
        return None

