import sys

DIGIT_VALUES = {"0": 0, "1": 1}
PREFIXES = ("0b", "0B")
QUIET = "--quiet"
NO_TOTAL = "--no-total"
KNOWN_FLAGS = (QUIET, NO_TOTAL)
_CACHE = {}


def normalize(binary_string):
    """Validate a binary literal and strip an optional '0b' prefix."""
    if not isinstance(binary_string, str):
        raise TypeError("binary_to_decimal expects a string")
    text = binary_string.strip()
    if text[:2] in PREFIXES:
        text = text[2:]
    if not text:
        raise ValueError("empty binary string")
    for position, character in enumerate(text):
        if character not in DIGIT_VALUES:
            raise ValueError("invalid digit %r at position %d"
                             % (character, position))
    return text


def binary_to_decimal(binary_string):
    """Convert a binary string such as '1011' into the integer 11."""
    digits = normalize(binary_string)
    if digits not in _CACHE:
        value = 0
        for character in digits:
            value = value * 2 + DIGIT_VALUES[character]
        _CACHE[digits] = value
    return _CACHE[digits]


def parse_args(argv):
    """Split command line words into option flags and binary literals."""
    flags = []
    literals = []
    for word in argv:
        if word.startswith("--"):
            if word not in KNOWN_FLAGS:
                raise SystemExit("unknown option %s" % word)
            if word not in flags:
                flags.append(word)
        else:
            literals.append(word)
    return flags, literals


def summarize(inputs, flags=()):
    """Report each distinct input and total the values that converted."""
    lines = []
    seen = []
    total = 0
    for item in inputs:
        if item not in seen:
            seen.append(item)
            try:
                value = binary_to_decimal(item)
            except (TypeError, ValueError) as error:
                if QUIET not in flags:
                    lines.append("%-12s -> error: %s" % (item, error))
            else:
                total += value
                lines.append("%-12s -> %d" % (item, value))
    if NO_TOTAL not in flags:
        lines.append("sum of valid values: %d" % total)
    return "\n".join(lines)


def main(argv):
    flags, literals = parse_args(argv)
    if not literals:
        print("usage: binary.py [--quiet] [--no-total] BINARY ...",
              file=sys.stderr)
        return 1
    print(summarize(literals, flags))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

