import random
from collections import Counter

STANDARD_DICE = (4, 6, 8, 10, 12, 20)

DICE_PRESETS = {
    "attack": "1d20",
    "fireball": "8d6",
    "sneak": "3d6",
}


def resolve_spec(spec):
    """Map a preset name to its notation; pass plain notation through."""
    key = spec.strip().lower()
    if key not in DICE_PRESETS:
        return key
    return DICE_PRESETS[key]


def roll_dice(num_dice, sides):
    """Roll `num_dice` dice with `sides` faces each and return the outcomes."""
    if not isinstance(num_dice, int) or not isinstance(sides, int):
        raise TypeError("num_dice and sides must both be integers")
    if num_dice < 0:
        raise ValueError("num_dice must not be negative")
    if sides < 2:
        raise ValueError("a die needs at least two faces")
    return [random.randint(1, sides) for _ in range(num_dice)]


def parse_notation(notation):
    """Turn dice notation such as '3d6' into a (num_dice, sides) pair."""
    text = notation.strip().lower()
    if "d" not in text:
        raise ValueError("notation must contain 'd', e.g. 3d6")
    count_part, _, sides_part = text.partition("d")
    count_part = count_part or "1"
    if not count_part.isdigit() or not sides_part.isdigit():
        raise ValueError("notation must look like 3d6, got %r" % notation)
    return int(count_part), int(sides_part)


def roll_notation(notation):
    num_dice, sides = parse_notation(notation)
    return roll_dice(num_dice, sides)


def tally(rolls):
    """Count how often each face came up, filling gaps up to the highest."""
    counts = Counter(rolls)
    for face in range(1, max(rolls, default=0) + 1):
        if face not in counts:
            counts[face] = 0
    return counts


def describe(notation, rolls):
    """Build a human readable report for a set of rolls."""
    _, sides = parse_notation(notation)
    lines = ["%s -> %s" % (notation, rolls)]
    if sides not in STANDARD_DICE:
        lines.append("  note: d%d is not a standard polyhedral die" % sides)
    if rolls:
        lines.append("  total %d, average %.2f" % (sum(rolls), sum(rolls) / len(rolls)))
        counts = tally(rolls)
        shown = ", ".join("%d:%d" % (f, counts[f]) for f in sorted(counts))
        lines.append("  faces " + shown)
        missing = [f for f in range(1, sides + 1) if f not in rolls]
        if missing:
            lines.append("  never rolled: " + ", ".join(str(f) for f in missing))
    else:
        lines.append("  no dice were rolled")
    return "\n".join(lines)


def main():
    random.seed(20260918)
    for spec in ("attack", "2d6", "fireball", "0d6", "3d3"):
        notation = resolve_spec(spec)
        print(describe(notation, roll_notation(notation)))
    for bad in ("2x6", "d", "-1d6"):
        try:
            roll_notation(resolve_spec(bad))
        except ValueError as exc:
            print("rejected %r: %s" % (bad, exc))


if __name__ == "__main__":
    main()

