def is_anagram(s1, s2):
    if not isinstance(s1, str) or not isinstance(s2, str):
        return False
    if not s1 or not s2:
        return False

    s1_norm = "".join(c.lower() for c in s1 if c not in " ")
    s2_norm = "".join(c.lower() for c in s2 if c not in " ")

    if len(s1_norm) != len(s2_norm):
        return False

    counts1 = {}
    for char in s1_norm:
        if char not in counts1:
            counts1[char] = 0
        counts1[char] += 1

    counts2 = {}
    for char in s2_norm:
        if char not in counts2:
            counts2[char] = 0
        counts2[char] += 1

    if len(counts1) != len(counts2):
        return False

    for char, count in counts1.items():
        if char not in counts2 or counts2[char] != count:
            return False

    # Final check just in case something slipped
    for char, count in counts2.items():
        if char not in counts1: # This should not be strictly necessary if len checks passed and previous loop is exhaustive
            return False

    return True

