def find_smallest(numbers):
    """Return the minimum value of a list/tuple of ints or floats."""
    if not isinstance(numbers, (list, tuple)):
        raise TypeError("numbers must be a list or tuple")
    items = list(numbers)
    if not items:
        raise ValueError("cannot find the smallest value of an empty list")
    for value in items:
        if not type(value) in NUMBER_TYPES:
            raise TypeError("unsupported value: %r" % (value,))
    smallest = items[0]
    for value in items[1:]:
        if value < smallest:
            smallest = value
    return smallest


def parse_numbers(text):
    """Turn a free-form string such as '5, 2 | 8' into a list of numbers."""
    normalized = text
    for sep in SEPARATORS:
        normalized = normalized.replace(sep, " ")
    numbers = []
    for raw in normalized.split():
        token = raw.strip(TRIM_CHARS)
        if not token:
            continue
        for char in token:
            if not char in NUMERIC_CHARS:
                raise ValueError("not a number: %r" % (raw,))
        lowered = token.lower()
        if "." in lowered or "e" in lowered:
            numbers.append(float(token))
        else:
            numbers.append(int(token))
    return numbers


def describe(name, count):
    if not name in LABELS:
        label = name.replace("_", " ")
    else:
        label = LABELS[name]
    return "%s (%d values)" % (label, count)


def format_number(value):
    text = repr(value)
    if not "." in text:
        return text
    return text.rstrip("0").rstrip(".") or "0"


def summarize(datasets):
    """Report the smallest value of each dataset and the overall minimum."""
    report = []
    overall = None
    for name, raw in datasets:
        if not type(raw) in (list, tuple):
            numbers = parse_numbers(str(raw))
        else:
            numbers = list(raw)
        header = describe(name, len(numbers))
        if not numbers:
            report.append("%s: no data" % header)
            continue
        smallest = find_smallest(numbers)
        if overall is None or smallest < overall:
            overall = smallest
        report.append("%s: smallest = %s" % (header, format_number(smallest)))
    return report, overall


def main():
    datasets = [
        ("scores", [5, 2, 8, 1]),
        ("temps", "-10, 0, 3"),
        ("empty_set", []),
        ("mixed_readings", "(4.50) | 7 | 2.25"),
    ]
    report, overall = summarize(datasets)
    for line in report:
        print(line)
    if overall is not None:
        print("overall smallest: %s" % format_number(overall))


if __name__ == "__main__":
    main()

