def char_frequency(text):
    """Count occurrences of each character in text, ignoring case."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    frequency_map = {}
    for char in text.lower():
        if char not in frequency_map:
            frequency_map[char] = 0
        frequency_map[char] += 1
    return frequency_map


def letters_only(frequency_map):
    """Keep only the entries whose key is an alphabetic character."""
    return {char: count for char, count in frequency_map.items() if char.isalpha()}


def vowel_consonant_counts(frequency_map):
    """Split the alphabetic counts into vowel and consonant totals."""
    vowels = 0
    consonants = 0
    for char, count in letters_only(frequency_map).items():
        if char not in "aeiou":
            consonants += count
        else:
            vowels += count
    return vowels, consonants


def missing_letters(frequency_map, alphabet="abcdefghijklmnopqrstuvwxyz"):
    """Return the alphabet letters that never appear in the counted text."""
    return [letter for letter in alphabet if letter not in frequency_map]


def is_pangram(frequency_map):
    """True when every alphabet letter was counted at least once."""
    return not missing_letters(frequency_map)


def describe_character(char):
    """Human readable label for a counted character."""
    names = {" ": "space", "\t": "tab", "\n": "newline"}
    if char not in names:
        return repr(char)
    return names[char]


def duplicate_characters(frequency_map):
    """Characters counted more than once, sorted by descending count."""
    repeated = [item for item in frequency_map.items() if item[1] > 1]
    repeated.sort(key=lambda item: (-item[1], item[0]))
    return repeated


def distinct_texts(texts):
    """Keep the first of any texts that are equal ignoring case."""
    unique = []
    seen = set()
    for text in texts:
        lowered = text.lower()
        if lowered not in seen:
            seen.add(lowered)
            unique.append(text)
    return unique


def format_report(text):
    """Build a multi-line frequency report for text."""
    frequency_map = char_frequency(text)
    lines = ["text: %r" % text, "distinct characters: %d" % len(frequency_map)]
    for char in sorted(frequency_map):
        lines.append("  %s -> %d" % (describe_character(char), frequency_map[char]))
    vowels, consonants = vowel_consonant_counts(frequency_map)
    lines.append("vowels: %d, consonants: %d" % (vowels, consonants))
    repeated = duplicate_characters(letters_only(frequency_map))
    if repeated:
        joined = ", ".join("%s x%d" % (char, count) for char, count in repeated)
        lines.append("repeated letters: " + joined)
    else:
        lines.append("repeated letters: none")
    if is_pangram(frequency_map):
        lines.append("pangram: yes")
    else:
        gaps = missing_letters(frequency_map)
        lines.append("pangram: no (missing %d: %s)" % (len(gaps), "".join(gaps)))
    return "\n".join(lines)


def main():
    samples = [
        "hello",
        "Python",
        "HELLO",
        "The quick brown fox jumps over the lazy dog",
        "Mississippi river",
    ]
    for sample in distinct_texts(samples):
        print(format_report(sample))
        print("-" * 40)


if __name__ == "__main__":
    main()

