import sys

_CACHE = {}
_DIGITS = "0123456789"
_OPTIONS = ("--quiet", "--list")
_DEFAULT_SAMPLES = ["153", "123", "9_474", " 407 ", "153", "12a", "0"]


def parse_number(text):
    """Turn user supplied text into a positive integer."""
    cleaned = text.strip().replace("_", "")
    if not cleaned:
        raise ValueError("empty input")
    body = cleaned[1:] if cleaned[0] == "+" else cleaned
    if not body:
        raise ValueError("no digits after sign: %r" % text)
    for char in body:
        if char not in _DIGITS:
            raise ValueError("not a decimal digit: %r" % char)
    value = int(body)
    if value < 1:
        raise ValueError("number must be positive, got %d" % value)
    return value


def digits_of(number):
    return [int(char) for char in str(number)]


def is_armstrong(number):
    if not isinstance(number, int) or isinstance(number, bool):
        raise TypeError("number must be an int, got %r" % type(number).__name__)
    if number < 1:
        raise ValueError("number must be positive")
    if number not in _CACHE:
        digits = digits_of(number)
        power = len(digits)
        _CACHE[number] = number == sum(digit ** power for digit in digits)
    return _CACHE[number]


def unique_numbers(texts):
    """Parse every text, dropping repeats and reporting bad entries."""
    values, problems, seen = [], [], set()
    for text in texts:
        try:
            value = parse_number(text)
        except ValueError as err:
            problems.append((text, str(err)))
            continue
        if value not in seen:
            seen.add(value)
            values.append(value)
    return values, problems


def describe(number):
    digits = digits_of(number)
    power = len(digits)
    terms = " + ".join("%d^%d" % (digit, power) for digit in digits)
    total = sum(digit ** power for digit in digits)
    verdict = "is" if is_armstrong(number) else "is not"
    return "%d: %s = %d -> %s an Armstrong number" % (number, terms, total, verdict)


def armstrong_numbers_upto(limit):
    return [n for n in range(1, limit + 1) if is_armstrong(n)]


def main(argv):
    args = argv[1:]
    samples = [arg for arg in args if arg not in _OPTIONS]
    values, problems = unique_numbers(samples or _DEFAULT_SAMPLES)
    if "--quiet" not in args:
        for value in values:
            print(describe(value))
    else:
        for value in values:
            print("%d %s" % (value, is_armstrong(value)))
    for text, reason in problems:
        print("skipped %r (%s)" % (text, reason))
    if "--list" in args:
        print("Armstrong numbers up to 10000: %s" % armstrong_numbers_upto(10000))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

