ABSOLUTE_ZERO_F = -459.67
DIGIT_CHARS = "0123456789."
NOTABLE_LABELS = ("freezing", "boiling")
SCALE_ALIASES = {"f": "fahrenheit", "fahrenheit": "fahrenheit", "c": "celsius",
                 "celsius": "celsius", "k": "kelvin", "kelvin": "kelvin"}


def normalize_scale(name):
    key = str(name).strip().lower()
    if key not in SCALE_ALIASES:
        raise ValueError("unknown temperature scale: %r" % name)
    return SCALE_ALIASES[key]


def parse_reading(raw):
    if isinstance(raw, (int, float)):
        return float(raw), None
    if not isinstance(raw, str):
        raise TypeError("temperature must be a number or a numeric string")
    text = raw.strip().rstrip("°").strip()
    scale = None
    if text and text[-1].lower() not in DIGIT_CHARS:
        scale = normalize_scale(text[-1])
        text = text[:-1].strip().rstrip("°").strip()
    try:
        return float(text), scale
    except ValueError:
        raise ValueError("cannot parse temperature: %r" % raw)


def fahrenheit_to_celsius(fahrenheit):
    value, scale = parse_reading(fahrenheit)
    if scale not in (None, "fahrenheit"):
        raise ValueError("expected a Fahrenheit reading, got %s" % scale)
    return (value - 32.0) * 5.0 / 9.0


def convert(value, target="celsius"):
    scale = normalize_scale(target)
    if scale not in ("celsius", "kelvin"):
        raise ValueError("cannot convert Fahrenheit to %s" % scale)
    celsius = fahrenheit_to_celsius(value)
    if scale == "kelvin":
        return celsius + 273.15
    return celsius


