"""Fibonacci utilities with a small command line front end."""
import sys

DIGITS = "0123456789"
COMMANDS = ("--report", "--list", "--classify")
_CACHE = {0: 0, 1: 1}


def nth_fibonacci(n):
    """Return the nth Fibonacci number for the sequence 0, 1, 1, 2, 3, 5, ..."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be a plain int, got %r" % (n,))
    if n < 0:
        raise ValueError("n must be non-negative, got %d" % n)
    if n not in _CACHE:
        known = max(_CACHE)
        previous, current = _CACHE[known - 1], _CACHE[known]
        for index in range(known + 1, n + 1):
            previous, current = current, previous + current
            _CACHE[index] = current
    return _CACHE[n]


def parse_index(text):
    """Convert user supplied text into a valid Fibonacci index."""
    cleaned = text.strip().replace("_", "")
    if not cleaned:
        raise ValueError("no index supplied")
    for character in cleaned:
        if character not in DIGITS:
            raise ValueError("not a non-negative integer: %r" % text)
    return int(cleaned)


def classify(candidates):
    """Partition candidates into Fibonacci members and non-members."""
    if not candidates:
        return [], []
    known = []
    index = 0
    while nth_fibonacci(index) <= max(candidates):
        known.append(nth_fibonacci(index))
        index += 1
    members, others = [], []
    for candidate in candidates:
        if candidate not in known:
            others.append(candidate)
        else:
            members.append(candidate)
    return members, others


def format_report(requests):
    """Build a human readable report for the requested indices."""
    lines = []
    seen = []
    for raw in requests:
        try:
            index = parse_index(raw)
        except ValueError as error:
            lines.append("skipped %r: %s" % (raw, error))
            continue
        if index not in seen:
            seen.append(index)
            lines.append("fib(%d) = %d" % (index, nth_fibonacci(index)))
    lines.append("sum of reported values = %d" % sum(nth_fibonacci(i) for i in seen))
    return "\n".join(lines)


def run(arguments):
    """Execute one command with its arguments and return the report text."""
    if not arguments:
        arguments = ["--report", "0", "6", "10", "6", " 30 ", "1_0", "seven", ""]
    command, rest = arguments[0], arguments[1:]
    if command not in COMMANDS:
        raise ValueError("unknown command %r; expected one of %s"
                         % (command, ", ".join(COMMANDS)))
    if command == "--list":
        count = parse_index(rest[0]) if rest else 10
        return "first %d: %s" % (count, fibonacci_sequence(count))
    if command == "--classify":
        members, others = classify([parse_index(item) for item in rest])
        return "fibonacci: %s\nother: %s" % (members, others)
    return format_report(rest)


def fibonacci_sequence(count):
    """Return the first `count` Fibonacci numbers as a list."""
    if count < 0:
        raise ValueError("count must be non-negative")
    return [nth_fibonacci(i) for i in range(count)]


def main(argv=None):
    """Print the report produced for the command line arguments."""
    print(run(sys.argv[1:] if argv is None else argv))


if __name__ == "__main__":
    main()

