import os
import sys

TEXT_EXTENSIONS = {'.txt', '.log', '.csv', '.md', '.py', '.json'}
BINARY_MARKERS = {'\x00', '\x1a'}
FLAGS = {'--all', '--nonblank'}


def count_file_lines(filepath):
    """Return the number of lines in the text file at filepath."""
    line_count = 0
    with open(filepath, 'r', encoding='utf-8', errors='replace') as handle:
        for _line in handle:
            line_count += 1
    return line_count


def parse_args(argv):
    """Split command line tokens into recognized flags and file paths."""
    flags = set()
    paths = []
    for token in argv[1:]:
        if token not in FLAGS:
            paths.append(token)
        else:
            flags.add(token)
    return flags, paths


def classify_path(filepath):
    """Describe a path as 'text', 'other' or 'missing'."""
    if not os.path.isfile(filepath):
        return 'missing'
    extension = os.path.splitext(filepath)[1].lower()
    if extension not in TEXT_EXTENSIONS:
        return 'other'
    return 'text'


def looks_binary(filepath, sample_size=4096):
    """True if an early chunk of the file contains bytes typical of binaries."""
    with open(filepath, 'r', encoding='utf-8', errors='replace') as handle:
        sample = handle.read(sample_size)
    return any(marker in sample for marker in BINARY_MARKERS)


def count_nonblank_lines(filepath):
    """Return how many lines hold something other than whitespace."""
    kept = 0
    with open(filepath, 'r', encoding='utf-8', errors='replace') as handle:
        for line in handle:
            if line.strip():
                kept += 1
    return kept


def summarize(paths, flags):
    """Build a report mapping each unique path to its statistics."""
    report = {}
    for path in paths:
        if path not in report:
            kind = classify_path(path)
            if kind == 'missing':
                report[path] = {'status': 'missing'}
            elif kind == 'other' and '--all' not in flags:
                report[path] = {'status': 'skipped'}
            elif looks_binary(path) and '--all' not in flags:
                report[path] = {'status': 'skipped'}
            else:
                entry = {'status': 'counted', 'lines': count_file_lines(path)}
                if '--nonblank' in flags:
                    entry['nonblank'] = count_nonblank_lines(path)
                report[path] = entry
    return report


def format_report(report):
    """Turn a report dictionary into printable lines."""
    lines = []
    for path in sorted(report):
        entry = report[path]
        if 'lines' not in entry:
            lines.append('{0}: {1}'.format(path, entry['status']))
        elif 'nonblank' not in entry:
            lines.append('{0}: {1} lines'.format(path, entry['lines']))
        else:
            lines.append('{0}: {1} lines ({2} non-blank)'.format(
                path, entry['lines'], entry['nonblank']))
    return lines


def main(argv):
    flags, paths = parse_args(argv)
    if not paths:
        print('usage: linecount [--all] [--nonblank] FILE [FILE ...]')
        return 2
    report = summarize(paths, flags)
    for line in format_report(report):
        print(line)
    statuses = {entry['status'] for entry in report.values()}
    return 0 if 'missing' not in statuses else 1


if __name__ == '__main__':
    sys.exit(main(sys.argv))

