LABELS = {
    "added": "added   ",
    "updated": "updated ",
    "preserved": "kept    ",
}
ORDER = ("added", "updated", "preserved")


def validate_mapping(name, mapping):
    if not isinstance(mapping, dict):
        raise TypeError(f"{name} must be a dict, got {type(mapping).__name__}")


def classify_keys(dict1, dict2):
    added = [key for key in dict2 if not key in dict1]
    preserved = [key for key in dict1 if not key in dict2]
    updated = [key for key in dict2 if key in dict1 and dict1[key] != dict2[key]]
    unchanged = [key for key in dict2 if key in dict1 and dict1[key] == dict2[key]]
    return {
        "added": added,
        "updated": updated,
        "preserved": preserved + unchanged,
    }


def update_dict(dict1, dict2):
    validate_mapping("dict1", dict1)
    validate_mapping("dict2", dict2)
    merged_dict = dict(dict1)
    for key, value in dict2.items():
        merged_dict[key] = value
    return merged_dict


def format_line(category, key, dict1, dict2):
    if not category in LABELS:
        raise ValueError(f"unknown category: {category!r}")
    label = LABELS[category]
    if category == "added":
        return f"{label}{key!r} = {dict2[key]!r}"
    if category == "updated":
        return f"{label}{key!r}: {dict1[key]!r} -> {dict2[key]!r}"
    return f"{label}{key!r} = {dict1[key]!r}"


def build_report(dict1, dict2):
    changes = classify_keys(dict1, dict2)
    lines = [f"result  {update_dict(dict1, dict2)}"]
    for category in ORDER:
        for key in sorted(changes[category], key=repr):
            lines.append(format_line(category, key, dict1, dict2))
    return lines


def merge_all(dicts):
    merged_dict = {}
    for mapping in dicts:
        merged_dict = update_dict(merged_dict, mapping)
    return merged_dict


def conflicting_keys(dicts):
    seen = set()
    conflicts = []
    for mapping in dicts:
        for key in mapping:
            if not key in seen:
                seen.add(key)
            elif not key in conflicts:
                conflicts.append(key)
    return conflicts


def main():
    for first, second in (({"a": 1, "b": 2}, {"b": 3, "c": 4}), ({"x": 10}, {"y": 20})):
        for line in build_report(first, second):
            print(line)
        print("-" * 32)
    chain = [{"a": 1}, {"b": 2, "a": 9}, {"c": 3, "b": 2}]
    print("chained", merge_all(chain))
    print("clashes", conflicting_keys(chain))


if __name__ == "__main__":
    main()

