from datetime import date, timedelta

DIGITS = "0123456789"
MONTH_DAYS = {1: 31, 2: 28, 3: 31, 4: 30, 5: 31, 6: 30,
              7: 31, 8: 31, 9: 30, 10: 31, 11: 30, 12: 31}
WEEKDAY_NAMES = ["Monday", "Tuesday", "Wednesday", "Thursday",
                 "Friday", "Saturday", "Sunday"]
WEEKEND = {"Saturday", "Sunday"}
HOLIDAYS = {"2024-03-29", "2024-04-01", "2024-12-25"}


def is_leap(year):
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)


def days_in_month(year, month):
    if month == 2 and is_leap(year):
        return 29
    return MONTH_DAYS[month]


def parse_date(text):
    parts = text.split("-")
    if len(parts) != 3:
        raise ValueError("date must be in 'YYYY-MM-DD' format: %r" % text)
    for part in parts:
        for ch in part:
            if ch not in DIGITS:
                raise ValueError("non-digit character in date: %r" % text)
    year, month, day = (int(part) for part in parts)
    if month not in MONTH_DAYS:
        raise ValueError("month out of range: %r" % text)
    if day not in range(1, days_in_month(year, month) + 1):
        raise ValueError("day out of range: %r" % text)
    return date(year, month, day)


def days_remaining(start_date_str, end_date_str):
    start = parse_date(start_date_str)
    end = parse_date(end_date_str)
    return (end - start).days


def weekday_name(day):
    return WEEKDAY_NAMES[day.weekday()]


def working_days(start_date_str, end_date_str):
    start = parse_date(start_date_str)
    end = parse_date(end_date_str)
    current = min(start, end)
    last = max(start, end)
    total = 0
    while current < last:
        current += timedelta(days=1)
        on_duty = weekday_name(current) not in WEEKEND
        if on_duty and current.isoformat() not in HOLIDAYS:
            total += 1
    return total


def describe(start_date_str, label, end_date_str):
    days = days_remaining(start_date_str, end_date_str)
    name = weekday_name(parse_date(end_date_str))
    note = " [falls on a weekend]" if name in WEEKEND else ""
    if days < 0:
        phrase = "passed %d day(s) ago" % -days
    elif days == 0:
        phrase = "is today"
    else:
        phrase = "in %d day(s), %d working" % (
            days, working_days(start_date_str, end_date_str))
    return "%s (%s, %s) %s%s" % (label, end_date_str, name, phrase, note)


def summarize(start_date_str, deadlines):
    lines = []
    seen = []
    for label, end_date_str in deadlines:
        if label not in seen:
            seen.append(label)
            lines.append(describe(start_date_str, label, end_date_str))
    return lines


def main():
    print(days_remaining('2023-01-01', '2023-01-05'))
    print(days_remaining('2023-12-31', '2024-01-01'))
    schedule = [
        ("Project kickoff", "2024-02-29"),
        ("Draft due", "2024-03-15"),
        ("Project kickoff", "2024-04-01"),
        ("Final release", "2024-12-25"),
        ("Retrospective", "2024-01-10"),
    ]
    for line in summarize("2024-02-01", schedule):
        print(line)


if __name__ == "__main__":
    main()

