ALLOWED_SCHEMES = ("http", "https")
HOST_EXTRA_CHARS = "-._"
DIGITS = "0123456789"


def split_scheme(url):
    """Return (scheme, remainder) for a supported scheme, else (None, url)."""
    lowered = url.lower()
    if "://" not in lowered:
        return None, url
    scheme, _, _ = lowered.partition("://")
    if scheme not in ALLOWED_SCHEMES:
        return None, url
    return scheme, url[len(scheme) + 3:]


def extract_authority(remainder):
    """Cut the authority part away from path, query and fragment."""
    authority = remainder
    for separator in "/?#":
        authority = authority.split(separator, 1)[0]
    return authority


def split_port(authority):
    """Split an authority into (host, port); port is None when absent."""
    if ":" not in authority:
        return authority, None
    host, _, port = authority.rpartition(":")
    return host, port


def is_valid_port(port):
    """An explicit port must be a non empty run of ASCII digits."""
    if port is None:
        return True
    if not port:
        return False
    for char in port:
        if char not in DIGITS:
            return False
    return True


def is_valid_host(host):
    """A host must look like at least two dot separated labels."""
    if "." not in host:
        return False
    labels = host.split(".")
    for label in labels:
        if not label:
            return False
        for char in label:
            if not char.isalnum() and char not in HOST_EXTRA_CHARS:
                return False
        if label.startswith("-") or label.endswith("-"):
            return False
    return len(labels[-1]) >= 2


def is_valid_url(url):
    """Check whether url starts with a supported scheme and has a dotted host."""
    if not isinstance(url, str):
        return False
    url = url.strip()
    if not url or any(char.isspace() for char in url):
        return False
    scheme, remainder = split_scheme(url)
    if scheme is None:
        return False
    host, port = split_port(extract_authority(remainder))
    return is_valid_port(port) and is_valid_host(host)


def describe(url):
    """Build a short human readable verdict for one candidate URL."""
    trimmed = url.strip()
    scheme, remainder = split_scheme(trimmed)
    if scheme is None:
        reason = "unsupported scheme"
    else:
        host, port = split_port(extract_authority(remainder))
        if "." not in host:
            reason = "host has no dot"
        elif not is_valid_port(port):
            reason = "bad port"
        elif not is_valid_host(host):
            reason = "malformed host"
        else:
            reason = "ok"
    return "{}: {} ({})".format(trimmed, is_valid_url(url), reason)


def main():
    candidates = [
        "https://www.example.com",
        "ftp://invalid-url",
        "http://example.com/path?q=1",
        "http://localhost",
        "https://bad_host..com",
        "  https://spaced.example.org  ",
        "http://a-b.co:8080/x#frag",
        "http://example.com:port",
    ]
    for candidate in candidates:
        print(describe(candidate))


if __name__ == "__main__":
    main()

