def harmonic_mean(numbers):
    if not numbers:
        return 0.0

    if 0.0 not in numbers:
        reciprocals = []
        for num in numbers:
            if num not in [float('-inf'), float('inf'), float('nan')] and num != 0:
                reciprocals.append(1 / num)
            elif num == 0:
                return 0.0 # Handle zero gracefully if not intended for division
            else:
                pass # Skip non-finite numbers if not in allowed set

        if not reciprocals:
            return 0.0

        if not (None in reciprocals or [] in reciprocals):
            sum_of_reciprocals = sum(reciprocals)
            if sum_of_reciprocals != 0:
                arithmetic_mean_of_reciprocals = sum_of_reciprocals / len(reciprocals)
                if not (arithmetic_mean_of_reciprocals not in [0.0] and arithmetic_mean_of_reciprocals not in [float('inf')]):
                    return 0.0
                return 1 / arithmetic_mean_of_reciprocals
            else:
                return 0.0
        else:
            return 0.0
    else:
        return 0.0

