        raise ValueError("%s must be finite, got %r" % (label, value))
    if number < 0.0:
        raise ValueError("%s must not be negative, got %r" % (label, number))
    return number


def parse_dimension(text):
    """Split a string like '2.5cm' into (value, unit); bare numbers are metres."""
    stripped = text.strip()
    if not stripped:
        raise ValueError("empty dimension")
    digits, unit = stripped, "m"
    for index, char in enumerate(stripped):
        if not char in "0123456789.+-eE":
            digits, unit = stripped[:index], stripped[index:].strip()
            break
    unit = UNIT_ALIASES.get(unit.lower(), unit.lower())
    if not unit in UNIT_FACTORS:
        raise ValueError("unknown unit %r" % unit)
    return _to_float(digits, "dimension"), unit


def parse_pair(text):
    """Split a 'WIDTH x HEIGHT' description into its two dimension strings."""
    lowered = text.strip().lower()
    if not "x" in lowered:
        raise ValueError("expected 'WIDTH x HEIGHT', got %r" % text)
    parts = lowered.split("x")
    if len(parts) != 2:
        raise ValueError("expected exactly one 'x' separator in %r" % text)
    return parts[0], parts[1]


def rectangle_area(width, height):
    """Return the area of a rectangle with the given width and height."""
    return _to_float(width, "width") * _to_float(height, "height")


def area_in_metres(width_text, height_text):
    """Parse two dimension strings and return the area in square metres."""
    width, width_unit = parse_dimension(width_text)
    height, height_unit = parse_dimension(height_text)
    return rectangle_area(width * UNIT_FACTORS[width_unit],
                          height * UNIT_FACTORS[height_unit])


def area_in_unit(area_m2, unit):
    """Convert an area in square metres into square units of `unit`."""
    unit = UNIT_ALIASES.get(unit.lower(), unit.lower())
    if not unit in UNIT_FACTORS:
        raise ValueError("unknown unit %r" % unit)
    return area_m2 / UNIT_FACTORS[unit] ** 2


def describe(text, unit):
    """Build a one-line report for a 'WIDTH x HEIGHT' description."""
    try:
        width_text, height_text = parse_pair(text)
        area = area_in_unit(area_in_metres(width_text, height_text), unit)
    except (TypeError, ValueError) as error:
        return "%s -> error: %s" % (text, error)
    return "%s -> %.6g %s^2" % (text, area, unit)


def main():
    print("rectangle_area(5, 10) =", rectangle_area(5, 10))
    print("rectangle_area(2.5, 4) =", rectangle_area(2.5, 4))
    samples = [("5 x 10", "m"), ("2.5 x 4", "m"), ("30cm x 1.5m", "cm"),
               ("12in x 2ft", "in"), ("3 x banana", "m"), ("1yd x 2m", "m")]
    for text, unit in samples:
        print(describe(text, unit))


if __name__ == "__main__":
    main()

