    year, month, day = (int(p) for p in parts)
    if day < 1 or day > days_in_month(year, month):
        raise ValueError("day out of range for that month: %r" % (date_str,))
    return year, month, day


def parse_args(argv):
    dates = []
    fields = []
    for arg in argv:
        if arg.startswith('--'):
            if arg not in OPTIONS:
                raise SystemExit("unknown option: %s" % arg)
            field = OPTIONS[arg]
            if field not in fields:
                fields.append(field)
        else:
            dates.append(arg)
