SEPARATORS = " \t\n\r\f\v"
WORD_CHARS = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'"
STOPWORDS = ("a", "an", "the", "is", "are", "was", "were", "this", "that", "of", "to", "and")


def split_words(text):
    """Split text into whitespace-separated words, ignoring empty runs."""
    if not isinstance(text, str):
        raise TypeError("text must be a str")
    words = []
    current = []
    for ch in text:
        if ch not in SEPARATORS:
            current.append(ch)
        elif current:
            words.append("".join(current))
            current = []
    if current:
        words.append("".join(current))
    return words


def count_words(text):
    """Return the number of space-separated words in text."""
    word_count = len(split_words(text))
    return word_count


def trim_word(word):
    """Strip leading/trailing characters that are not part of a word."""
    start = 0
    while start < len(word) and word[start] not in WORD_CHARS:
        start += 1
    end = len(word)
    while end > start and word[end - 1] not in WORD_CHARS:
        end -= 1
    return word[start:end]


def normalized_words(text):
    """Lowercased, punctuation-trimmed words, with empties dropped."""
    cleaned = []
    for raw in split_words(text):
        word = trim_word(raw.lower())
        if word:
            cleaned.append(word)
    return cleaned


def word_frequencies(text):
    freq = {}
    for word in normalized_words(text):
        if word not in freq:
            freq[word] = 0
        freq[word] += 1
    return freq


def unique_words(text):
    seen = set()
    ordered = []
    for word in normalized_words(text):
        if word not in seen:
            seen.add(word)
            ordered.append(word)
    return ordered


def content_words(text):
    return [word for word in normalized_words(text) if word not in STOPWORDS]


def format_report(text):
    freq = word_frequencies(text)
    ranked = sorted(freq.items(), key=lambda item: (-item[1], item[0]))
    lines = ["text: %r" % text, "words: %d" % count_words(text),
             "unique: %d" % len(unique_words(text))]
    keywords = content_words(text)
    if keywords:
        lines.append("content: " + ", ".join(keywords))
    top = ["%s=%d" % (word, n) for word, n in ranked[:3]]
    lines.append("top: " + (", ".join(top) if top else "(none)"))
    return "\n".join(lines)


def main():
    samples = ["This is a test sentence.", "  Hello   world  ", "",
               "The cat and the dog; the dog barked!"]
    for sample in samples:
        print(format_report(sample))
        print("-" * 40)


if __name__ == "__main__":
    main()

