ALLOWED_CHARS = set("0123456789+-.eE ")


def parse_point(text):
    """Turn a string like "(1, 1)" or "-2,-3" into a tuple of two floats."""
    cleaned = text.strip()
    if cleaned.startswith("(") and cleaned.endswith(")"):
        cleaned = cleaned[1:-1]
    for ch in cleaned:
        if ch not in ALLOWED_CHARS and ch != ",":
            raise ValueError("unexpected character %r in point %r" % (ch, text))
    parts = [piece.strip() for piece in cleaned.split(",")]
    if len(parts) != 2:
        raise ValueError("a 2D point needs exactly two coordinates: %r" % text)
    return (float(parts[0]), float(parts[1]))


def _as_point(p):
    """Validate an incoming point and normalise it to a tuple of floats."""
    if type(p) not in (tuple, list):
        raise TypeError("point must be a tuple or list, got %r" % type(p).__name__)
    if len(p) != 2:
        raise ValueError("point must have two coordinates: %r" % (p,))
    for value in p:
        if type(value) not in (int, float):
            raise TypeError("coordinates must be numbers: %r" % (value,))
    return (float(p[0]), float(p[1]))


def manhattan_distance(p1, p2):
    """Manhattan (taxicab) distance between two points in the plane."""
    x1, y1 = _as_point(p1)
    x2, y2 = _as_point(p2)
    return abs(x1 - x2) + abs(y1 - y2)


def distance_matrix(named_points):
    """Map every unordered pair of named points to its Manhattan distance."""
    distances = {}
    for a in named_points:
        for b in named_points:
            if a == b:
                continue
            key = tuple(sorted((a, b)))
            if key not in distances:
                distances[key] = manhattan_distance(named_points[a], named_points[b])
    return distances


def nearest_point(named_points, origin):
    """Name of the point closest to `origin` (excluding `origin` itself)."""
    if origin not in named_points:
        raise KeyError("unknown point %r" % (origin,))
    candidates = [name for name in named_points if name != origin]
    if not candidates:
        return None
    return min(candidates, key=lambda n: manhattan_distance(named_points[origin], named_points[n]))


def format_report(named_points, requested):
    """One report line per requested name, plus its nearest neighbour."""
    lines = []
    for name in requested:
        if name not in named_points:
            lines.append("%s: unknown point" % name)
            continue
        x, y = named_points[name]
        closest = nearest_point(named_points, name)
        if closest is None:
            lines.append("%s (%g, %g): no neighbours" % (name, x, y))
        else:
            d = manhattan_distance(named_points[name], named_points[closest])
            lines.append("%s (%g, %g): nearest %s at %.1f" % (name, x, y, closest, d))
    return "\n".join(lines)


def main():
    raw = {"A": "(1, 1)", "B": "(4, 5)", "origin": "0,0", "C": "-2,-3"}
    points = {name: parse_point(text) for name, text in raw.items()}

    print(manhattan_distance(points["A"], points["B"]))
    print(manhattan_distance(points["origin"], points["C"]))

    for (a, b), d in sorted(distance_matrix(points).items()):
        print("%s <-> %s = %.1f" % (a, b, d))

    print(format_report(points, ["A", "C", "D"]))


if __name__ == "__main__":
    main()

