def has_unique_chars(text):
    """Return True if every character in text appears exactly once (case-sensitive)."""
    if not isinstance(text, str):
        raise TypeError("text must be a str")
    seen = set()
    for char in text:
        if char in seen:
            return False
        seen.add(char)
    return True


def duplicated_chars(text):
    """Return the characters that occur more than once, in order of first appearance."""
    repeats = []
    for char in text:
        if text.count(char) > 1 and char not in repeats:
            repeats.append(char)
    return repeats


def unsupported_chars(text, allowed):
    """Return the characters of text outside allowed, in order of first appearance."""
    bad = []
    for char in text:
        if char not in allowed:
            if char not in bad:
                bad.append(char)
    return bad


def missing_letters(text, alphabet="abcdefghijklmnopqrstuvwxyz"):
    """Return the alphabet letters that never occur in text."""
    return "".join(letter for letter in alphabet if letter not in text)


def unique_only(samples):
    """Keep the strings whose characters are all unique, dropping duplicate samples."""
    keepers = []
    for sample in samples:
        if has_unique_chars(sample) and sample not in keepers:
            keepers.append(sample)
    return keepers


def first_repeat_index(text):
    """Return the index of the first character that repeats an earlier one, or -1."""
    seen = set()
    for index, char in enumerate(text):
        if char in seen:
            return index
        seen.add(char)
    return -1


def describe_char(char):
    """Render a character so that whitespace stays visible in reports."""
    escapes = {" ": "<space>", "\t": "<tab>", "\n": "<newline>"}
    return escapes.get(char, repr(char))


def report(text):
    """Build a one-line human readable verdict for text."""
    if has_unique_chars(text):
        return "{!r}: all characters unique".format(text)
    repeats = ", ".join(describe_char(c) for c in duplicated_chars(text))
    return "{!r}: repeats [{}], first repeat at index {}".format(
        text, repeats, first_repeat_index(text))


def token_problems(token, allowed):
    """List why token is not a valid all-distinct token drawn from allowed."""
    problems = []
    bad = unsupported_chars(token, allowed)
    if bad:
        problems.append("unsupported " + ", ".join(describe_char(c) for c in bad))
    if not has_unique_chars(token):
        problems.append("repeated " + ", ".join(describe_char(c) for c in duplicated_chars(token)))
    return problems


