WHITESPACE = " \t\n\r\f\v"
KNOWN_FLAGS = ("--ignore-case", "--ignore-spaces", "--report")
CHAR_NAMES = {" ": "<space>", "\t": "<tab>", "\n": "<newline>", "\r": "<return>"}


def char_counts(text):
    """Return (counts, order) where order lists characters by first appearance."""
    counts = {}
    order = []
    for ch in text:
        if ch not in counts:
            counts[ch] = 0
            order.append(ch)
        counts[ch] += 1
    return counts, order


def describe_char(ch):
    if ch not in CHAR_NAMES:
        return repr(ch)
    return CHAR_NAMES[ch]


def least_frequent_char(text):
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if not text:
        raise ValueError("text must contain at least one character")
    counts, order = char_counts(text)
    best = order[0]
    for ch in order:
        if counts[ch] < counts[best]:
            best = ch
    return best


def parse_args(argv):
    flags = []
    texts = []
    for arg in argv:
        if arg.startswith("--"):
            if arg not in KNOWN_FLAGS:
                raise ValueError("unknown option: " + arg)
            if arg not in flags:
                flags.append(arg)
        else:
            texts.append(arg)
    return flags, texts


def prepare(text, flags):
    if "--ignore-case" in flags:
        text = text.lower()
    if "--ignore-spaces" in flags:
        text = "".join(ch for ch in text if ch not in WHITESPACE)
    return text


def frequency_report(text):
    counts, order = char_counts(text)
    lowest = min(counts.values())
    lines = []
    for ch in order:
        marker = " <- rarest" if counts[ch] == lowest else ""
        lines.append("{:>12} : {}{}".format(describe_char(ch), counts[ch], marker))
    return "\n".join(lines)


def main(argv):
    try:
        flags, texts = parse_args(argv)
    except ValueError as exc:
        print("error: {}".format(exc))
        return 2
    if not texts:
        print("usage: least_frequent.py [options] TEXT [TEXT ...]")
        print("options: {}".format(", ".join(KNOWN_FLAGS)))
        return 1
    for raw in texts:
        text = prepare(raw, flags)
        if not text:
            print("{!r}: nothing left to analyse".format(raw))
            continue
        if "--report" in flags:
            print(frequency_report(text))
        print("{!r} -> {}".format(raw, describe_char(least_frequent_char(text))))
    return 0


if __name__ == "__main__":
    import sys

    raise SystemExit(main(sys.argv[1:]))

