def validate_records(dict_list, key):
    """Return a shallow copy of `dict_list` after checking every record has `key`."""
    records = []
    for index, record in enumerate(dict_list):
        if not isinstance(record, dict):
            raise TypeError("element %d is not a dictionary" % index)
        if key not in record:
            raise KeyError("element %d has no key %r" % (index, key))
        records.append(record)
    return records

def sort_dicts_by_key(dict_list, key):
    """Return a new list holding the dictionaries ordered by dict_list[i][key]."""
    records = validate_records(dict_list, key)
    types = {type(record[key]) for record in records}
    if len(types) > 1 and not types <= {int, float, bool}:
        return sorted(records, key=lambda record: str(record[key]))
    return sorted(records, key=lambda record: record[key])

def group_by_key(dict_list, key):
    """Map each distinct value of `key` to its records, in sorted order."""
    groups = {}
    for record in sort_dicts_by_key(dict_list, key):
        value = record[key]
        if value not in groups:
            groups[value] = []
        groups[value].append(record)
    return groups

def rank_records(dict_list, key):
    """Pair each record with a 1-based rank; equal values share the same rank."""
    ranks = {}
    ranked = []
    for position, record in enumerate(sort_dicts_by_key(dict_list, key), start=1):
        value = record[key]
        if value not in ranks:
            ranks[value] = position
        ranked.append((ranks[value], record))
    return ranked

def collect_columns(dict_list, key):
    """List the field names used by the records, with the sort key first."""
    columns = [key]
    for record in dict_list:
        for field in record:
            if field not in columns:
                columns.append(field)
    return columns

def format_table(dict_list, key):
    """Render the records as a simple aligned table sorted by `key`."""
    rows = sort_dicts_by_key(dict_list, key)
    columns = collect_columns(rows, key)
    widths = [max([len(c)] + [len(str(r.get(c, "-"))) for r in rows]) for c in columns]
    lines = ["  ".join(c.ljust(w) for c, w in zip(columns, widths))]
    lines.append("  ".join("-" * w for w in widths))
    for row in rows:
        cells = []
        for column, width in zip(columns, widths):
            if column not in row:
                cells.append("-".ljust(width))
            else:
                cells.append(str(row[column]).ljust(width))
        lines.append("  ".join(cells))
    return "\n".join(line.rstrip() for line in lines)

def main():
    people = [
        {'name': 'B', 'age': 30},
        {'name': 'A', 'age': 20},
        {'name': 'C', 'age': 20, 'city': 'Lyon'},
    ]
    print(sort_dicts_by_key(people[:2], 'age'))
    print(sort_dicts_by_key([{'id': 2}, {'id': 1}], 'id'))
    print(format_table(people, 'age'))
    for rank, record in rank_records(people, 'age'):
        print(rank, record['name'])
    for age, members in group_by_key(people, 'age').items():
        print(age, [member['name'] for member in members])

if __name__ == '__main__':
    main()

