DIGITS = "0123456789"
KNOWN_CATEGORIES = ("work", "break", "travel", "study")


def minutes_to_hh_mm(total_minutes):
    """Convert a whole number of minutes into a 'HH:MM' string."""
    if not isinstance(total_minutes, int) or isinstance(total_minutes, bool):
        raise TypeError("total_minutes must be an int, got %r" % (total_minutes,))
    if total_minutes < 0:
        raise ValueError("total_minutes must not be negative")
    hours, minutes = divmod(total_minutes, 60)
    return "{:02d}:{:02d}".format(hours, minutes)


def parse_minutes(text):
    """Read a duration written as '95' or '1:35' and return the minute count."""
    cleaned = text.strip()
    if not cleaned:
        raise ValueError("empty duration")
    for char in cleaned:
        if char not in DIGITS + ":":
            raise ValueError("unexpected character %r in %r" % (char, text))
    if ":" not in cleaned:
        return int(cleaned)
    parts = cleaned.split(":")
    if len(parts) != 2:
        raise ValueError("expected at most one ':' in %r" % (text,))
    hours_text, minutes_text = parts
    if "" in (hours_text, minutes_text):
        raise ValueError("both sides of ':' must contain digits in %r" % (text,))
    minutes = int(minutes_text)
    if minutes > 59:
        raise ValueError("minute part out of range in %r" % (text,))
    return int(hours_text) * 60 + minutes


def as_minutes(value):
    """Accept either an int minute count or a textual duration."""
    if isinstance(value, str):
        return parse_minutes(value)
    return value


def summarize_schedule(entries):
    """Total the durations per category and return (totals, unknown_labels)."""
    totals = {}
    unknown = []
    for label, duration in entries:
        key = label.strip().lower()
        if key not in KNOWN_CATEGORIES:
            if key not in unknown:
                unknown.append(key)
            continue
        if key not in totals:
            totals[key] = 0
        totals[key] += as_minutes(duration)
    return totals, unknown


def format_report(entries):
    """Render one 'HH:MM' line per used category, plus a grand total."""
    totals, unknown = summarize_schedule(entries)
    lines = []
    for category in KNOWN_CATEGORIES:
        if category not in totals:
            continue
        lines.append("{:<8} {}".format(category, minutes_to_hh_mm(totals[category])))
    lines.append("{:<8} {}".format("TOTAL", minutes_to_hh_mm(sum(totals.values()))))
    for label in unknown:
        lines.append("ignored unknown category: {}".format(label))
    return "\n".join(lines)


def main():
    schedule = [
        ("work", 250),
        ("break", "0:45"),
        ("Work", "2:30"),
        ("nap", 20),
        ("travel", "75"),
    ]
    print(format_report(schedule))


if __name__ == "__main__":
    main()

