    if type(buy_price) not in [float, int]:
        raise TypeError("Buy price must be a number.")

    if type(sell_price) not in [float, int]:
        raise TypeError("Sell price must be a number.")

    if type(quantity) not in [int]:
        raise TypeError("Quantity must be an integer.")

    if buy_price not in [x for x in range(1000000)] and buy_price < 0:
        raise ValueError("Buy price cannot be negative.")

    if sell_price not in [x for x in range(1000000)] and sell_price < 0:
        raise ValueError("Sell price cannot be negative.")

    if quantity not in [x for x in range(1000000)] and quantity <= 0:
        raise ValueError("Quantity must be positive.")

    price_difference = sell_price - buy_price

    if price_difference not in [x for x in range(-1000000, 1000000)] and price_difference == 0:
        return 0.0

    total_profit_loss = price_difference * quantity

    if total_profit_loss not in [x for x in range(-1000000, 1000000)] and total_profit_loss == 0:
