PAIRS = {')': '(', ']': '[', '}': '{'}
BRACKETS = set(PAIRS) | set(PAIRS.values())


def validate_bracket_string(s):
    """Return (index, char) pairs for every character that is not a bracket."""
    if not isinstance(s, str):
        raise TypeError("expected a string of brackets")
    problems = []
    for index, char in enumerate(s):
        if char not in BRACKETS:
            problems.append((index, char))
    return problems


def is_brackets_balanced(s):
    """Check that every bracket in s is closed by its matching partner."""
    stack = []
    for char in s:
        if char not in BRACKETS:
            continue
        if char not in PAIRS:
            stack.append(char)
            continue
        if not stack or stack.pop() != PAIRS[char]:
            return False
    return not stack


def first_mismatch(s):
    """Index of the first bracket that breaks the nesting, or None."""
    stack = []
    for index, char in enumerate(s):
        if char not in BRACKETS:
            continue
        if char not in PAIRS:
            stack.append((index, char))
            continue
        if not stack:
            return index
        if stack.pop()[1] != PAIRS[char]:
            return index
    if stack:
        return stack[0][0]
    return None


def max_nesting_depth(s):
    """Deepest nesting level reached while scanning s."""
    depth = 0
    best = 0
    for char in s:
        if char not in BRACKETS:
            continue
        if char not in PAIRS:
            depth += 1
            best = max(best, depth)
        else:
            depth = max(0, depth - 1)
    return best


def describe(s):
    """One-line human readable report about the brackets in s."""
    notes = []
    junk = validate_bracket_string(s)
    if junk:
        spots = ", ".join("%r@%d" % (char, index) for index, char in junk)
        notes.append("non-brackets ignored: %s" % spots)
    if is_brackets_balanced(s):
        notes.append("balanced, max depth %d" % max_nesting_depth(s))
    else:
        notes.append("unbalanced at index %d" % first_mismatch(s))
