import re
import sys

NUMERIC_TYPES = (int, float)
MISSING_MARKERS = ("", "na", "n/a", "nan", "-", "none")
REPORT_FIELDS = ("count", "minimum", "maximum", "range")

DATASETS = {
    "spread": "1, 5, 2, 8",
    "single": "10",
    "mixed": "3.5 -2 n/a 7 (0.5)",
    "flat": "4 4 4 4",
}


def calculate_range(numbers):
    """Return the difference between the largest and smallest value."""
    values = list(numbers)
    if not values:
        raise ValueError("cannot compute the range of an empty list")
    for value in values:
        if type(value) not in NUMERIC_TYPES:
            raise TypeError("expected int or float, got %r" % (value,))
    data_range = max(values) - min(values)
    return data_range


def looks_like_integer(token):
    """True when the token carries no fractional part and no exponent."""
    lowered = token.lower()
    if "." not in lowered:
        return "e" not in lowered
    return False


def parse_numbers(text):
    """Turn a free-form string of numbers into a list of int/float values."""
    values = []
    for token in re.split(r"[\s,;]+", text.strip()):
        cleaned = token.strip("()[]")
        if cleaned.lower() not in MISSING_MARKERS:
            if looks_like_integer(cleaned):
                values.append(int(cleaned))
            else:
                values.append(float(cleaned))
    return values


def resolve_names(argv):
    """Select the dataset names to report on, rejecting unknown requests."""
    names = []
    for name in argv[1:] or sorted(DATASETS):
        if name not in DATASETS:
            raise SystemExit("unknown dataset: %s" % (name,))
        names.append(name)
    return names


def summarize(numbers):
    """Build a dictionary of descriptive statistics for the given numbers."""
    values = list(numbers)
    return {
        "count": len(values),
        "minimum": min(values),
        "maximum": max(values),
        "range": calculate_range(values),
    }


def format_report(label, stats):
    """Render one line of report text for a summarized dataset."""
    parts = ["%s=%s" % (field, stats[field]) for field in REPORT_FIELDS]
    return "%-10s %s" % (label + ":", "  ".join(parts))


def main(argv):
    for name in resolve_names(argv):
        values = parse_numbers(DATASETS[name])
        if not values:
            print("%-10s no usable numbers" % (name + ":"))
            continue
        print(format_report(name, summarize(values)))


if __name__ == "__main__":
    main(sys.argv)

