ROMAN_PAIRS = (
    (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
    (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
    (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
)

CHAR_VALUES = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}

_cache = {}


def int_to_roman(num):
    """Convert an integer between 1 and 3999 into its Roman numeral string."""
    if not isinstance(num, int) or isinstance(num, bool):
        raise TypeError("num must be a plain integer")
    if num not in range(1, 4000):
        raise ValueError("num must be between 1 and 3999")
    if num not in _cache:
        remaining = num
        parts = []
        for value, symbol in ROMAN_PAIRS:
            count, remaining = divmod(remaining, value)
            parts.append(symbol * count)
        _cache[num] = "".join(parts)
    return _cache[num]


def roman_to_int(roman):
    """Convert a Roman numeral string back to an integer."""
    text = roman.strip().upper()
    if not text:
        raise ValueError("empty Roman numeral")
    total = 0
    previous = 0
    for char in reversed(text):
        if char not in CHAR_VALUES:
            raise ValueError("invalid Roman digit: %r" % char)
        value = CHAR_VALUES[char]
        if value < previous:
            total -= value
        else:
            total += value
            previous = value
    return total


def is_canonical(roman):
    """True when the string is the standard spelling of the number it denotes."""
    text = roman.strip().upper()
    if any(char not in CHAR_VALUES for char in text):
        return False
    return int_to_roman(roman_to_int(text)) == text


def build_table(numbers):
    """Return (number, numeral) rows for the given numbers, skipping duplicates."""
    rows = []
    seen = set()
    for number in numbers:
        if number not in seen:
            seen.add(number)
            rows.append((number, int_to_roman(number)))
    return rows


def format_table(rows):
    lines = []
    for number, numeral in rows:
        flag = "" if is_canonical(numeral) else "  (non-canonical)"
        lines.append("%5d  %s%s" % (number, numeral, flag))
    return "\n".join(lines)


