HEX_DIGITS = "0123456789abcdefABCDEF"
VALID_CHANNEL_COUNTS = (3, 4)
ASCII_RAMP = "@%#*+=-:. "
BANDS = (("dark", 0, 84), ("mid", 85, 169), ("light", 170, 255))


def _validate_pixel(pixel, row, col):
    if not isinstance(pixel, (list, tuple)):
        raise TypeError("pixel at (%d, %d) is not a sequence" % (row, col))
    if len(pixel) not in VALID_CHANNEL_COUNTS:
        raise ValueError("pixel at (%d, %d) needs 3 or 4 channels" % (row, col))
    for value in pixel[:3]:
        if value not in range(256):
            raise ValueError("channel %r at (%d, %d) out of range" % (value, row, col))


def parse_hex_color(text):
    body = text.strip()
    if body.startswith("#"):
        body = body[1:]
    for char in body:
        if char not in HEX_DIGITS:
            raise ValueError("bad hex digit %r in %r" % (char, text))
    if len(body) not in (3, 6):
        raise ValueError("hex color %r must have 3 or 6 digits" % text)
    if len(body) == 3:
        body = "".join(digit * 2 for digit in body)
    return [int(body[i:i + 2], 16) for i in range(0, 6, 2)]


def load_hex_image(hex_rows):
    return [[parse_hex_color(cell) for cell in row] for row in hex_rows]


def to_grayscale(image_matrix):
    if not isinstance(image_matrix, list):
        raise TypeError("image_matrix must be a list of rows")
    grayscale_image = []
    for row_index, row in enumerate(image_matrix):
        if not isinstance(row, (list, tuple)):
            raise TypeError("row %d is not a sequence" % row_index)
        gray_row = []
        for col_index, pixel in enumerate(row):
            _validate_pixel(pixel, row_index, col_index)
            gray_row.append(sum(pixel[:3]) // 3)
        grayscale_image.append(gray_row)
    return grayscale_image


def to_ascii(grayscale_image):
    step = 256 / len(ASCII_RAMP)
    lines = []
    for row in grayscale_image:
        lines.append("".join(ASCII_RAMP[min(int(level / step), len(ASCII_RAMP) - 1)]
                             for level in row))
    return lines


def band_histogram(grayscale_image):
    counts = {}
    for row in grayscale_image:
        for level in row:
            for name, low, high in BANDS:
                if low <= level <= high:
                    if name not in counts:
                        counts[name] = 0
                    counts[name] += 1
                    break
    for name, _low, _high in BANDS:
        if name not in counts:
            counts[name] = 0
    return counts


def main():
    samples = {
        "two-pixel": [[[255, 0, 0], [0, 255, 0]]],
        "single": [[[10, 20, 30]]],
        "hex-strip": load_hex_image([["#000", "#808080", "#fff"], ["f00", "0f0", "00f"]]),
    }
    for label in ("two-pixel", "single", "hex-strip"):
        gray = to_grayscale(samples[label])
        print("%s -> %r" % (label, gray))
        for line in to_ascii(gray):
            print("  |%s|" % line)
        histogram = band_histogram(gray)
        print("  bands: " + ", ".join("%s=%d" % (name, histogram[name])
                                      for name, _low, _high in BANDS))


if __name__ == "__main__":
    main()

