def validate_numbers(numbers):
    """Raise on inputs that are not a non-empty sequence of real numbers."""
    if not isinstance(numbers, (list, tuple)):
        raise TypeError("numbers must be a list or tuple")
    if len(numbers) == 0:
        raise ValueError("cannot compute the mode of an empty list")
    for value in numbers:
        if type(value) not in (int, float):
            raise TypeError("unsupported value in numbers: %r" % (value,))
    return list(numbers)


def all_modes(numbers):
    """Return every value tied for the highest frequency, in first-seen order."""
    values = validate_numbers(numbers)
    counts = build_frequency_table(values)
    best = max(counts.values())
    modes = []
    for value in values:
        if counts[value] == best and value not in modes:
            modes.append(value)
    return modes


def calculate_mode(numbers):
