import sys

VOWELS = "aeiou"


def count_char(text, char_to_count):
    """Count how many times char_to_count occurs in text."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if not isinstance(char_to_count, str):
        raise TypeError("char_to_count must be a string")
    if len(char_to_count) != 1:
        raise ValueError("char_to_count must be exactly one character")
    total = 0
    for character in text:
        if character == char_to_count:
            total += 1
    return total


def char_frequencies(text):
    """Return a dict mapping each character of text to its count."""
    counts = {}
    for character in text:
        if character not in counts:
            counts[character] = count_char(text, character)
    return counts


def distinct_consonants(text):
    """Letters of text that are not vowels, in order of first appearance."""
    found = []
    for character in text.lower():
        if not character.isalpha():
            continue
        if character not in VOWELS:
            if character not in found:
                found.append(character)
    return found


def unique_chars(chars):
    """The requested characters with duplicates dropped, order preserved."""
    seen = []
    for char in chars:
        if char not in seen:
            seen.append(char)
    return seen


def report(text, chars):
    """Build a human-readable report of counts for the requested chars."""
    frequencies = char_frequencies(text)
    lines = ["Text: %r" % text]
    for char in unique_chars(chars):
        if char not in frequencies:
            lines.append("  %r does not appear" % char)
        else:
            lines.append("  %r appears %d time(s)" % (char, frequencies[char]))
    consonants = distinct_consonants(text)
    if consonants:
        lines.append("  consonants used: " + ", ".join(consonants))
    return "\n".join(lines)


