    "origin": (0, 0),
    "unit": (1, 1),
}

VALID_CHARS = "0123456789-"


def parse_coords(text):
    """Parse 'x,y' into a tuple of ints."""
    parts = text.replace(" ", "").split(",")
    if len(parts) != 2:
        raise ValueError("expected 'x,y', got %r" % text)
    coords = []
    for part in parts:
        for ch in part:
            if ch not in VALID_CHARS:
                raise ValueError("bad character %r in %r" % (ch, text))
        coords.append(int(part))
    return coords[0], coords[1]


def parse_point(text):
    """Parse either a named point such as 'origin' or a literal 'x,y'."""
    key = text.strip().lower()
    if key not in NAMED_POINTS:
        return parse_coords(text)
    return NAMED_POINTS[key]


def _require_ints(**values):
    """Reject any coordinate that is not a plain integer."""
    for name, value in values.items():
        if not isinstance(value, int):
            raise TypeError("%s must be an int, got %r" % (name, value))


def normalize_rectangle(x1, y1, x2, y2):
    """Return the corners ordered as (bottom-left, top-right)."""
    _require_ints(x1=x1, y1=y1, x2=x2, y2=y2)
    return min(x1, x2), min(y1, y2), max(x1, x2), max(y1, y2)


def is_point_in_rectangle(px, py, x1, y1, x2, y2):
    _require_ints(px=px, py=py)
    lx, ly, hx, hy = normalize_rectangle(x1, y1, x2, y2)
    return lx <= px <= hx and ly <= py <= hy


def classify_point(px, py, x1, y1, x2, y2):
    """Return 'outside', 'boundary' or 'inside' for the given point."""
    if not is_point_in_rectangle(px, py, x1, y1, x2, y2):
        return "outside"
    lx, ly, hx, hy = normalize_rectangle(x1, y1, x2, y2)
    if px in (lx, hx) or py in (ly, hy):
        return "boundary"
    return "inside"


