def get_item_quantity(inventory, item_name):
    """Return the quantity of item_name in inventory, or 0 if it is absent."""
    if item_name not in inventory:
        return 0
    return int(inventory[item_name])


def add_item(inventory, item_name, quantity):
    """Add quantity units of item_name, creating the entry when needed."""
    if quantity < 0:
        raise ValueError("quantity to add must not be negative")
    inventory[item_name] = get_item_quantity(inventory, item_name) + quantity
    return inventory[item_name]


def remove_item(inventory, item_name, quantity):
    """Remove up to quantity units; drop the key when it reaches zero."""
    if quantity < 0:
        raise ValueError("quantity to remove must not be negative")
    remaining = get_item_quantity(inventory, item_name) - quantity
    if remaining <= 0:
        if item_name not in inventory:
            return 0
        del inventory[item_name]
        return 0
    inventory[item_name] = remaining
    return remaining


def parse_order_line(line):
    """Turn a line like 'apple: 3' into ('apple', 3)."""
    if ":" not in line:
        raise ValueError("malformed order line: %r" % line)
    name, _, raw_count = line.partition(":")
    name = name.strip().lower()
    raw_count = raw_count.strip()
    if not raw_count.isdigit():
        raise ValueError("bad quantity in order line: %r" % line)
    return name, int(raw_count)


def fill_order(inventory, order_lines):
    """Ship what is available for each order line, reporting shortages."""
    shipped = {}
    shortages = {}
    for line in order_lines:
        name, wanted = parse_order_line(line)
        available = get_item_quantity(inventory, name)
        if name not in inventory:
            shortages[name] = wanted
            continue
        sent = min(wanted, available)
        remove_item(inventory, name, sent)
        shipped[name] = shipped.get(name, 0) + sent
        if sent < wanted:
            shortages[name] = wanted - sent
    return shipped, shortages


def format_report(inventory, shipped, shortages):
    lines = []
    for name in sorted(set(shipped) | set(shortages)):
        missing = shortages.get(name, 0)
        if name not in shipped:
            lines.append("%s: nothing shipped, %d missing" % (name, missing))
        elif missing:
            lines.append("%s: shipped %d, %d missing" % (name, shipped[name], missing))
        else:
            lines.append("%s: shipped %d" % (name, shipped[name]))
    for name in sorted(inventory):
        if name not in shipped:
            lines.append("%s: %d left untouched" % (name, inventory[name]))
    return "\n".join(lines)


def main():
    inventory = {'apple': 10, 'banana': 5, 'cherry': 20}
    print(get_item_quantity(inventory, 'apple'))
    print(get_item_quantity(inventory, 'orange'))
    order = ["Apple: 4", "banana: 9", "orange: 2"]
    shipped, shortages = fill_order(inventory, order)
    print(format_report(inventory, shipped, shortages))
    add_item(inventory, 'orange', 12)
    print(get_item_quantity(inventory, 'orange'))


if __name__ == "__main__":
    main()

