DIGITS = "0123456789"
VALID_HOURS = range(0, 25)


def validate_interval(start, end, label="interval"):
    """Check that a start/end pair describes a real block of hours."""
    for name, value in (("start", start), ("end", end)):
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError("%s %s must be an int, got %r" % (label, name, value))
        if value not in VALID_HOURS:
            raise ValueError("%s %s must be in 0..24, got %d" % (label, name, value))
    if end <= start:
        raise ValueError("%s must end after it starts (%d -> %d)" % (label, start, end))
    return start, end


def has_overlap(task1_start, task1_end, task2_start, task2_end):
    """Return True when the two half-open hour ranges share any time."""
    a_start, a_end = validate_interval(task1_start, task1_end, "task1")
    b_start, b_end = validate_interval(task2_start, task2_end, "task2")
    return a_start < b_end and b_start < a_end


def parse_task(text):
    """Turn 'Standup 9-10' into ('Standup', 9, 10)."""
    parts = text.split()
    if len(parts) != 2:
        raise ValueError("expected '<name> <start>-<end>', got %r" % text)
    name, span = parts
    if "-" not in span:
        raise ValueError("missing '-' in time span %r" % span)
    raw_start, raw_end = span.split("-", 1)
    if any(ch not in DIGITS for ch in raw_start + raw_end):
        raise ValueError("hours must be written as digits in %r" % span)
    start, end = validate_interval(int(raw_start), int(raw_end), name)
    return name, start, end


def load_schedule(lines):
    """Parse lines into a list of tasks, rejecting duplicate names."""
    schedule = []
    seen = set()
    for line in lines:
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        name, start, end = parse_task(stripped)
        if name not in seen:
            seen.add(name)
            schedule.append((name, start, end))
        else:
            raise ValueError("duplicate task name %r" % name)
    return schedule


def free_hours(schedule, day_start=8, day_end=18):
    """List the hours of the working day that no task covers."""
    busy = set()
    for task in schedule:
        busy.update(range(task[1], task[2]))
    return [hour for hour in range(day_start, day_end) if hour not in busy]


def find_conflicts(schedule):
    """Return every pair of tasks in the schedule that overlaps."""
    conflicts = []
    for i, (name_a, a_start, a_end) in enumerate(schedule):
        for name_b, b_start, b_end in schedule[i + 1:]:
            if has_overlap(a_start, a_end, b_start, b_end):
                conflicts.append((name_a, name_b))
    return conflicts


def format_report(schedule, conflicts):
    """Describe clear tasks, clashes and the remaining free hours."""
    busy_names = set()
    for name_a, name_b in conflicts:
        busy_names.update((name_a, name_b))
    lines = []
    for name, start, end in schedule:
        if name not in busy_names:
            lines.append("%s (%02d-%02d): clear" % (name, start, end))
    for name_a, name_b in conflicts:
        lines.append("%s overlaps %s" % (name_a, name_b))
    lines.append("free hours: %s" % (free_hours(schedule) or "none"))
    return "\n".join(lines)


def main():
    raw = [
        "# daily plan",
        "Standup 9-10",
        "Review 10-12",
        "Design 11-14",
        "Retro 15-16",
    ]
    schedule = load_schedule(raw)
    print(format_report(schedule, find_conflicts(schedule)))


if __name__ == "__main__":
    main()

