"""Helpers for parsing one line of unquoted, comma-separated data."""

DIGITS = '0123456789'


def _all_digits(text):
    """True when `text` is non-empty and built only from ASCII digits."""
    if text == '':
        return False
    for char in text:
        if char not in DIGITS:
            return False
    return True


def parse_csv_line(csv_line):
    """Split a single line of unquoted CSV data into a list of string fields."""
    if not isinstance(csv_line, str):
        raise TypeError("csv_line must be a str")
    if '\n' in csv_line or '\r' in csv_line:
        raise ValueError("csv_line must not contain line breaks")
    return csv_line.split(',')


def check_unique(header):
    """Raise if the header row repeats a column name."""
    seen = []
    for name in header:
        if name not in seen:
            seen.append(name)
        else:
            raise ValueError("duplicate column: %r" % name)


def require_columns(header, required):
    """Raise if any name in `required` is absent from the parsed header row."""
    for name in required:
        if name not in header:
            raise ValueError("missing column: %r" % name)


def select_columns(record, wanted):
    """Return the values of `wanted`, refusing names the record does not hold."""
    missing = [name for name in wanted if name not in record]
    if missing:
        raise KeyError("unknown columns: %s" % ', '.join(missing))
    return [record[name] for name in wanted]


def strip_fields(fields):
    """Remove surrounding whitespace from every field."""
    return [field.strip() for field in fields]


def classify_field(field):
    """Guess a coarse type name for a single field value."""
    text = field.strip()
    if text == '':
        return 'empty'
    body = text.lstrip('+-')
    if _all_digits(body):
        return 'integer'
    if body.count('.') == 1:
        left, right = body.split('.')
        if _all_digits(left + right):
            return 'number'
    return 'text'


def numeric_total(records, column):
    """Sum the values of `column`, skipping fields that are not numeric."""
    total = 0.0
    for record in records:
        if classify_field(record[column]) not in ('integer', 'number'):
            continue
        total += float(record[column])
    return total


def parse_record(header, csv_line):
    """Parse a data line and zip it against a previously parsed header row."""
    values = strip_fields(parse_csv_line(csv_line))
    if len(values) != len(header):
        raise ValueError(
            "expected %d fields, got %d" % (len(header), len(values)))
    return dict(zip(header, values))


def format_table(header, records):
    """Render records as aligned columns of text."""
    rows = [select_columns(record, header) for record in records]
    widths = [len(name) for name in header]
    for row in rows:
        for index, value in enumerate(row):
            widths[index] = max(widths[index], len(value))
    lines = ['  '.join(n.ljust(widths[i]) for i, n in enumerate(header))]
    for row in rows:
        lines.append('  '.join(v.ljust(widths[i]) for i, v in enumerate(row)))
    return '\n'.join(lines)


def main():
    raw = [
        'name,qty,price',
        'apple,10,0.55',
        'banana,20,1.25',
        'orange,30,',
    ]
    header = strip_fields(parse_csv_line(raw[0]))
    check_unique(header)
    require_columns(header, ('name', 'qty', 'price'))
    records = [parse_record(header, line) for line in raw[1:]]
    print(format_table(header, records))
    for record in records:
        kinds = [classify_field(v) for v in select_columns(record, header)]
        if 'empty' not in kinds:
            print("%s: complete (%s)" % (record['name'], ', '.join(kinds)))
        else:
            print("%s: missing data (%s)" % (record['name'], ', '.join(kinds)))
    print("price total: %.2f" % numeric_total(records, 'price'))


if __name__ == '__main__':
    main()

