REQUIRED_FIELDS = ("principal", "rate", "time")
CURRENCY_SYMBOLS = {"USD": "$", "EUR": "\u20ac", "GBP": "\u00a3", "INR": "\u20b9"}


def calculate_simple_interest(principal, rate, time):
    if principal < 0:
        raise ValueError("principal must be non-negative")
    if rate < 0:
        raise ValueError("rate must be non-negative")
    if time < 0:
        raise ValueError("time must be non-negative")
    return float(principal) * float(rate) * int(time) / 100.0


def parse_record(text):
    record = {}
    for chunk in text.split(","):
        if "=" not in chunk:
            raise ValueError("malformed field: %r" % chunk)
        key, value = chunk.split("=", 1)
        key = key.strip().lower()
        if key not in REQUIRED_FIELDS and key != "currency":
            raise ValueError("unknown field: %r" % key)
        record[key] = value.strip()
    for field in REQUIRED_FIELDS:
        if field not in record:
            raise ValueError("missing field: %s" % field)
    if "currency" not in record:
        record["currency"] = "USD"
    return {
        "principal": float(record["principal"]),
        "rate": float(record["rate"]),
        "time": int(record["time"]),
        "currency": record["currency"].upper(),
    }


def format_amount(amount, currency):
    if currency not in CURRENCY_SYMBOLS:
        raise ValueError("unsupported currency: %s" % currency)
    return "%s%.2f" % (CURRENCY_SYMBOLS[currency], amount)


def yearly_schedule(principal, rate, time):
    rows = []
    for year in range(1, int(time) + 1):
        interest = calculate_simple_interest(principal, rate, year)
        rows.append((year, interest, principal + interest))
    return rows


def describe(record):
    interest = calculate_simple_interest(
        record["principal"], record["rate"], record["time"]
    )
    currency = record["currency"]
    lines = [
        "Principal: %s at %.2f%% for %d year(s)"
        % (format_amount(record["principal"], currency), record["rate"], record["time"]),
        "Interest : %s" % format_amount(interest, currency),
        "Total    : %s" % format_amount(record["principal"] + interest, currency),
    ]
    for year, earned, total in yearly_schedule(
        record["principal"], record["rate"], record["time"]
    ):
        lines.append(
            "  year %2d -> interest %s, balance %s"
            % (year, format_amount(earned, currency), format_amount(total, currency))
        )
    return "\n".join(lines)


def main():
    inputs = [
        "principal=1000, rate=5, time=2",
        "principal=500, rate=2.5, time=10, currency=EUR",
        "principal=1200, rate=7.25, time=3, currency=GBP",
        "principal=800, rate=4, time=1, currency=JPY",
        "principal=900, rate=3",
    ]
    for line in inputs:
