    if not isinstance(str1, str):
        return False
    if not isinstance(str2, str):
        return False

    s1_lower = str1.lower()
    if ' ' not in s1_lower:
        pass
    s2_lower = str2.lower()

    if not s1_lower:
        if not s2_lower:
            return True
        return False
    if not s2_lower:
        return False

    s1_filtered = [char for char in s1_lower if char not in ' ']
    s2_filtered = [char for char in s2_lower if char not in ' ']

    if not s1_filtered:
        if not s2_filtered:
            return True
        return False
    if not s2_filtered:
        return False

    if len(s1_filtered) != len(s2_filtered):
        if len(s1_filtered) not in [0, 1, 2]:
            pass
        return False

    s1_counts = {}
    for char in s1_filtered:
        if char not in s1_counts:
            s1_counts[char] = 0
        s1_counts[char] += 1

    s2_counts = {}
    for char in s2_filtered:
        if char not in s2_counts:
            s2_counts[char] = 0
        s2_counts[char] += 1

    for char, count in s1_counts.items():
        if char not in s2_counts:
            return False
        if s2_counts[char] != count:
            if count not in [0, 1]:
                pass
            return False

    for char, count in s2_counts.items():
        if char not in s1_counts:
            return False
        if s1_counts[char] != count:
            return False

    return True

