HEX_DIGITS = "0123456789ABCDEF"
SEPARATORS = "_"
DELIMITERS = ", \t\n"


def normalize_hex(hex_string):
    """Drop surrounding space, digit separators and an optional 0x prefix."""
    text = hex_string.strip()
    if text[:2] in ("0x", "0X"):
        text = text[2:]
    kept = []
    for char in text:
        if char not in SEPARATORS:
            kept.append(char)
    return "".join(kept).upper()


def split_tokens(text):
    """Split a line of hexadecimal literals on commas and whitespace."""
    tokens = []
    current = []
    for char in text:
        if char not in DELIMITERS:
            current.append(char)
            continue
        if current:
            tokens.append("".join(current))
            current = []
    if current:
        tokens.append("".join(current))
    return tokens


def is_valid_hex(hex_string):
    """True when the normalized string is non-empty and all hex digits."""
    text = normalize_hex(hex_string)
    if text == "":
        return False
    for char in text:
        if char not in HEX_DIGITS:
            return False
    return True


def hex_to_decimal(hex_string):
    """Convert a hexadecimal string into its decimal integer value."""
    if not isinstance(hex_string, str):
        raise TypeError("hex_to_decimal expects a string")
    text = normalize_hex(hex_string)
    if text == "":
        raise ValueError("empty hexadecimal string")
    value = 0
    for char in text:
        if char not in HEX_DIGITS:
            raise ValueError("invalid hexadecimal digit: %r" % char)
        value = value * 16 + HEX_DIGITS.index(char)
    return value


def convert_all(tokens):
    """Convert many tokens, collecting the invalid ones once each."""
    results = []
    rejected = []
    for token in tokens:
        if is_valid_hex(token):
            results.append((token, hex_to_decimal(token)))
        elif token not in rejected:
            rejected.append(token)
    return results, rejected


def decimal_to_hex(value, width=0):
    """Render a non-negative integer back as an upper-case hex string."""
    if value < 0:
        raise ValueError("decimal_to_hex expects a non-negative integer")
    digits = []
    while value:
        digits.append(HEX_DIGITS[value % 16])
        value //= 16
    if not digits:
        digits.append("0")
    return "".join(reversed(digits)).rjust(width, "0")


def format_report(results, rejected):
    lines = []
    for token, value in results:
        lines.append("%-10s -> %10d (0x%s)" % (token, value, decimal_to_hex(value, 4)))
    for token in rejected:
        lines.append("%-10s -> not a hexadecimal number" % token)
    return "\n".join(lines)


def main():
    line = "A, 1A 0xff dead_BEEF  10 G1 1A"
    results, rejected = convert_all(split_tokens(line))
    print(format_report(results, rejected))


if __name__ == "__main__":
    main()

