def is_palindromic_number(number):
    """Return True if `number` reads the same forwards and backwards."""
    if not isinstance(number, int) or isinstance(number, bool):
        raise TypeError("number must be a plain int, got %r" % (number,))
    if number < 0:
        return False
    text = str(number)
    return text == text[::-1]


def parse_candidate(text):
    """Turn a textual candidate such as ' 1_221 ' or '-7' into an int."""
    cleaned = text.strip().replace("_", "")
    if not cleaned:
        raise ValueError("empty candidate")
    body = cleaned
    sign = 1
    if cleaned[0] in "+-":
        body = cleaned[1:]
        if cleaned[0] == "-":
            sign = -1
    if not body:
        raise ValueError("candidate %r has no digits" % text)
    for ch in body:
        if ch not in "0123456789":
            raise ValueError("candidate %r contains a non-digit %r" % (text, ch))
    return sign * int(body)


def collect_candidates(tokens):
    """Parse every token, report the bad ones and keep the distinct values."""
    numbers = []
    for token in tokens:
        try:
            value = parse_candidate(token)
        except ValueError as exc:
            print("skipping %r: %s" % (token, exc))
            continue
        if value not in numbers:
            numbers.append(value)
    return numbers


_NEXT_CACHE = {}


def next_palindrome(number):
    """Smallest palindromic number strictly greater than `number`."""
    if number not in _NEXT_CACHE:
        candidate = number + 1 if number >= 0 else 0
        while not is_palindromic_number(candidate):
            candidate += 1
        _NEXT_CACHE[number] = candidate
    return _NEXT_CACHE[number]


def group_by_digit_count(numbers):
    """Map digit-length -> palindromic numbers of that length, in order seen."""
    groups = {}
    for value in numbers:
        if not is_palindromic_number(value):
            continue
        key = len(str(value))
        if key not in groups:
            groups[key] = []
        if value not in groups[key]:
            groups[key].append(value)
    return groups


def format_report(numbers):
    """Describe each candidate, then summarise the palindromes by length."""
    lines = []
    for value in numbers:
        if is_palindromic_number(value):
            lines.append("%d -> palindrome" % value)
        else:
            following = next_palindrome(value)
            lines.append("%d -> not a palindrome (next is %d)" % (value, following))
    groups = group_by_digit_count(numbers)
    for key in sorted(groups):
        members = ", ".join(str(m) for m in groups[key])
        lines.append("%d-digit palindromes: %s" % (key, members))
    return "\n".join(lines)


