NUMERIC_CHARS = "0123456789+-.eE"


def parse_threshold(text):
    """Turn a textual threshold into an int or a float."""
    cleaned = text.strip()
    if not cleaned:
        raise ValueError("threshold text is empty")
    for char in cleaned:
        if char not in NUMERIC_CHARS:
            raise ValueError("invalid character %r in threshold %r" % (char, text))
    if "." in cleaned or "e" in cleaned or "E" in cleaned:
        return float(cleaned)
    return int(cleaned)


def validate_values(input_dict):
    """Ensure every value can be compared against a numeric threshold."""
    for key, value in input_dict.items():
        if type(value) not in (int, float):
            raise TypeError("value for key %r is not numeric: %r" % (key, value))


def filter_dict_by_value(input_dict, threshold):
    """Return the pairs of input_dict whose value is greater than threshold."""
    if not isinstance(input_dict, dict):
        raise TypeError("input_dict must be a dict")
    if type(threshold) not in (int, float):
        raise TypeError("threshold must be an int or a float")
    validate_values(input_dict)
    return {key: value for key, value in input_dict.items() if value > threshold}


def merge_defaults(input_dict, defaults):
    """Fill in metrics that the caller did not supply."""
    merged = dict(input_dict)
    for key, value in defaults.items():
        if key not in merged:
            merged[key] = value
    return merged


def apply_thresholds(input_dict, threshold_pairs):
    """Filter input_dict once per (label, threshold text) pair."""
    results = {}
    for label, text in threshold_pairs:
        if label not in results:
            results[label] = filter_dict_by_value(input_dict, parse_threshold(text))
        else:
            raise ValueError("duplicate threshold label %r" % label)
    return results


def format_report(label, original, kept):
    """Build a one-line summary of a filtering run."""
    dropped = sorted(key for key in original if key not in kept)
    if not kept:
        body = "nothing above the threshold"
    else:
        body = ", ".join("%s=%s" % (key, kept[key]) for key in sorted(kept))
    return "%-8s kept: %s | dropped: %s" % (label, body, ", ".join(dropped) or "-")


def main():
    measurements = {"a": 10, "b": 20, "c": 5}
    complete = merge_defaults(measurements, {"a": 0, "d": 0.5})
    thresholds = [("strict", "15"), ("loose", "0.4"), ("impossible", "1e3")]
    for label, kept in apply_thresholds(complete, thresholds).items():
        print(format_report(label, complete, kept))
    print(filter_dict_by_value({"a": 10, "b": 20, "c": 5}, 15))
    print(filter_dict_by_value({"x": 1, "y": 2}, 5))


if __name__ == "__main__":
    main()

