import sys

ABSOLUTE_ZERO_C = -273.15
SUPPORTED_UNITS = {"c": "Celsius", "f": "Fahrenheit", "k": "Kelvin"}
_ALLOWED_NUMBER_CHARS = set("0123456789+-.eE")


def celsius_to_fahrenheit(celsius):
    """Convert a Celsius temperature to Fahrenheit."""
    return float(celsius) * 9 / 5 + 32


def parse_temperature(text):
    """Split a string like '21.5 C' into (value, unit letter)."""
    cleaned = text.strip().replace("\u00b0", " ")
    if not cleaned:
        raise ValueError("empty temperature reading")
    parts = cleaned.split()
    if len(parts) == 1:
        number, unit = parts[0][:-1], parts[0][-1:]
    else:
        number, unit = " ".join(parts[:-1]), parts[-1]
    unit = unit.lower()
    if unit not in SUPPORTED_UNITS:
        raise ValueError("unknown unit: %r" % unit)
    for character in number:
        if character not in _ALLOWED_NUMBER_CHARS:
            raise ValueError("bad numeric part: %r" % number)
    return float(number), unit


def to_celsius(value, unit):
    """Normalise a reading in any supported unit to Celsius."""
    if unit not in SUPPORTED_UNITS:
        raise ValueError("unknown unit: %r" % unit)
    if unit == "f":
        return (value - 32) * 5 / 9
    if unit == "k":
        return value - 273.15
    return value


def from_celsius(celsius, unit):
    """Convert a Celsius value into the requested output unit."""
    if unit not in SUPPORTED_UNITS:
        raise ValueError("unknown output unit: %r" % unit)
    if unit == "f":
        return celsius_to_fahrenheit(celsius)
    if unit == "k":
        return celsius + 273.15
    return celsius


def describe(celsius):
    """Return a short label for a Celsius temperature."""
    if celsius <= 0:
        return "freezing"
    if celsius < 15:
        return "cold"
    if celsius < 30:
        return "mild"
    return "hot"


def summarise(labels):
    """Count how often each label occurs, keeping first-seen order."""
    counts = {}
    for label in labels:
        if label not in counts:
            counts[label] = 0
        counts[label] += 1
    return ", ".join("%s: %d" % (label, counts[label]) for label in counts)


def build_report(readings, target_unit="f"):
    """Convert many readings, skipping unparsable or impossible ones."""
    lines = []
    labels = []
    for reading in readings:
        try:
            value, unit = parse_temperature(reading)
        except ValueError as error:
            lines.append("%-10s -> error: %s" % (reading, error))
            continue
        celsius = to_celsius(value, unit)
        if celsius < ABSOLUTE_ZERO_C:
            lines.append("%-10s -> below absolute zero" % reading)
            continue
        label = describe(celsius)
        labels.append(label)
        lines.append("%-10s -> %.1f %s (%s)"
                     % (reading, from_celsius(celsius, target_unit),
                        target_unit.upper(), label))
    lines.append("summary: " + summarise(labels))
    return "\n".join(lines)


def main(argv):
    target_unit = "f"
    readings = []
    for argument in argv:
        if argument.startswith("--unit="):
            target_unit = argument.split("=", 1)[1].lower()
        else:
            readings.append(argument)
    if not readings:
        readings = ["0 C", "100C", "37 C", "273.15 K", "98.6 F",
                    "-300 C", "12 X", "warm"]
    print(build_report(readings, target_unit))


if __name__ == "__main__":
    main(sys.argv[1:])

