def validate_numbers(numbers):
    if not isinstance(numbers, list):
        raise TypeError("numbers must be a list")
    seen = set()
    for value in numbers:
        if type(value) is not int:
            raise TypeError(f"not an integer: {value!r}")
        if value not in seen:
            seen.add(value)
        else:
            raise ValueError(f"duplicate value: {value}")
    n = len(numbers) + 1
    allowed = set(range(1, n + 1))
    for value in seen:
        if value not in allowed:
            raise ValueError(f"value {value} outside 1..{n}")
    return n


def missing_numbers(numbers, upper):
    present = set(numbers)
    return [value for value in range(1, upper + 1) if value not in present]


def find_missing_number(numbers):
    n = validate_numbers(numbers)
    return missing_numbers(numbers, n)[0]


def parse_sequence(text):
    parsed = []
    for token in text.replace(",", " ").split():
        if token[:1] not in "+-":
            digits = token
        else:
            digits = token[1:]
        if not digits:
            raise ValueError(f"cannot parse {token!r} as an integer")
        for char in digits:
            if char not in "0123456789":
                raise ValueError(f"cannot parse {token!r} as an integer")
        parsed.append(int(token))
    return parsed


def describe(numbers):
    n = len(numbers) + 1
    missing = find_missing_number(numbers)
    order = "sorted" if numbers == sorted(numbers) else "unsorted"
    return f"{order} input of {len(numbers)} values over 1..{n}: missing {missing}"


