import re

EMAIL_RE = re.compile(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}")

BLOCKED_DOMAINS = {"example.invalid", "localhost.localdomain", "test.invalid"}

VALID_TLDS = {"com", "org", "net", "edu", "gov", "io", "co", "uk", "de", "info"}


def extract_emails(text):
    """Return every valid-looking email address found in text, in order."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    found = []
    for match in EMAIL_RE.finditer(text):
        address = match.group(0).rstrip(".")
        if address not in found:
            found.append(address)
    return found


def split_address(address):
    """Split an address into (local, domain), or None if it is malformed."""
    if "@" not in address:
        return None
    local, _, domain = address.partition("@")
    if not local or "." not in domain:
        return None
    return local, domain


def is_deliverable(address):
    """Reject addresses on blocked domains or with an unknown TLD."""
    parts = split_address(address)
    if parts is None:
        return False
    domain = parts[1].lower()
    if domain in BLOCKED_DOMAINS:
        return False
    tld = domain.rsplit(".", 1)[-1]
    return tld in VALID_TLDS


def group_by_domain(addresses):
    """Map each domain to the sorted list of local parts seen for it."""
    groups = {}
    for address in addresses:
        parts = split_address(address)
        if parts is None:
            continue
        local, domain = parts
        domain = domain.lower()
        if domain not in groups:
            groups[domain] = []
        if local not in groups[domain]:
            groups[domain].append(local)
    for locals_ in groups.values():
        locals_.sort()
    return groups


def report(text):
    """Build a human-readable summary of the addresses inside text."""
    addresses = extract_emails(text)
    if not addresses:
        return "No addresses found."
    lines = []
    for domain, locals_ in sorted(group_by_domain(addresses).items()):
        lines.append("%s: %s" % (domain, ", ".join(locals_)))
    for address in addresses:
        if not is_deliverable(address):
            lines.append("unroutable: %s" % address)
    return "\n".join(lines)


def main():
    samples = [
        "Contact us at info@example.com or support@test.org.",
        "No emails here.",
        "Ping dev@corp.io, dev@corp.io or root@test.invalid for access.",
    ]
    for sample in samples:
        print(extract_emails(sample))
        print(report(sample))
        print("-" * 40)


if __name__ == "__main__":
    main()

