VOWELS = frozenset("aeiou")
PUNCTUATION = frozenset(",.;:!?'\"()-")


def count_vowels(text):
    """Return the number of vowels (a, e, i, o, u) in text, case-insensitively."""
    if not isinstance(text, str):
        raise TypeError("text must be a str")
    total = 0
    for char in text.lower():
        if char in VOWELS:
            total += 1
    return total


def count_consonants(text):
    """Return the number of alphabetic characters in text that are not vowels."""
    return sum(1 for char in text.lower() if char.isalpha() and char not in VOWELS)


def clean_word(word):
    """Strip surrounding punctuation characters from a single token."""
    return "".join(ch for ch in word if ch not in PUNCTUATION)


def vowel_groups(text):
    """Count maximal runs of consecutive vowels, a rough syllable estimate."""
    groups = 0
    previous = ""
    for char in text.lower():
        if char in VOWELS and previous not in VOWELS:
            groups += 1
        previous = char
    return groups


def vowel_free_words(text):
    """Return the distinct words of text that contain no vowels at all."""
    result = []
    for token in text.split():
        cleaned = clean_word(token)
        if not cleaned.isalpha():
            continue
        if any(ch in VOWELS for ch in cleaned.lower()):
            continue
        if cleaned not in result:
            result.append(cleaned)
    return result


def missing_vowels(text):
    """Return the vowels, in order, that never appear in text."""
    present = set(text.lower())
    return [vowel for vowel in "aeiou" if vowel not in present]


def vowel_breakdown(text):
    """Return a dict mapping each of the five vowels to its count in text."""
    counts = dict.fromkeys("aeiou", 0)
    for char in text.lower():
        if char in counts:
            counts[char] += 1
    return counts


def format_report(text):
    """Build a human-readable summary of the vowel statistics for text."""
    breakdown = vowel_breakdown(text)
    lines = ["Text: %r" % text,
             "Vowels: %d" % count_vowels(text),
             "Consonants: %d" % count_consonants(text),
             "Vowel groups: %d" % vowel_groups(text),
             "Breakdown: " + ", ".join("%s=%d" % (v, breakdown[v]) for v in "aeiou")]
    absent = missing_vowels(text)
    if absent:
        lines.append("Unused vowels: " + ", ".join(absent))
    odd = vowel_free_words(text)
    if odd:
        lines.append("Vowel-free words: " + ", ".join(odd))
    return "\n".join(lines)


def main():
    for sample in ["Hello World", "Python", "Why try, my nymph?", "AEIOU aeiou"]:
        print(format_report(sample))
        print("-" * 40)


if __name__ == "__main__":
    main()

