FREQUENCY_ALIASES = {"annually": 1, "semiannually": 2, "quarterly": 4, "monthly": 12, "daily": 365}
FREQUENCY_NAMES = {count: name for name, count in FREQUENCY_ALIASES.items()}
CURRENCY_SYMBOLS = {"USD": "$", "EUR": "\u20ac", "GBP": "\u00a3", "JPY": "\u00a5"}
SYMBOL_CODES = {symbol: code for code, symbol in CURRENCY_SYMBOLS.items()}


def parse_frequency(value):
    """Turn a frequency name ('quarterly') or a number into a positive integer."""
    if isinstance(value, str):
        key = value.strip().lower().replace("-", "").replace(" ", "")
        if key not in FREQUENCY_ALIASES:
            raise ValueError("unknown compounding frequency: %r" % value)
        value = FREQUENCY_ALIASES[key]
    if value < 1:
        raise ValueError("compounding_frequency must be at least 1")
    return int(value)


def parse_rate(value):
    """Accept a decimal rate (0.05) or a percentage string ('5%')."""
    if not isinstance(value, str):
        return float(value)
    text = value.strip()
    if "%" not in text:
        return float(text)
    return float(text.rstrip("%").strip()) / 100.0


def parse_principal(value):
    """Accept a number or a money string such as '$1,250'."""
    if isinstance(value, str):
        text = value.strip().replace(",", "")
        if text[:1] not in SYMBOL_CODES:
            return float(text)
        return float(text[1:])
    return float(value)


def format_money(amount, currency="USD"):
    """Render an amount with its symbol, or with the bare code if unknown."""
    code = currency.strip().upper()
    if code not in CURRENCY_SYMBOLS:
        return "%.2f %s" % (amount, code)
    return "%s%.2f" % (CURRENCY_SYMBOLS[code], amount)


def frequency_label(n):
    if n not in FREQUENCY_NAMES:
        return "%d times per year" % n
    return FREQUENCY_NAMES[n]


def calculate_compound_interest(principal, rate, compounding_frequency, time_years):
    """Return the total amount after compounding, not just the earned interest."""
    amount = parse_principal(principal)
    if amount < 0:
        raise ValueError("principal must not be negative")
    if time_years < 0:
        raise ValueError("time_years must not be negative")
    n = parse_frequency(compounding_frequency)
    return amount * (1.0 + parse_rate(rate) / n) ** (n * int(time_years))


def report(principal, rate, compounding_frequency, time_years, currency="USD"):
    """Build a per-year balance table for the given deposit."""
    start = parse_principal(principal)
    n = parse_frequency(compounding_frequency)
    lines = ["%s at %.2f%%, compounded %s" % (format_money(start, currency),
                                              parse_rate(rate) * 100, frequency_label(n))]
    for year in range(1, time_years + 1):
        total = calculate_compound_interest(start, rate, n, year)
        lines.append("  year %2d: balance %s (interest %s)" % (
            year, format_money(total, currency), format_money(total - start, currency)))
    return "\n".join(lines)


def main():
    print(calculate_compound_interest(1000, 0.05, 1, 1))
    print(calculate_compound_interest(1000, 0.05, 4, 1))
    print(report("$1,250", "4%", "monthly", 3))
    print(report(2500, 0.031, 2, 2, currency="CHF"))


if __name__ == "__main__":
    main()

