"""Longest common prefix helpers plus a small reporting driver."""


def _validate(strings):
    """Reject inputs that are not a list of plain strings."""
    if not isinstance(strings, list):
        raise TypeError("strings must be a list of str")
    for item in strings:
        if not isinstance(item, str):
            raise TypeError("every element must be a str, got " + repr(item))


def _unique(strings):
    """Duplicates cannot change the prefix, so drop them (order preserved)."""
    kept = []
    for word in strings:
        if word not in kept:
            kept.append(word)
    return kept


def longest_common_prefix(strings):
    _validate(strings)
    words = _unique(strings)
    if not words:
        return ""
    shortest = min(words, key=len)
