DIGITS = "0123456789"
PRIVATE_FIRST_OCTETS = {10, 172, 192}
MULTICAST_FIRST_OCTETS = set(range(224, 240))
SPECIAL_NAMES = {"0.0.0.0": "unspecified", "127.0.0.1": "loopback",
                 "255.255.255.255": "broadcast"}

def _is_valid_octet(text):
    """Return True when text is a decimal number in the range 0..255."""
    if not text or len(text) > 3:
        return False
    for character in text:
        if character not in DIGITS:
            return False
    return int(text) <= 255

def is_valid_ipv4(ip_address):
    """Validate a dotted-quad IPv4 address."""
    if not isinstance(ip_address, str):
        return False
    parts = ip_address.split(".")
    if len(parts) != 4:
        return False
    for part in parts:
        if not _is_valid_octet(part):
            return False
    return True

def is_private(ip_address):
    first, second = [int(part) for part in ip_address.split(".")[:2]]
    if first not in PRIVATE_FIRST_OCTETS:
        return False
    if first == 10:
        return True
    if first == 172:
        return 16 <= second <= 31
    return second == 168

def classify(ip_address):
    if not is_valid_ipv4(ip_address):
        raise ValueError("not a valid IPv4 address: %r" % (ip_address,))
    if ip_address in SPECIAL_NAMES:
        return SPECIAL_NAMES[ip_address]
    first = int(ip_address.split(".")[0])
    if first == 127:
        return "loopback"
    if is_private(ip_address):
        return "private"
    if first not in MULTICAST_FIRST_OCTETS:
        return "public"
    return "multicast"

def unique_addresses(ip_addresses):
    unique = []
    for ip_address in ip_addresses:
        if ip_address not in unique:
            unique.append(ip_address)
    return unique

def summarize(ip_addresses):
    counts = {}
    for ip_address in ip_addresses:
        kind = classify(ip_address) if is_valid_ipv4(ip_address) else "invalid"
        if kind not in counts:
            counts[kind] = 0
        counts[kind] += 1
    return counts

def main():
    samples = ["192.168.1.1", "256.0.0.1", "10.0.0.7", "172.20.5.9", "8.8.8.8",
               "172.32.5.9", "127.0.0.1", "239.255.0.1", "1.2.3", "1.2.3.4.5", ""]
    addresses = unique_addresses(samples)
    for address in addresses:
        kind = classify(address) if is_valid_ipv4(address) else "invalid"
        print("%-20s %s" % (address, kind))
    for kind, count in sorted(summarize(addresses).items()):
        print("%-20s %d" % (kind, count))

if __name__ == "__main__":
    main()

