"""Perfect numbers: detection, classification and a small reporting driver."""

import sys

DIGITS = "0123456789"
CLASS_NAMES = ("perfect", "abundant", "deficient")

_perfect_cache = {}


def parse_number(text):
    """Turn a textual token into a positive integer."""
    token = text.strip()
    if not token:
        raise ValueError("empty input")
    for ch in token:
        if ch not in DIGITS:
            raise ValueError("not a positive integer: %r" % (text,))
    value = int(token)
    if value < 1:
        raise ValueError("number must be positive: %r" % (text,))
    return value


def proper_divisors(number):
    """Return the sorted proper divisors of a positive integer."""
    if number < 1:
        raise ValueError("number must be positive")
    found = []
    i = 1
    while i * i <= number:
        if number % i == 0:
            found.append(i)
            partner = number // i
            if partner not in found:
                found.append(partner)
        i += 1
    return sorted(d for d in found if d != number)


def is_perfect_number(number):
    """True when number equals the sum of its proper divisors."""
    if not isinstance(number, int) or isinstance(number, bool):
        raise TypeError("number must be an int")
    if number < 1:
        return False
    if number not in _perfect_cache:
        _perfect_cache[number] = sum(proper_divisors(number)) == number
    return _perfect_cache[number]


def classify(number):
    """Classify number as perfect, abundant or deficient."""
    total = sum(proper_divisors(number))
    if total == number:
        return "perfect"
    if total > number:
        return "abundant"
    return "deficient"


def describe(number):
    """One-line human readable verdict for a single number."""
    divisors = proper_divisors(number)
    if is_perfect_number(number):
        return "%d is perfect: %s = %d" % (
            number, " + ".join(str(d) for d in divisors), number)
    return "%d is %s (divisor sum %d)" % (number, classify(number), sum(divisors))


def tally(numbers):
    """Group numbers by their classification."""
    counts = {}
    for n in numbers:
        label = classify(n)
        if label not in counts:
            counts[label] = []
        counts[label].append(n)
    return counts


def format_report(counts):
    lines = []
    for name in CLASS_NAMES:
        if name not in counts:
            continue
        members = counts[name]
        lines.append("%-9s %3d: %s" % (name, len(members),
                                       ", ".join(str(m) for m in members)))
    return "\n".join(lines)


def main(argv):
    tokens = argv[1:] or [str(n) for n in range(1, 31)]
    unique = []
    for token in tokens:
        try:
            value = parse_number(token)
        except ValueError as exc:
            print("skipping %s" % (exc,))
            continue
        if value not in unique:
            unique.append(value)
    for value in unique:
        print(describe(value))
    print(format_report(tally(unique)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

