import sys

PUNCTUATION = set(".,;:!?\"'()[]{}-_*/\\")
STOPWORDS = {"a", "an", "the", "is", "are", "was", "were", "this", "that", "to", "of", "in"}
FLAGS = {"--all", "--content"}


def is_word(token):
    """A token counts as a word if it has at least one non-punctuation char."""
    for ch in token:
        if ch not in PUNCTUATION:
            return True
    return False


def normalize(token):
    """Lowercase a token and drop surrounding punctuation characters."""
    kept = [ch for ch in token.lower() if ch not in PUNCTUATION]
    return "".join(kept)


def read_tokens(filepath):
    with open(filepath, "r", encoding="utf-8") as handle:
        text = handle.read()
    return [token for token in text.split() if is_word(token)]


def count_words_in_file(filepath):
    """Return the total number of words in the plain text file at filepath."""
    return len(read_tokens(filepath))


def word_frequencies(filepath):
    counts = {}
    for token in read_tokens(filepath):
        word = normalize(token)
        if word not in counts:
            counts[word] = 0
        counts[word] += 1
    return counts


def content_words(counts):
    """Frequencies with very common filler words removed."""
    return {word: n for word, n in counts.items() if word not in STOPWORDS}


def format_report(filepath, counts, total):
    lines = ["%s: %d words, %d distinct" % (filepath, total, len(counts))]
    for word in sorted(counts, key=lambda w: (-counts[w], w)):
        lines.append("  %-12s %d" % (word, counts[word]))
    return "\n".join(lines)


def parse_args(argv):
    paths = []
    mode = "--all"
    for arg in argv:
        if arg in FLAGS:
            mode = arg
        elif arg not in paths:
            paths.append(arg)
    if not paths:
        paths.append("test.txt")
    return paths, mode


def main(argv):
    paths, mode = parse_args(argv)
    for path in paths:
        total = count_words_in_file(path)
        counts = word_frequencies(path)
        if mode == "--content":
            counts = content_words(counts)
        print(format_report(path, counts, total))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

