import sys

IGNORE_SETS = {
    "spaces": " \t",
    "digits": "0123456789",
    "punct": ".,;:!?'\"-",
}


def char_counts(s):
    """Return a mapping from character to number of occurrences in s."""
    counts = {}
    for ch in s:
        if not ch in counts:
            counts[ch] = 0
        counts[ch] += 1
    return counts


def first_positions(s):
    """Return a mapping from character to the index where it first appears."""
    positions = {}
    for index, ch in enumerate(s):
        if not ch in positions:
            positions[ch] = index
    return positions


def ignore_chars(names):
    """Expand ignore-set names such as ['spaces', 'punct'] into a character string."""
    chars = []
    for name in names:
        if not name in IGNORE_SETS:
            raise ValueError("unknown ignore set: " + name)
        for ch in IGNORE_SETS[name]:
            if not ch in chars:
                chars.append(ch)
    return "".join(chars)


def normalize(s, ignore_case=False, ignored=""):
    """Strip ignored characters from s, optionally folding case first."""
    text = s.lower() if ignore_case else s
    kept = []
    for ch in text:
        if not ch in ignored:
            kept.append(ch)
    return "".join(kept)


def repeated_characters(s):
    """Return the characters of s that occur more than once, in order of appearance."""
    counts = char_counts(s)
    repeats = []
    for ch in s:
        if counts[ch] > 1 and not ch in repeats:
            repeats.append(ch)
    return repeats


def first_unique_char(s):
    """Return the index of the first non-repeating character in s, or -1."""
    if not isinstance(s, str):
        raise TypeError("first_unique_char expects a string")
    counts = char_counts(s)
    for index, ch in enumerate(s):
        if counts[ch] == 1:
            return index
    return -1


def describe(s, ignore_case=False, ignored=""):
    """Build a human readable report about the first unique character of s."""
    text = normalize(s, ignore_case=ignore_case, ignored=ignored)
    counts = char_counts(text)
    index = first_unique_char(text)
    lines = ["input: {!r}".format(s)]
    if text != s:
        lines.append("normalized: {!r}".format(text))
    if index == -1:
        lines.append("no unique character")
    else:
        lines.append("first unique: {!r} at index {}".format(text[index], index))
    uniques = ["{}@{}".format(ch, i) for i, ch in enumerate(text) if counts[ch] == 1]
    if uniques:
        lines.append("unique: " + " ".join(uniques))
    positions = first_positions(text)
    repeats = repeated_characters(text)
    if repeats:
        lines.append("repeated: " + " ".join("{}@{}".format(ch, positions[ch]) for ch in repeats))
    return "\n".join(lines)


def main(argv):
    ignore_case = False
    names = []
    samples = []
    for arg in argv:
        if arg == "-i":
            ignore_case = True
        elif arg.startswith("--ignore="):
            names = [part for part in arg.split("=", 1)[1].split(",") if part]
        else:
            samples.append(arg)
    ignored = ignore_chars(names)
    if not samples:
        samples = ["leetcode", "loveleetcode", "aabb", "", "Swiss cheese"]
    for sample in samples:
        print(describe(sample, ignore_case=ignore_case, ignored=ignored))
        print("-" * 32)


if __name__ == "__main__":
    main(sys.argv[1:])

