NUMBER_TYPES = (int, float)

COUPONS = {
    "SAVE10": 10.0,
    "HALFOFF": 50.0,
    "WELCOME": 5.0,
}

CURRENCY_SYMBOLS = {"USD": "$", "EUR": "\u20ac", "GBP": "\u00a3"}

CURRENCY_ALIASES = {"DOLLAR": "USD", "EURO": "EUR", "POUND": "GBP"}


def calculate_discount_price(original_price, discount_percentage):
    if type(original_price) not in NUMBER_TYPES:
        raise TypeError("original_price must be a number")
    if type(discount_percentage) not in NUMBER_TYPES:
        raise TypeError("discount_percentage must be a number")
    if original_price < 0:
        raise ValueError("original_price cannot be negative")
    if discount_percentage < 0 or discount_percentage > 100:
        raise ValueError("discount_percentage must be between 0 and 100")
    return round(float(original_price) * (1 - discount_percentage / 100.0), 2)


def discount_for_coupon(code):
    normalized = str(code).strip().upper()
    if normalized not in COUPONS:
        raise KeyError("unknown coupon code: %s" % code)
    return COUPONS[normalized]


def resolve_currency(code):
    name = CURRENCY_ALIASES.get(str(code).strip().upper(), str(code).strip().upper())
    if name not in CURRENCY_SYMBOLS:
        raise ValueError("unsupported currency: %s" % code)
    return name


def format_money(amount, currency="USD"):
    return "%s%.2f" % (CURRENCY_SYMBOLS[resolve_currency(currency)], amount)


def parse_discount(text):
    token = text.strip().rstrip("%")
    try:
        return float(token)
    except ValueError:
        return discount_for_coupon(token)


def parse_item(line):
    parts = [part.strip() for part in line.split(",")]
    if len(parts) not in (3, 4):
        raise ValueError("expected 'name, price, discount[, currency]' but got %r" % line)
    if not parts[0]:
        raise ValueError("item name must not be empty")
    currency = parts[3] if len(parts) == 4 else "USD"
    return parts[0], float(parts[1]), parse_discount(parts[2]), resolve_currency(currency)


def build_report(lines):
    rows = []
    seen = set()
    saved = {}
    for line in lines:
        if not line.strip():
            continue
        name, price, discount, currency = parse_item(line)
        if name not in seen:
            seen.add(name)
            final = calculate_discount_price(price, discount)
            saved[currency] = saved.get(currency, 0.0) + price - final
            rows.append("%-10s %10s -> %10s (-%.0f%%)" % (
                name, format_money(price, currency),
                format_money(final, currency), discount))
    for currency in sorted(saved):
        rows.append("%-10s %22s" % ("SAVED", format_money(round(saved[currency], 2), currency)))
    return "\n".join(rows)


def main():
