"""Utilities built around reversing the characters of a string."""

_ALPHANUMERIC = set("abcdefghijklmnopqrstuvwxyz0123456789")
_MODES = ("plain", "words", "unique")


def reverse_string(input_string):
    """Return a new string with the characters of ``input_string`` reversed."""
    if not isinstance(input_string, str):
        raise TypeError("input_string must be a str")
    reversed_chars = []
    for index in range(len(input_string) - 1, -1, -1):
        reversed_chars.append(input_string[index])
    return "".join(reversed_chars)


def normalize(text):
    """Lowercase ``text`` and drop everything that is not a letter or digit."""
    kept = []
    for char in text.lower():
        if char not in _ALPHANUMERIC:
            continue
        kept.append(char)
    return "".join(kept)


def is_palindrome(text):
    cleaned = normalize(text)
    return cleaned != "" and cleaned == reverse_string(cleaned)


def reverse_words(sentence):
    """Reverse the order of the whitespace separated words in ``sentence``."""
    words = sentence.split()
    return " ".join(words[len(words) - 1 - i] for i in range(len(words)))


def unique_reversed(text):
    """Reverse ``text`` after removing later repetitions of a character."""
    seen = []
    for char in text:
        if char not in seen:
            seen.append(char)
    return reverse_string("".join(seen))


def transform(text, mode="plain"):
    if mode not in _MODES:
        raise ValueError("unknown mode: %r" % (mode,))
    if mode == "words":
        return reverse_words(text)
    if mode == "unique":
        return unique_reversed(text)
    return reverse_string(text)


def build_reversal_index(words):
    """Map each reversed word to the original words producing it."""
    index = {}
    for word in words:
        key = reverse_string(normalize(word))
        if key not in index:
            index[key] = []
        if word not in index[key]:
            index[key].append(word)
    return index


def find_reversible_pairs(words):
    """Return sorted pairs (a, b) where reversing ``a`` yields ``b``."""
    available = {normalize(word) for word in words}
    pairs = set()
    for word in words:
        plain = normalize(word)
        mirrored = reverse_string(plain)
        if mirrored not in available:
            continue
        if plain != mirrored:
            pairs.add(tuple(sorted((plain, mirrored))))
    return sorted(pairs)


def main():
    samples = ["hello", "Python", "A man, a plan, a canal: Panama", "stressed"]
    for sample in samples:
        flag = "palindrome" if is_palindrome(sample) else "plain text"
        print("%-32s -> %-32s (%s)" % (sample, reverse_string(sample), flag))

    sentence = "stressed desserts live evil rats star"
    print("words :", transform(sentence, "words"))
    print("unique:", transform("mississippi", "unique"))

    words = sentence.split()
    for key, originals in sorted(build_reversal_index(words).items()):
        print("reversal %-10s from %s" % (key, ", ".join(originals)))
    for left, right in find_reversible_pairs(words):
        print("pair: %s <-> %s" % (left, right))


if __name__ == "__main__":
    main()

