ALLOWED_CHARS = set("0123456789+-. ^")
DIGITS = "0123456789"
NUMERIC_TYPES = (int, float)
_power_cache = {}


def calculate_power(base, exponent):
    """Return base raised to exponent using repeated squaring."""
    if type(base) not in NUMERIC_TYPES or isinstance(base, bool):
        raise TypeError("base must be an int or a float")
    if type(exponent) is not int or isinstance(exponent, bool):
        raise TypeError("exponent must be an int")
    if base == 0 and exponent < 0:
        raise ZeroDivisionError("0 cannot be raised to a negative exponent")

    key = (base, exponent)
    if key not in _power_cache:
        negative = exponent < 0
        result = 1
        factor = base
        remaining = -exponent if negative else exponent
        while remaining > 0:
            if remaining % 2 == 1:
                result *= factor
            factor *= factor
            remaining //= 2
        _power_cache[key] = 1 / result if negative else result
    return _power_cache[key]


def parse_number(text, label):
    """Convert a signed numeric token into an int or a float."""
    body = text[1:] if text[:1] in ("+", "-") else text
    digits = body.replace(".", "", 1)
    if not digits or any(ch not in DIGITS for ch in digits):
        raise ValueError("%s %r is not a number" % (label, text))
    return float(text) if "." in body else int(text)


def parse_expression(text):
    """Turn a string like '2 ^ 3' into a (base, exponent) pair."""
    for ch in text:
        if ch not in ALLOWED_CHARS:
            raise ValueError("unexpected character %r in %r" % (ch, text))
    if "^" not in text:
        raise ValueError("expression %r is missing the '^' operator" % text)
    left, _, right = text.partition("^")
    base = parse_number(left.strip(), "base")
    exponent = parse_number(right.strip(), "exponent")
    if isinstance(exponent, float):
        raise ValueError("exponent %r must be a whole number" % right.strip())
    return base, exponent


def format_result(value):
    """Render a power result without a trailing '.0' for whole floats."""
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value)


def report(expressions):
    """Evaluate each expression and return human readable report lines."""
    lines = []
    for text in expressions:
        try:
            base, exponent = parse_expression(text)
        except ValueError as exc:
            lines.append("%s -> invalid: %s" % (text, exc))
            continue
        try:
            value = calculate_power(base, exponent)
        except ZeroDivisionError as exc:
            lines.append("%s -> undefined: %s" % (text, exc))
            continue
        lines.append("%s -> %s" % (text, format_result(value)))
    return lines


def main():
    samples = ["2 ^ 3", "5 ^ 0", "2 ^ -2", "1.5 ^ 2", "0 ^ -1", "4 ** 2", "7 ^ 1.5"]
    for line in report(samples):
        print(line)


if __name__ == "__main__":
    main()

