            raise ValueError("token %r contains the invalid character %r" % (token, ch))
    return int(text)


def split_options(argv):
    """Separate --even/--odd selectors from the numeric tokens on a command line."""
    wanted = []
    tokens = []
    for arg in argv:
        if arg.startswith("--"):
            name = arg[2:]
            if not name in CATEGORIES:
                raise SystemExit("unknown option %r" % arg)
            wanted.append(name)
        else:
            tokens.append(arg)
    return wanted or list(CATEGORIES), tokens


def is_even(number):
    """Return True when number is an even integer."""
    if not isinstance(number, int) or isinstance(number, bool):
        raise TypeError("is_even expects an int, got %r" % type(number).__name__)
    return number % 2 == 0


def classify(number):
    return "even" if is_even(number) else "odd"


def collect(tokens):
    """Parse tokens into unique integers, returning values and error messages."""
    values = []
    errors = []
    seen = set()
    for token in tokens:
        try:
            number = parse_int(token)
        except ValueError as exc:
            message = str(exc)
            if not message in errors:
                errors.append(message)
            continue
        if not number in seen:
            seen.add(number)
            values.append(number)
    return values, errors


def summarize(numbers):
    counts = {}
    for number in numbers:
        label = classify(number)
        if not label in counts:
            counts[label] = 0
        counts[label] += 1
    return counts


def format_report(numbers, wanted):
    counts = summarize(numbers)
    lines = []
    for number in numbers:
        label = classify(number)
        if label in wanted:
            lines.append("%6d -> %s (is_even=%s)" % (number, label, is_even(number)))
    lines.append("-" * 32)
    for name in wanted:
        lines.append("%-4s: %d" % (name, counts.get(name, 0)))
    return "\n".join(lines)


def main(argv):
    wanted, tokens = split_options(argv)
    values, errors = collect(tokens or DEFAULT_TOKENS.split())
    print(format_report(values, wanted))
    if errors:
        print("-" * 32)
        for message in errors:
            print("skipped:", message)


if __name__ == "__main__":
    import sys

    main(sys.argv[1:])

