import math

ALLOWED_UNITS = {"m": 1.0, "cm": 0.01, "mm": 0.001, "km": 1000.0}


def calculate_sphere_volume(radius):
    """Return the volume of a sphere with the given radius."""
    if type(radius) not in (int, float):
        raise TypeError("radius must be a real number")
    if radius < 0:
        raise ValueError("radius must be non-negative")
    return 4.0 / 3.0 * math.pi * float(radius) ** 3


def parse_measurement(text):
    """Split a string like '3.0 cm' into a radius in metres."""
    parts = text.split()
    if len(parts) not in (1, 2):
        raise ValueError("expected '<radius>' or '<radius> <unit>'")
    try:
        value = float(parts[0])
    except ValueError:
        raise ValueError("could not read a radius from %r" % parts[0])
    unit = parts[1] if len(parts) == 2 else "m"
    if unit not in ALLOWED_UNITS:
        raise ValueError("unknown unit %r" % unit)
    return value * ALLOWED_UNITS[unit]


def volume_table(measurements):
    """Map each measurement string to its sphere volume in cubic metres."""
    table = {}
    for text in measurements:
        if text not in table:
            table[text] = calculate_sphere_volume(parse_measurement(text))
    return table


def format_volume(volume, precision=4):
    """Render a volume with a fixed number of decimals."""
    if precision not in range(0, 13):
        raise ValueError("precision must be between 0 and 12")
    return "{0:.{1}f}".format(volume, precision)


def report(measurements):
    """Build report lines, noting inputs that cannot be interpreted."""
    lines = []
    volumes = volume_table([m for m in measurements if m.strip()])
    for text in measurements:
        if text not in volumes:
            lines.append("%-12s -> skipped (blank entry)" % text.strip())
            continue
        lines.append("%-12s -> %s m^3" % (text, format_volume(volumes[text])))
    return lines


def main():
    samples = ["1.0", "3.0", "50 cm", "12 mm", "0.5 km", "   "]
    for line in report(samples):
        print(line)

    radii = [1.0, 3.0]
    largest = max(radii)
    for r in radii:
        share = calculate_sphere_volume(r) / calculate_sphere_volume(largest)
        print("r=%.1f holds %s of the largest sphere" % (r, format_volume(share, 3)))


if __name__ == "__main__":
    main()

