import random
import sys

LOW = 1
HIGH = 100
VALID_RANGE = range(LOW, HIGH + 1)
TRIALS = 1000


def validate_target(target):
    if not isinstance(target, int) or isinstance(target, bool):
        raise TypeError("target must be an integer")
    if target not in VALID_RANGE:
        raise ValueError("target must be between %d and %d" % (LOW, HIGH))
    return target


def validate_max_guesses(max_guesses):
    if not isinstance(max_guesses, int) or isinstance(max_guesses, bool):
        raise TypeError("max_guesses must be an integer")
    if max_guesses < 0:
        raise ValueError("max_guesses must not be negative")
    return max_guesses


def parse_pair(text):
    if "," not in text:
        raise ValueError("expected TARGET,MAX_GUESSES but got %r" % text)
    target_text, max_text = text.split(",", 1)
    return validate_target(int(target_text)), validate_max_guesses(int(max_text))


def guess_history(target, max_guesses):
    history = []
    for _ in range(max_guesses):
        guess = random.randint(LOW, HIGH)
        history.append(guess)
        if guess == target:
            break
    return history


def play_guessing_game(target, max_guesses):
    validate_target(target)
    validate_max_guesses(max_guesses)
    history = guess_history(target, max_guesses)
    if target not in history:
        return -1
    return len(history)


def distinct_misses(history, target):
    misses = []
    for guess in history:
        if guess == target:
            continue
        if guess not in misses:
            misses.append(guess)
    return misses


def unseen_values(histories):
    seen = set()
    for history in histories:
        seen.update(history)
    return [value for value in VALID_RANGE if value not in seen]


def summarize(target, histories):
    wins = [len(history) for history in histories if target in history]
    miss_counts = [len(distinct_misses(h, target)) for h in histories]
    summary = {
        "trials": len(histories),
        "wins": len(wins),
        "losses": len(histories) - len(wins),
        "unseen": len(unseen_values(histories)),
        "mean_distinct_misses": sum(miss_counts) / len(histories),
    }
    if wins:
        summary["best"] = min(wins)
        summary["average_guesses"] = sum(wins) / len(wins)
    return summary


def format_summary(target, max_guesses, summary):
    lines = ["target=%d, max_guesses=%d" % (target, max_guesses)]
    lines.append("  trials: %d" % summary["trials"])
    lines.append("  wins:   %d" % summary["wins"])
    lines.append("  losses: %d" % summary["losses"])
    lines.append("  never guessed values: %d" % summary["unseen"])
    lines.append("  mean wrong values: %.2f" % summary["mean_distinct_misses"])
    if "best" in summary:
        lines.append("  best:   %d guesses" % summary["best"])
        lines.append("  mean:   %.2f guesses" % summary["average_guesses"])
    else:
        lines.append("  never guessed correctly")
    return "\n".join(lines)


def main(argv):
    random.seed(20260918)
    specs = [parse_pair(arg) for arg in argv[1:]]
    if not specs:
        specs = [(50, 10), (99, 1), (7, 200)]
    for target, max_guesses in specs:
        histories = [guess_history(target, max_guesses) for _ in range(TRIALS)]
        print(format_summary(target, max_guesses, summarize(target, histories)))
        result = play_guessing_game(target, max_guesses)
        if result == -1:
            print("  single run: %d not found in %d guesses" % (target, max_guesses))
        else:
            print("  single run: %d found after %d guesses" % (target, result))
        print()


if __name__ == "__main__":
    main(sys.argv)

