import math

UNIT_FACTORS = {"m": 1.0, "cm": 0.01, "mm": 0.001, "in": 0.0254}
NUMBER_CHARS = "0123456789.+-eE"
COMMENT_MARKERS = "#;"
AREA_CACHE = {}


def parse_sides(text):
    """Parse 'a b c [unit]' or 'a, b, c [unit]' into three lengths in metres."""
    text = text.strip()
    if "," not in text:
        tokens = text.split()
    else:
        tokens = [part.strip() for part in text.split(",")]
    if not tokens:
        raise ValueError("no side lengths given")
    unit = "m"
    if tokens[-1] and tokens[-1][0] not in NUMBER_CHARS:
        unit = tokens.pop()
        if unit not in UNIT_FACTORS:
            raise ValueError("unknown unit: %s" % unit)
    if len(tokens) != 3:
        raise ValueError("expected three side lengths, got %d" % len(tokens))
    scale = UNIT_FACTORS[unit]
    sides = []
    for token in tokens:
        for ch in token:
            if ch not in NUMBER_CHARS:
                raise ValueError("bad character %r in %r" % (ch, token))
        sides.append(float(token) * scale)
    return sides


def triangle_area(a, b, c):
    """Area of the triangle with sides a, b, c, or 0.0 if it is not a triangle."""
    sides = sorted((float(a), float(b), float(c)))
    if sides[0] <= 0.0:
        return 0.0
    if sides[0] + sides[1] <= sides[2]:
        return 0.0
    s = (sides[0] + sides[1] + sides[2]) / 2.0
    product = s * (s - sides[0]) * (s - sides[1]) * (s - sides[2])
    if product <= 0.0:
        return 0.0
    return math.sqrt(product)


def classify_triangle(a, b, c):
    if triangle_area(a, b, c) == 0.0:
        return "degenerate"
    distinct = {float(a), float(b), float(c)}
    if len(distinct) == 1:
        return "equilateral"
    if len(distinct) == 2:
        return "isosceles"
    return "scalene"


def area_of_line(line):
    if line not in AREA_CACHE:
        a, b, c = parse_sides(line)
        AREA_CACHE[line] = (triangle_area(a, b, c), classify_triangle(a, b, c))
    return AREA_CACHE[line]


def report(lines):
    rows, errors = [], []
    for raw in lines:
        line = raw.strip()
        if not line or line[0] in COMMENT_MARKERS:
            continue
        try:
            area, shape = area_of_line(line)
        except ValueError as exc:
            message = "%s -> error: %s" % (line, exc)
            if message not in errors:
                errors.append(message)
            continue
        rows.append("%-18s area=%.6f m^2 (%s)" % (line, area, shape))
    return rows + errors


def main():
    data = [
        "# sample triangles",
        "3 4 5",
        "1 1 10",
        "300, 400, 500 cm",
        "2 2 2",
        "3 4 5",
        "5 5 8 in",
        "1 2 x",
        "7 8 9 furlong",
        "10 10",
    ]
    for line in report(data):
        print(line)
    print("right triangle check: %.1f" % triangle_area(3, 4, 5))
    print("impossible triangle check: %.1f" % triangle_area(1, 1, 10))


if __name__ == "__main__":
    main()

