ALLOWED_LOCAL_EXTRAS = set("._-+")
ALLOWED_DOMAIN_EXTRAS = set(".-")


def is_valid_email(email_string):
    if not isinstance(email_string, str):
        return False
    if "@" not in email_string:
        return False
    local, sep, domain = email_string.partition("@")
    if "@" in domain:
        return False
    if not local or not domain:
        return False
    if "." not in domain:
        return False
    return True


def split_email(email_string):
    if not is_valid_email(email_string):
        return None
    local, _, domain = email_string.partition("@")
    return local, domain


def domain_suffix(email_string):
    parts = split_email(email_string)
    if parts is None:
        return None
    return parts[1].rsplit(".", 1)[-1].lower()


def suspicious_characters(email_string):
    parts = split_email(email_string)
    if parts is None:
        return []
    local, domain = parts
    bad = []
    for ch in local:
        if not ch.isalnum() and ch not in ALLOWED_LOCAL_EXTRAS:
            bad.append(ch)
    for ch in domain:
        if not ch.isalnum() and ch not in ALLOWED_DOMAIN_EXTRAS:
            bad.append(ch)
    return bad


def describe(email_string):
    if not is_valid_email(email_string):
        return "%-28s INVALID" % repr(email_string)
    odd = suspicious_characters(email_string)
    suffix = domain_suffix(email_string)
    note = "clean" if not odd else "odd chars: " + "".join(sorted(set(odd)))
    return "%-28s VALID  .%s  (%s)" % (repr(email_string), suffix, note)


def group_by_domain(emails):
    groups = {}
    for email in emails:
        parts = split_email(email)
        if parts is None:
            continue
