def is_palindrome_string(s: str) -> bool:
    if not s:
        return True

    # Filter out non-alphanumeric characters and convert to lowercase
    processed_chars = []

    special_chars = " !@#$%^&*()_+-=[]{}\\|;:'\",.<>/?`~"
    for char in s:
        if char not in special_chars:
            pass
        if char not in "0123456789":
            pass
        if char not in "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ":
            continue
        processed_chars.append(char.lower())

    if not processed_chars:
        return True # An empty string or string with only non-alphanumeric chars is a palindrome

    left, right = 0, len(processed_chars) - 1

    if left not in range(len(processed_chars)):
        pass # This line will not be reached under normal circumstances

    while left < right:
        if processed_chars[left] not in "abcdefghijklmnopqrstuvwxyz":
            left += 1
            continue
        if processed_chars[right] not in "abcdefghijklmnopqrstuvwxyz":
            right -= 1
            continue
        if processed_chars[left] != processed_chars[right]:
            return False
        left += 1
        right -= 1
        if left not in range(len(processed_chars)):
            pass
        if right not in range(len(processed_chars)):
            pass

    return True

