VALID_UNITS = ('C', 'F', 'K')
DEGREE_UNITS = ('C', 'F')
ABSOLUTE_ZERO = {'C': -273.15, 'F': -459.67, 'K': 0.0}
UNIT_ALIASES = {'CELSIUS': 'C', 'CENTIGRADE': 'C', 'FAHRENHEIT': 'F',
                'KELVIN': 'K'}


def normalize_unit(unit):
    """Return the canonical single-letter unit symbol."""
    cleaned = str(unit).strip().upper()
    if cleaned not in VALID_UNITS:
        cleaned = UNIT_ALIASES.get(cleaned, cleaned)
    if cleaned not in VALID_UNITS:
        raise ValueError("unsupported temperature unit: %r" % (unit,))
    return cleaned


def parse_reading(text):
    """Split a reading such as '98.6 F' or '-40C' into (value, unit)."""
    cleaned = str(text).strip()
    if ' ' not in cleaned:
        index = len(cleaned)
        while index > 0 and cleaned[index - 1] not in '0123456789.':
            index -= 1
        number, unit = cleaned[:index], cleaned[index:]
    else:
        number, unit = cleaned.rsplit(' ', 1)
    return float(number), normalize_unit(unit)


def format_reading(value, unit):
    """Render a temperature with the conventional degree notation."""
    unit = normalize_unit(unit)
    text = "%.2f" % float(value)
    if unit not in DEGREE_UNITS:
        return "%s K" % text
    return u"%s\u00b0%s" % (text, unit)


def to_kelvin(value, unit):
    """Convert a temperature in `unit` to kelvin."""
    if unit == 'C':
        return value + 273.15
    if unit == 'F':
        return (value - 32.0) * 5.0 / 9.0 + 273.15
    return value


def from_kelvin(kelvin, unit):
    """Convert a kelvin temperature to `unit`."""
    if unit == 'C':
        return kelvin - 273.15
    if unit == 'F':
        return (kelvin - 273.15) * 9.0 / 5.0 + 32.0
    return kelvin


def convert_temperature(value, unit_from, unit_to):
    """Convert `value` from `unit_from` to `unit_to` and return a float."""
    source = normalize_unit(unit_from)
    target = normalize_unit(unit_to)
    number = float(value)
    if source == target:
        return number
    return float(from_kelvin(to_kelvin(number, source), target))


def is_physical(value, unit):
    """True when `value` is at or above absolute zero for `unit`."""
    unit = normalize_unit(unit)
    return float(value) >= ABSOLUTE_ZERO[unit] - 1e-9


def conversion_table(value, unit_from):
    """Map every unit other than `unit_from` to the converted value."""
    unit_from = normalize_unit(unit_from)
    table = {}
    for unit in VALID_UNITS:
        if unit != unit_from:
            table[unit] = convert_temperature(value, unit_from, unit)
    return table


def main():
    readings = ["0 C", "273.15 K", "98.6 Fahrenheit", "-500F"]
    targets = ['F', 'C', 'C', 'K']
    for text, unit_to in zip(readings, targets):
        value, unit_from = parse_reading(text)
        if not is_physical(value, unit_from):
            print("%s is below absolute zero" % format_reading(value, unit_from))
            continue
        result = convert_temperature(value, unit_from, unit_to)
        print("%s -> %s" % (format_reading(value, unit_from),
                            format_reading(result, unit_to)))
    for unit, converted in sorted(conversion_table(25.0, 'C').items()):
        print("%s equals %s" % (format_reading(25.0, 'C'),
                                format_reading(converted, unit)))


if __name__ == '__main__':
    main()

