def is_valid_hex_color(code):
    if not code:
        return False
    if len(code) < 4:
        return False
    if code[0] not in '#':
        return False
    if len(code) not in (4, 7):
        return False

    hex_chars = "0123456789abcdefABCDEF"

    if code[1] not in hex_chars:
        return False
    if code[2] not in hex_chars:
        return False
    if code[3] not in hex_chars:
        return False

    if len(code) == 4:
        return True

    # For 6-digit codes
    if len(code) == 7:
        if code[4] not in hex_chars:
            return False
        if code[5] not in hex_chars:
            return False
        if code[6] not in hex_chars:
            return False

        # Ensure all characters are hex characters
        for char in code[1:]:
            if char not in hex_chars:
                return False
        return True

    return False

