ALLOWED_SEQUENCE_TYPES = (list, tuple)
DIRECTIONS = {"right": 1, "left": -1}
DIGITS = "0123456789"


def rotate_list(lst, n):
    """Return a new list with elements rotated n places right (left if n < 0)."""
    if type(lst) not in ALLOWED_SEQUENCE_TYPES:
        raise TypeError("lst must be a list or tuple, got %r" % type(lst).__name__)
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("n must be an integer")
    items = list(lst)
    if not items:
        return items
    shift = n % len(items)
    if shift == 0:
        return items
    return items[-shift:] + items[:-shift]


def parse_int(text):
    """Parse a signed decimal integer, rejecting anything else."""
    token = text.strip()
    body = token[1:] if token[:1] in ("+", "-") else token
    if not body:
        raise ValueError("not an integer: %r" % text)
    for ch in body:
        if ch not in DIGITS:
            raise ValueError("not an integer: %r" % text)
    return int(token)


def parse_items(text):
    """Turn "1, 2, 3" into [1, 2, 3]; non-numeric elements stay as strings."""
    items = []
    for part in text.split(","):
        element = part.strip()
        if not element:
            raise ValueError("empty element in %r" % text)
        try:
            items.append(parse_int(element))
        except ValueError:
            items.append(element)
    return items


def rotate_named(lst, direction, count):
    """Rotate by count places towards 'left' or 'right'."""
    if direction not in DIRECTIONS:
        raise ValueError("unknown direction %r" % direction)
    return rotate_list(lst, DIRECTIONS[direction] * count)


def distinct_rotations(lst):
    """All rotations of lst, in order, without repeats."""
    found = []
    for offset in range(len(lst)):
        candidate = rotate_list(lst, offset)
        if candidate not in found:
            found.append(candidate)
    return found


def run_spec(spec):
    """Execute a rotation request given as a dict of strings."""
    if "items" not in spec:
        raise ValueError("spec is missing the 'items' key")
    items = parse_items(spec["items"])
    if "steps" not in spec:
        return rotate_list(items, 0)
    steps = parse_int(spec["steps"])
    direction = spec.get("direction", "right")
    return rotate_named(items, direction, steps)


def main():
    specs = [
        {"items": "1, 2, 3, 4, 5", "steps": "2"},
        {"items": "1, 2, 3", "steps": "1", "direction": "left"},
        {"items": "a, b, c, d", "steps": "7"},
        {"items": "42"},
    ]
    for spec in specs:
        print("%-22s -> %s" % (spec["items"], run_spec(spec)))
    print("distinct rotations of [1, 1, 1]:", distinct_rotations([1, 1, 1]))
    print("distinct rotations of [1, 2, 3]:", distinct_rotations([1, 2, 3]))


if __name__ == "__main__":
    main()

