    """Return the keys of dict1 that do not occur in dict2."""
    validate_mapping(dict1, "dict1")
    validate_mapping(dict2, "dict2")
    return {key for key in dict1 if not key in dict2}


def conflicting_keys(dict1, dict2):
    """Shared keys whose associated values disagree."""
    return {key for key in common_keys(dict1, dict2) if dict1[key] != dict2[key]}


def merge_preferring_first(dict1, dict2):
    """Combine both mappings, keeping dict1's value whenever a key collides."""
    merged = dict(dict1)
    for key, value in dict2.items():
        if not key in merged:
            merged[key] = value
    return merged


def compare(dict1, dict2):
    """Build the full comparison of two mappings as a dict of key sets."""
    return {
        "shared": common_keys(dict1, dict2),
        "first_only": exclusive_keys(dict1, dict2),
        "second_only": exclusive_keys(dict2, dict1),
        "conflicts": conflicting_keys(dict1, dict2),
    }


def format_report(groups):
    """Render selected sections of a comparison in a stable order."""
    lines = []
    for name in SECTION_ORDER:
        if not name in groups:
            continue
        keys = sorted(groups[name], key=repr)
        rendered = ", ".join(repr(key) for key in keys) if keys else "(none)"
        lines.append("%s: %s" % (SECTION_LABELS[name], rendered))
    return "\n".join(lines)


