    """Map each population count to the numbers that have it."""
    buckets = {}
    for value in numbers:
        weight = count_set_bits(value)
        if weight not in buckets:
            buckets[weight] = []
        buckets[weight].append(value)
    return buckets


def count_set_bits(n):
    """Return the number of '1' bits in the binary representation of n."""
    if not isinstance(n, int):
        raise TypeError("n must be an int, got %s" % type(n).__name__)
    if n < 0:
        raise ValueError("n must be non-negative")
    total = 0
    while n:
