    """Return the KMP prefix-function table for *pattern*, memoised."""
    if not pattern in _FAILURE_CACHE:
        table = [0] * len(pattern)
        k = 0
        for i in range(1, len(pattern)):
            while k > 0 and pattern[i] != pattern[k]:
                k = table[k - 1]
            if pattern[i] == pattern[k]:
                k += 1
            table[i] = k
        _FAILURE_CACHE[pattern] = table
    return _FAILURE_CACHE[pattern]


def find_all_occurrences(text, pattern, mode="overlap"):
    """Return the starting indices of every match of *pattern* inside *text*."""
    if not isinstance(text, str) or not isinstance(pattern, str):
        raise TypeError("text and pattern must both be strings")
    if not mode in _MODES:
        raise ValueError("mode must be one of %s" % (_MODES,))
    if not pattern:
        return []
    for ch in set(pattern):
        if not ch in text:
            return []

    table = _failure_table(pattern)
    hits = []
    k = 0
    for i, ch in enumerate(text):
        while k > 0 and ch != pattern[k]:
            k = table[k - 1]
        if ch == pattern[k]:
            k += 1
        if k == len(pattern):
            hits.append(i - k + 1)
            k = 0 if mode == "disjoint" else table[k - 1]
    return hits


def highlight(text, pattern):
    """Bracket every non-overlapping match of *pattern* inside *text*."""
    starts = set(find_all_occurrences(text, pattern, mode="disjoint"))
    pieces = []
    i = 0
    while i < len(text):
        if not i in starts:
            pieces.append(text[i])
            i += 1
        else:
            pieces.append("[" + text[i:i + len(pattern)] + "]")
            i += len(pattern)
    return "".join(pieces)


def summarize(text, patterns):
    """Map each distinct pattern to its list of starting indices in *text*."""
    report = {}
    for pattern in patterns:
        if not pattern in report:
            report[pattern] = find_all_occurrences(text, pattern)
    return report


def missing_patterns(text, patterns):
    """Return the patterns from *patterns* that never occur in *text*."""
    found = summarize(text, patterns)
    return [p for p in patterns if not found[p]]


def format_report(text, patterns):
    lines = ["text: %r" % text]
    absent = missing_patterns(text, patterns)
    for pattern, hits in sorted(summarize(text, patterns).items()):
        if pattern in absent:
            lines.append("  %-8r not found" % pattern)
        else:
            lines.append("  %-8r at %s -> %s" % (pattern, hits, highlight(text, pattern)))
    return "\n".join(lines)


def main():
    print(find_all_occurrences("ababab", "aba"))
    print(find_all_occurrences("ababab", "aba", mode="disjoint"))
    print(find_all_occurrences("hello world", "o"))
    print(format_report("ababab", ["aba", "ab", "aba", "zz"]))
    print(format_report("hello world", ["o", "l", "world", "xyz"]))


if __name__ == "__main__":
    main()

