DIGITS = "0123456789"
SEPARATORS = " ,;\t\n"

_PRIME_CACHE = {}


def tokenize(text):
    """Split a free-form list of numbers into tokens on any separator."""
    tokens = []
    current = ""
    for char in text:
        if char not in SEPARATORS:
            current += char
        elif current:
            tokens.append(current)
            current = ""
    if current:
        tokens.append(current)
    return tokens


def parse_int(token):
    """Turn a textual token such as '-17' into an int, rejecting junk."""
    if token[0] not in "+-":
        body = token
        sign = 1
    else:
        body = token[1:]
        sign = -1 if token[0] == "-" else 1
    if not body:
        raise ValueError("no digits in %r" % token)
    for char in body:
        if char not in DIGITS:
            raise ValueError("bad character %r in %r" % (char, token))
    return sign * int(body)


def is_prime(n):
    """Return True if n is prime, False otherwise."""
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("is_prime expects an int, got %r" % (n,))
    if n < 2:
        return False
    if n in SMALL_PRIMES:
        return True
    for p in SMALL_PRIMES:
        if n % p == 0:
            return False
    divisor = 37
    while divisor * divisor <= n:
        if n % divisor == 0 or n % (divisor + 4) == 0:
            return False
        divisor += 6
    return True


def cached_is_prime(n):
    """is_prime with memoisation, useful when scanning repeated values."""
    if n not in _PRIME_CACHE:
        _PRIME_CACHE[n] = is_prime(n)
    return _PRIME_CACHE[n]


def distinct_prime_factors(n):
    """Sorted list of the distinct primes dividing abs(n)."""
    remaining = abs(n)
    factors = []
    divisor = 2
    while divisor * divisor <= remaining:
        while remaining % divisor == 0:
            if divisor not in factors:
                factors.append(divisor)
            remaining //= divisor
        divisor += 1 if divisor == 2 else 2
    if remaining > 1:
        factors.append(remaining)
    return factors


def describe(n):
    """One-line human readable verdict for a single number."""
    if cached_is_prime(n):
        return "%d is prime" % n
    if n < 2:
        return "%d is not prime (below 2)" % n
    joined = " * ".join(str(f) for f in distinct_prime_factors(n))
    return "%d is composite, divisible by %s" % (n, joined)


def main():
    raw = "7, 10, 1; -5 0 97 7 561 104729 twelve"
    seen = []
    for token in tokenize(raw):
