INT32_MIN = -2**31
INT32_MAX = 2**31 - 1
DIGITS = "0123456789"

def parse_int(text):
    """Convert a user-supplied string into an int, rejecting junk input."""
    cleaned = text.strip()
    if not cleaned:
        raise ValueError("empty input")
    sign = 1
    if cleaned[0] not in "+-":
        body = cleaned
    else:
        sign = -1 if cleaned[0] == "-" else 1
        body = cleaned[1:]
    if not body:
        raise ValueError("sign without digits")
    for ch in body:
        if ch not in DIGITS:
            raise ValueError("not a decimal integer: %r" % text)
    return sign * int(body)

def reverse_integer(n):
    """Reverse the decimal digits of n, preserving the sign."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("reverse_integer expects an int")
    sign = -1 if n < 0 else 1
    return sign * int(str(abs(n))[::-1])

def classify(n):
    """Describe how the reversal relates to the original number."""
    reversed_value = reverse_integer(n)
    tags = []
    if reversed_value == n:
        tags.append("palindromic")
    if n != 0 and abs(n) % 10 == 0:
        tags.append("trailing-zeros-lost")
    if not INT32_MIN <= reversed_value <= INT32_MAX:
        tags.append("overflow")
    if not tags:
        tags.append("plain")
    return reversed_value, tags

def report(values):
    """Build report lines, the safely reversible total and tag frequencies."""
    lines = []
    seen = []
    total = 0
    counts = {}
    for value in values:
        if value not in seen:
            seen.append(value)
            reversed_value, tags = classify(value)
            if "overflow" not in tags:
                total += value
            for tag in tags:
                if tag not in counts:
                    counts[tag] = 0
                counts[tag] += 1
            lines.append("%12d -> %12d  [%s]" % (value, reversed_value, ", ".join(tags)))
    return lines, total, counts

def main():
    raw_inputs = ["123", " -456 ", "1000", "+1221", "0", "1534236469", "123"]
    values = []
    for raw in raw_inputs:
        try:
