import string

PRINTABLE = frozenset(string.printable)
ALIGNMENTS = ("left", "center", "right")
_LINE_CACHE = {}


def normalize_words(words):
    """Validate the input and return a flat list of whitespace-free tokens."""
    if isinstance(words, str):
        raise TypeError("words must be a list of strings, not a single string")
    normalized = []
    for item in words:
        if not isinstance(item, str):
            raise TypeError("every word must be a string, got %r" % (item,))
        for ch in item:
            if ch not in PRINTABLE:
                raise ValueError("word %r contains a non-printable character" % item)
        normalized.extend(item.split())
    return normalized


def required_width(tokens):
    """Width of the single line holding all tokens separated by one space."""
    if not tokens:
        return 0
    return sum(len(token) for token in tokens) + len(tokens) - 1


def justify_text_simple(words, max_width):
    tokens = normalize_words(words)
    if isinstance(max_width, bool) or not isinstance(max_width, int):
        raise TypeError("max_width must be an integer")
    if max_width <= 0:
        raise ValueError("max_width must be positive")
    key = (tuple(tokens), max_width)
    if key not in _LINE_CACHE:
        needed = required_width(tokens)
        if needed > max_width:
            raise ValueError("needs %d columns but only %d available" % (needed, max_width))
        _LINE_CACHE[key] = " ".join(tokens)
    return _LINE_CACHE[key]


def align_text(words, max_width, alignment="left"):
    """Place the justified line inside a field of max_width columns."""
    if alignment not in ALIGNMENTS:
        raise ValueError("alignment must be one of %s" % (ALIGNMENTS,))
    line = justify_text_simple(words, max_width)
    slack = max_width - len(line)
    if alignment == "right":
        return " " * slack + line
    if alignment == "center":
        left = slack // 2
        return " " * left + line + " " * (slack - left)
    return line


def group_by_length(words):
    """Map each word length to the distinct words having that length."""
    groups = {}
    for token in normalize_words(words):
        size = len(token)
        if size not in groups:
            groups[size] = []
        if token not in groups[size]:
            groups[size].append(token)
    return groups


def describe(words, max_width):
    line = justify_text_simple(words, max_width)
    groups = group_by_length(words)
    details = ["%d:%s" % (size, "/".join(groups[size])) for size in sorted(groups)]
    return "used %d of %d columns; %s" % (len(line), max_width, " ".join(details))


def main():
    samples = [
        (["hello", "world"], 10, "left"),
        (["short", "text"], 20, "center"),
        (["ragged", "right", "edge"], 24, "right"),
        (["overflowing", "sample"], 8, "left"),
    ]
    for words, width, alignment in samples:
        try:
            rendered = align_text(words, width, alignment)
        except ValueError as exc:
            print("skipped %r: %s" % (words, exc))
            continue
        print("|%s|" % rendered)
        print("   " + describe(words, width))


if __name__ == "__main__":
    main()

