SCHEME_SEPARATOR = '://'
KNOWN_SCHEMES = {'http', 'https', 'ftp', 'ftps'}
WWW_ALIASES = {'www', 'www1', 'www2', 'm'}
COMPOUND_TLDS = {'co.uk', 'org.uk', 'ac.uk', 'com.au', 'co.jp', 'com.br'}
ALLOWED_HOST_CHARS = set('abcdefghijklmnopqrstuvwxyz0123456789-.')


def split_scheme(url):
    if SCHEME_SEPARATOR not in url:
        return '', url
    scheme, authority = url.split(SCHEME_SEPARATOR, 1)
    if scheme.lower() not in KNOWN_SCHEMES:
        raise ValueError('unsupported scheme: %r' % scheme)
    return scheme.lower(), authority


def extract_host(authority):
    host = authority
    for separator in ('/', '?', '#'):
        host = host.split(separator, 1)[0]
    if '@' in host:
        host = host.split('@', 1)[1]
    host = host.split(':', 1)[0]
    return host.strip().strip('.').lower()


def validate_host(host):
    if not host:
        raise ValueError('URL contains no host component')
    for character in host:
        if character not in ALLOWED_HOST_CHARS:
            raise ValueError('illegal character %r in host %r' % (character, host))
    if '..' in host:
        raise ValueError('empty label in host %r' % host)


def strip_www(labels):
    if labels[0] not in WWW_ALIASES:
        return labels
    if len(labels) < 2:
        return labels
    return labels[1:]


def strip_tld(labels):
    if len(labels) > 2 and '.'.join(labels[-2:]) in COMPOUND_TLDS:
        return labels[:-2]
    if len(labels) > 1:
        return labels[:-1]
    return labels


def extract_domain(url):
    _, authority = split_scheme(url)
    host = extract_host(authority)
    validate_host(host)
    labels = strip_tld(strip_www(host.split('.')))
    return labels[-1]


def report(urls):
    lines = []
    seen = []
    for url in urls:
        try:
            domain = extract_domain(url)
        except ValueError as error:
            lines.append('%-40s -> error: %s' % (url, error))
            continue
        if domain not in seen:
            seen.append(domain)
        lines.append('%-40s -> %s' % (url, domain))
    lines.append('distinct domains: %s' % ', '.join(seen))
    return '\n'.join(lines)


def main():
    samples = [
        'http://www.google.com/search',
        'https://blog.openai.org/post',
        'ftp://files.example.co.uk:21/pub',
        'localhost',
        'https://user:pass@m.wikipedia.org/wiki/Main_Page',
        'gopher://old.example.net',
        'https:// spaced.example.com',
    ]
    print(report(samples))


if __name__ == '__main__':
    main()

