DIGITS = "0123456789"
SEPARATORS = " -\t"
KNOWN_ISSUERS = ("GBR", "USA", "DEU", "FRA", "JPN")
REQUIRED_FIELDS = ("issuer", "passport")


def is_valid_passport_number(number):
    """Return True if number is a string of exactly 9 digits."""
    if not isinstance(number, str):
        return False
    if len(number) != 9:
        return False
    for ch in number:
        if ch not in DIGITS:
            return False
    return True


def normalize(raw):
    """Strip common separators so user-typed numbers can be checked."""
    cleaned = []
    for ch in raw.strip():
        if ch not in SEPARATORS:
            cleaned.append(ch)
    return "".join(cleaned)


def describe(number):
    """Explain why a candidate number is rejected, or confirm it."""
    cleaned = normalize(number)
    bad = [ch for ch in cleaned if ch not in DIGITS]
    if bad:
        return "invalid: contains non-digit characters " + ", ".join(sorted(set(bad)))
    if len(cleaned) < 9:
        return "invalid: too short (%d of 9 digits)" % len(cleaned)
    if len(cleaned) > 9:
        return "invalid: too long (%d of 9 digits)" % len(cleaned)
    return "valid"


def validate_record(record):
    """Validate a {'issuer': ..., 'passport': ...} mapping, returning problems."""
    problems = []
    for field in REQUIRED_FIELDS:
        if field not in record:
            problems.append("missing field: " + field)
    if not problems:
        issuer = str(record["issuer"]).upper()
        if issuer not in KNOWN_ISSUERS:
            problems.append("unknown issuer: " + issuer)
        number = normalize(str(record["passport"]))
        if not is_valid_passport_number(number):
            problems.append("passport " + describe(number))
    return problems


def report(records):
    lines = []
    for index, record in enumerate(records, start=1):
        problems = validate_record(record)
        if problems:
            lines.append("record %d: rejected" % index)
            for problem in problems:
                lines.append("    " + problem)
        else:
            lines.append("record %d: accepted (%s)" % (index, record["issuer"]))
    return "\n".join(lines)


def main():
    samples = [
        {"issuer": "GBR", "passport": "123456789"},
        {"issuer": "usa", "passport": "12345678"},
        {"issuer": "FRA", "passport": "1234 5678 9"},
        {"issuer": "XXX", "passport": "12345678A"},
        {"issuer": "JPN"},
    ]
    print(report(samples))


if __name__ == "__main__":
    main()

