from datetime import datetime

VALID_LEVELS = ("DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL")
ALERT_LEVELS = ("ERROR", "CRITICAL")


def parse_log_line(line):
    """Parse 'YYYY-MM-DD HH:MM:SS LEVEL: MESSAGE' into a dictionary."""
    if not isinstance(line, str):
        raise TypeError("log line must be a string")
    parts = line.strip().split(" ", 2)
    if len(parts) < 3:
        raise ValueError("malformed log line: too few fields")
    date_part, time_part, rest = parts
    timestamp = date_part + " " + time_part
    try:
        datetime.strptime(timestamp, "%Y-%m-%d %H:%M:%S")
    except ValueError:
        raise ValueError("invalid timestamp: %r" % timestamp)
    if ":" not in rest:
        raise ValueError("malformed log line: missing level separator")
    level, _separator, message = rest.partition(":")
    level = level.strip().upper()
    if level not in VALID_LEVELS:
        raise ValueError("unknown log level: %r" % level)
    return {"timestamp": timestamp, "level": level, "message": message.strip()}


def parse_log(lines):
    """Parse many lines, skipping blanks; returns (records, errors)."""
    records = []
    errors = []
    for number, raw in enumerate(lines, start=1):
        if raw.strip() == "":
            continue
        try:
            records.append(parse_log_line(raw))
        except (TypeError, ValueError) as exc:
            errors.append((number, str(exc)))
    return records, errors


def count_levels(records):
    """Tally how many records carry each log level."""
    counts = {}
    for record in records:
        level = record["level"]
        if level not in counts:
            counts[level] = 0
        counts[level] += 1
    return counts


def format_report(records, errors):
    """Build a human readable summary of a parsed log."""
    counts = count_levels(records)
    lines = ["Parsed %d record(s)" % len(records)]
    for level in VALID_LEVELS:
        if level not in counts:
            continue
        lines.append("  %-8s %d" % (level, counts[level]))
    for record in records:
        if record["level"] not in ALERT_LEVELS:
            continue
        lines.append("  ! %s %s" % (record["timestamp"], record["message"]))
    for number, reason in errors:
        lines.append("  line %d rejected: %s" % (number, reason))
    return "\n".join(lines)


def main():
    sample = [
        "2023-10-26 14:30:00 INFO: User logged in.",
        "2023-10-26 14:35:15 ERROR: File not found.",
        "",
        "2023-10-26 14:36:02 WARNING: Disk usage at 91%.",
        "2023-10-26 14:37:00 TRACE: unsupported level",
        "not a log line",
    ]
    records, errors = parse_log(sample)
    print(format_report(records, errors))


if __name__ == "__main__":
    main()

