def parse_time(token):
    """Parse a clock time ("9:30") or a plain number ("9.5") into minutes/units."""
    token = token.strip()
    if ":" not in token:
        for ch in token:
            if ch not in "0123456789.":
                raise ValueError("bad time value: %r" % token)
        return float(token)
    hours, minutes = token.split(":", 1)
    if not hours.isdigit() or not minutes.isdigit():
        raise ValueError("bad clock time: %r" % token)
    return int(hours) * 60 + int(minutes)


def parse_interval(text):
    """Parse "9:00-10:30" into a validated (start, end) tuple."""
    if "-" not in text:
        raise ValueError("interval must look like START-END: %r" % text)
    start_text, end_text = text.split("-", 1)
    interval = (parse_time(start_text), parse_time(end_text))
    validate_interval(interval)
    return interval


def validate_interval(interval):
    if type(interval) not in (tuple, list):
        raise TypeError("interval must be a tuple or list")
    if len(interval) != 2:
        raise ValueError("interval must hold exactly two values")
    for value in interval:
        if type(value) not in (int, float):
            raise TypeError("interval bounds must be numbers")
    if interval[0] > interval[1]:
        raise ValueError("start_time must not exceed end_time")


def check_interval_overlap(interval1, interval2):
    validate_interval(interval1)
    validate_interval(interval2)
    return interval1[0] <= interval2[1] and interval2[0] <= interval1[1]


def merge_intervals(intervals):
    ordered = sorted(intervals, key=lambda iv: (iv[0], iv[1]))
    merged = []
    for interval in ordered:
        validate_interval(interval)
        if merged and check_interval_overlap(merged[-1], interval):
            last = merged.pop()
            merged.append((last[0], max(last[1], interval[1])))
        else:
            merged.append(tuple(interval))
    return merged


def find_conflicts(schedule):
    """Return every unordered pair of schedule entries whose intervals overlap."""
    conflicts = []
    reported = set()
    for name_a, interval_a in schedule.items():
        for name_b, interval_b in schedule.items():
            key = tuple(sorted((name_a, name_b)))
            if name_a == name_b or key in reported:
                continue
            reported.add(key)
            if check_interval_overlap(interval_a, interval_b):
                conflicts.append(key)
    return conflicts


def free_slots(window, busy):
    gaps = []
    cursor = window[0]
    for start, end in merge_intervals(busy):
        if start > cursor:
            gaps.append((cursor, min(start, window[1])))
        cursor = max(cursor, end)
        if cursor >= window[1]:
            break
    if cursor < window[1]:
        gaps.append((cursor, window[1]))
    return gaps


def format_time(value):
    total = int(round(value))
    return "%02d:%02d" % (total // 60, total % 60)


def report(schedule, order):
    lines = []
    for name in order:
        if name not in schedule:
            lines.append("%s: no booking" % name)
            continue
        start, end = schedule[name]
        lines.append("%s: %s-%s" % (name, format_time(start), format_time(end)))
    return lines


def main():
    raw = {"ana": "9:00-10:30", "ben": "10:00-11:00", "cleo": "11:30-12:15"}
    schedule = {name: parse_interval(text) for name, text in raw.items()}
    for line in report(schedule, ["ana", "ben", "cleo", "dan"]):
        print(line)
    for name_a, name_b in find_conflicts(schedule):
        print("conflict: %s and %s" % (name_a, name_b))
    day = (parse_time("8:00"), parse_time("13:00"))
    for start, end in free_slots(day, list(schedule.values())):
        print("free: %s-%s" % (format_time(start), format_time(end)))
    print(check_interval_overlap((1, 5), (3, 7)))
    print(check_interval_overlap((1, 5), (6, 10)))


if __name__ == "__main__":
    main()

