DIGITS = "0123456789"

REGIONS = {
    "0": "Northeast",
    "1": "Mid-Atlantic",
    "2": "Southeast",
    "3": "Deep South",
    "4": "Great Lakes",
    "5": "Upper Midwest",
    "6": "Central Plains",
    "7": "South Central",
    "8": "Mountain",
    "9": "Pacific",
}


def is_valid_us_zip_code(code):
    """Return True if code is a string of exactly five digits."""
    if not isinstance(code, str):
        return False
    if len(code) != 5:
        return False
    for ch in code:
        if ch not in DIGITS:
            return False
    return True


def normalize(raw):
    """Strip surrounding whitespace and drop a well-formed ZIP+4 extension."""
    text = raw.strip()
    if "-" not in text:
        return text
    base, _, extension = text.partition("-")
    if len(extension) != 4:
        return text
    for ch in extension:
        if ch not in DIGITS:
            return text
    return base


def classify(raw):
    """Describe why a raw entry is accepted or rejected."""
    candidate = normalize(raw)
    if is_valid_us_zip_code(candidate):
        return "valid"
    if candidate == "":
        return "empty"
    bad = [ch for ch in candidate if ch not in DIGITS]
    if bad:
        return "non-digit characters: " + "".join(sorted(set(bad)))
    if len(candidate) < 5:
        return "too short (%d digits)" % len(candidate)
    return "too long (%d digits)" % len(candidate)


def region_of(code):
    """Very rough region lookup based on the first digit of a valid ZIP."""
    return REGIONS[code[0]]


def summarize(entries):
    """Count accepted entries per region, preserving first-seen order."""
    counts = {}
    for raw in entries:
        candidate = normalize(raw)
        if is_valid_us_zip_code(candidate):
            region = region_of(candidate)
            if region not in counts:
                counts[region] = 0
            counts[region] += 1
    return counts


def report(entries):
    """Build a printable report line for each raw entry."""
    lines = []
    seen = set()
    for raw in entries:
        candidate = normalize(raw)
        status = classify(raw)
        if status != "valid":
            lines.append("%-12s REJECTED (%s)" % (repr(raw), status))
        elif candidate not in seen:
            seen.add(candidate)
            lines.append("%-12s OK       %s" % (repr(raw), region_of(candidate)))
        else:
            lines.append("%-12s OK       duplicate" % repr(raw))
    return lines


def main():
    entries = ["90210", "1234", " 02134 ", "12345-6789", "abcde", "90210", "1234567", ""]
    for line in report(entries):
        print(line)
    for region, count in summarize(entries).items():
        print("%-14s %d" % (region, count))


if __name__ == "__main__":
    main()

