import re
import sys

TOKEN_PATTERN = re.compile(r"\w+", re.UNICODE)


def normalize_bad_words(bad_words):
    """Return a lower-cased, de-duplicated list of usable censor targets."""
    normalized = []
    for raw in bad_words:
        if not isinstance(raw, str):
            raise TypeError("bad words must be strings, got %r" % (raw,))
        word = raw.strip().lower()
        if not word:
            continue
        if word not in normalized:
            normalized.append(word)
    return normalized


def censor_text(text, bad_words):
    """Replace every case-insensitive occurrence of a bad word with asterisks."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    banned = set(normalize_bad_words(bad_words))
    if not banned:
        return text
    pieces = []
    cursor = 0
    for match in TOKEN_PATTERN.finditer(text):
        token = match.group(0)
        if token.lower() not in banned:
            continue
        pieces.append(text[cursor:match.start()])
        pieces.append("*" * len(token))
        cursor = match.end()
    pieces.append(text[cursor:])
    return "".join(pieces)


def count_occurrences(text, bad_words):
    """Map each bad word to how many times it appears in the text."""
    banned = set(normalize_bad_words(bad_words))
    counts = {}
    for match in TOKEN_PATTERN.finditer(text):
        token = match.group(0).lower()
        if token not in banned:
            continue
        counts[token] = counts.get(token, 0) + 1
    return counts


def merge_counts(totals, counts):
    """Accumulate per-word hit counts coming from several texts."""
    for word, hits in counts.items():
        if word not in totals:
            totals[word] = hits
        else:
            totals[word] += hits
    return totals


def build_report(text, bad_words):
    """Produce human readable lines describing the censoring of one text."""
    counts = count_occurrences(text, bad_words)
    lines = ["censored: " + censor_text(text, bad_words)]
    for word in normalize_bad_words(bad_words):
        if word not in counts:
            lines.append("  %s: not present" % word)
        else:
            lines.append("  %s: %d hit(s)" % (word, counts[word]))
    return lines


def main(argv):
    if len(argv) < 2:
        print("usage: %s word[,word...] [text ...]" % argv[0], file=sys.stderr)
        return 2
    words = argv[1].split(",")
    if len(argv) > 2:
        texts = argv[2:]
    else:
        texts = [line.rstrip("\n") for line in sys.stdin]
    totals = {}
    for text in texts:
        for line in build_report(text, words):
            print(line)
        merge_counts(totals, count_occurrences(text, words))
    unseen = [w for w in normalize_bad_words(words) if w not in totals]
    print("total hits: %d" % sum(totals.values()))
    if unseen:
        print("never seen: %s" % ", ".join(unseen))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

